@dataclass(frozen=True)
class RangeBandContract:
    """Pre-registered physical range zones for one holdout grid."""

    case_id: str
    range_regime_labels: tuple[str, ...]
    range_band_mask_digests: tuple[str, ...]
    reference_active_range_regimes: tuple[str, ...]
    grid_contract_digest: str
    range_geometry_contract_digest: str
    dynamic_source_resolution: bool = False
    registered_active_range_regime_sets: tuple[tuple[str, ...], ...] = ()
    contract: str = "neural-prior-range-band-contract-v3"
    contract_digest: str = field(init=False)

    def __post_init__(self) -> None:
        if (
            self.contract != "neural-prior-range-band-contract-v3"
            or not self.case_id
            or self.case_id.strip() != self.case_id
            or not self.range_regime_labels
            or len(set(self.range_regime_labels)) != len(self.range_regime_labels)
            or any(not value or value.strip() != value for value in self.range_regime_labels)
            or len(set(self.reference_active_range_regimes))
            != len(self.reference_active_range_regimes)
            or any(
                value not in self.range_regime_labels
                for value in self.reference_active_range_regimes
            )
        ):
            raise ValueError("range-band contract is invalid")
        registered_sets = self.registered_active_range_regime_sets
        if not registered_sets and not self.dynamic_source_resolution:
            registered_sets = (self.reference_active_range_regimes,)
            object.__setattr__(
                self,
                "registered_active_range_regime_sets",
                registered_sets,
            )
        if (
            not registered_sets
            or len(set(registered_sets)) != len(registered_sets)
            or any(
                not values
                or tuple(sorted(values)) != values
                or len(set(values)) != len(values)
                or any(value not in self.range_regime_labels for value in values)
                for values in registered_sets
            )
            or (
                self.dynamic_source_resolution
                and (
                    self.range_band_mask_digests
                    or self.reference_active_range_regimes
                )
            )
            or (
                not self.dynamic_source_resolution
                and (
                    len(self.range_band_mask_digests)
                    != len(self.range_regime_labels)
                    or registered_sets != (self.reference_active_range_regimes,)
                )
            )
        ):
            raise ValueError("range-band source-resolution contract is invalid")
        _require_digest("range-band grid contract", self.grid_contract_digest)
        _require_digest(
            "range geometry contract", self.range_geometry_contract_digest
        )
        for digest in self.range_band_mask_digests:
            _require_digest("range-band mask digest", digest)
        object.__setattr__(self, "contract_digest", json_digest(self.payload))

    @property
    def payload(self) -> dict[str, object]:
        return {
            "contract": self.contract,
            "case_id": self.case_id,
            "range_regime_labels": list(self.range_regime_labels),
            "range_band_mask_digests": list(self.range_band_mask_digests),
            "reference_active_range_regimes": list(
                self.reference_active_range_regimes
            ),
            "grid_contract_digest": self.grid_contract_digest,
            "range_geometry_contract_digest": (
                self.range_geometry_contract_digest
            ),
            "dynamic_source_resolution": self.dynamic_source_resolution,
            "registered_active_range_regime_sets": [
                list(values)
                for values in self.registered_active_range_regime_sets
            ],
        }

    def mask_digest(self, range_regime: str) -> str:
        if self.dynamic_source_resolution:
            raise ValueError("dynamic mosaic range masks resolve after issuance")
        try:
            index = self.range_regime_labels.index(range_regime)
        except ValueError as error:
            raise ValueError("range regime is outside the physical contract") from error
        return self.range_band_mask_digests[index]


def _validate_complete_range_partition(
    range_band_masks: dict[str, Tensor],
    *,
    valid_range_domain_mask: Tensor | None = None,
) -> None:
    """Require one band on the valid range domain and none outside it."""

    masks = tuple(range_band_masks.values())
    if (
        not masks
        or any(mask.dtype is not torch.bool or mask.ndim != 2 for mask in masks)
        or any(
            mask.shape != masks[0].shape or mask.device != masks[0].device
            for mask in masks[1:]
        )
    ):
        raise ValueError("range-band masks are not a complete partition")
    membership = torch.stack(tuple(mask.to(torch.int8) for mask in masks)).sum(
        dim=0
    )
    domain = (
        torch.ones_like(masks[0], dtype=torch.bool)
        if valid_range_domain_mask is None
        else valid_range_domain_mask
    )
    if (
        domain.dtype is not torch.bool
        or domain.shape != masks[0].shape
        or domain.device != masks[0].device
        or not torch.equal(membership, domain.to(torch.int8))
    ):
        raise ValueError("range-band masks are not a complete partition")


@dataclass(frozen=True)
class OperationalIssuanceDomainPlan:
    """Candidate-independent definition of cells that may be published."""

    case_id: str
    grid_contract_digest: str
    radar_source_contract_digest: str
    lead_minutes: tuple[int, ...]
    publication_policy_digest: str
    source_coverage_policy_digest: str
    permanent_exclusion_policy_digest: str
    publication_eligible_mask_digest: str
    source_coverage_mask_digest: str
    permanent_exclusion_mask_digest: str
    radar_source_kind: Literal["single_site", "mosaic"] = "single_site"
    source_radar_registry_digest: str | None = None
    source_radar_count: int | None = None
    data_ingestor_id: str | None = None
    data_ingestor_public_key_hex: str | None = None
    contract: str = "operational-issuance-domain-plan-v2"
    plan_digest: str = field(init=False)

    def __post_init__(self) -> None:
        if (
            self.contract not in {
                "operational-issuance-domain-plan-v1",
                "operational-issuance-domain-plan-v2",
            }
            or not self.case_id
            or self.case_id.strip() != self.case_id
            or not self.lead_minutes
            or len(set(self.lead_minutes)) != len(self.lead_minutes)
            or any(type(value) is not int or value <= 0 for value in self.lead_minutes)
        ):
            raise ValueError("operational issuance-domain plan is invalid")
        for name in (
            "grid_contract_digest",
            "radar_source_contract_digest",
            "publication_policy_digest",
            "source_coverage_policy_digest",
            "permanent_exclusion_policy_digest",
            "publication_eligible_mask_digest",
            "source_coverage_mask_digest",
            "permanent_exclusion_mask_digest",
        ):
            _require_digest(name, getattr(self, name))
        dynamic_values = (
            self.source_radar_registry_digest,
            self.source_radar_count,
            self.data_ingestor_id,
            self.data_ingestor_public_key_hex,
        )
        if self.contract == "operational-issuance-domain-plan-v1":
            if self.radar_source_kind != "single_site" or any(
                value is not None for value in dynamic_values
            ):
                raise ValueError("legacy issuance-domain plans are static")
        elif self.radar_source_kind == "mosaic":
            if (
                self.source_radar_registry_digest is None
                or self.source_radar_count is None
                or type(self.source_radar_count) is not int
                or self.source_radar_count <= 0
                or self.data_ingestor_id is None
                or not self.data_ingestor_id
                or self.data_ingestor_public_key_hex is None
            ):
                raise ValueError("mosaic issuance-domain trust is incomplete")
            _require_digest(
                "source radar registry", self.source_radar_registry_digest
            )
            try:
                Ed25519PublicKey.from_public_bytes(
                    bytes.fromhex(self.data_ingestor_public_key_hex)
                )
            except (ValueError, TypeError) as error:
                raise ValueError("data ingestor public key is invalid") from error
        elif any(value is not None for value in dynamic_values):
            raise ValueError("single-site issuance-domain plan is not dynamic")
        object.__setattr__(self, "plan_digest", json_digest(self.payload))

    @property
    def payload(self) -> dict[str, object]:
        return {
            key: (list(value) if key == "lead_minutes" else value)
            for key, value in self.__dict__.items()
            if key != "plan_digest"
        }


@dataclass(frozen=True, init=False)
class ResolvedSourceCoverageArtifact:
    """Input-time mosaic/outage/QC resolution of nominal source coverage."""

    _resolved_mask: Tensor
    _source_radar_index_map: Tensor
    _input_history_source_radar_index_map: Tensor
    _outage_mask: Tensor
    _dynamic_qc_valid_mask: Tensor
    _nominal_source_coverage_mask: Tensor
    issuance_domain_plan_digest: str
    case_id: str
    grid_contract_digest: str
    radar_source_contract_digest: str
    source_coverage_policy_digest: str
    input_bundle_digest: str
    full_analysis_input_digest: str
    input_available_at: str
    resolved_at: str
    decision_deadline: str
    publication_time: str
    source_radar_registry_digest: str
    source_radar_site_digests: tuple[str, ...]
    source_radar_count: int
    source_selection_policy_digest: str
    data_ingestor_id: str
    data_ingestor_public_key_hex: str
    source_radar_index_map_digest: str
    input_history_source_radar_index_map_digest: str
    outage_mask_digest: str
    dynamic_qc_valid_mask_digest: str
    nominal_source_coverage_mask_digest: str
    resolved_source_coverage_mask_digest: str
    resolved_cell_counts: tuple[int, ...]
    data_ingestor_signature_hex: str
    contract: str = "resolved-source-coverage-artifact-v3"
    artifact_digest: str = field(init=False)

    def __init__(self) -> None:
        raise TypeError("use ResolvedSourceCoverageArtifact.from_observations")

    @classmethod
    def from_observations(
        cls,
        plan: OperationalIssuanceDomainPlan,
        input_plan: NeuralPriorInputPlan,
        source_registry: SourceRadarRegistry,
        *,
        nominal_source_coverage_mask: Tensor,
        source_radar_index_map: Tensor,
        outage_mask: Tensor,
        dynamic_qc_valid_mask: Tensor,
        input_bundle_digest: str,
        full_analysis_input_digest: str,
        resolved_at: str,
        data_ingestor_id: str,
        data_ingestor_private_key: Ed25519PrivateKey,
        input_history_source_radar_index_map: Tensor | None = None,
    ) -> ResolvedSourceCoverageArtifact:
        masks = (outage_mask, dynamic_qc_valid_mask)
        source_history = (
            source_radar_index_map.unsqueeze(0).expand(
                len(input_plan.valid_times), -1, -1
            ).clone()
            if input_history_source_radar_index_map is None
            else input_history_source_radar_index_map
        )
        if (
            nominal_source_coverage_mask.dtype is not torch.bool
            or nominal_source_coverage_mask.ndim != 3
            or any(mask.dtype is not torch.bool or mask.ndim != 2 for mask in masks)
            or not source_radar_index_map.dtype in (
                torch.int8,
                torch.int16,
                torch.int32,
                torch.int64,
            )
            or source_radar_index_map.ndim != 2
            or source_history.dtype != source_radar_index_map.dtype
            or source_history.ndim != 3
            or source_history.shape
            != (len(input_plan.valid_times), *source_radar_index_map.shape)
            or source_history.device != source_radar_index_map.device
            or any(mask.shape != source_radar_index_map.shape for mask in masks)
            or nominal_source_coverage_mask.shape[1:]
            != source_radar_index_map.shape
            or any(mask.device != source_radar_index_map.device for mask in masks)
            or nominal_source_coverage_mask.device
            != source_radar_index_map.device
            or nominal_source_coverage_mask.shape[0] != len(plan.lead_minutes)
            or tensor_digest(nominal_source_coverage_mask)
            != plan.source_coverage_mask_digest
            or plan.radar_source_kind != "mosaic"
            or plan.source_radar_registry_digest
            != source_registry.registry_digest
            or plan.source_radar_count != len(source_registry.radar_site_digests)
            or plan.source_coverage_policy_digest
            != source_registry.source_selection_policy_digest
            or plan.data_ingestor_id != data_ingestor_id
            or plan.data_ingestor_public_key_hex
            != data_ingestor_private_key.public_key()
            .public_bytes(
                encoding=serialization.Encoding.Raw,
                format=serialization.PublicFormat.Raw,
            )
            .hex()
            or input_plan.plan_digest == ""
            or input_plan.grid_contract_digest != plan.grid_contract_digest
            or input_plan.input_available_time == ""
        ):
            raise ValueError("resolved source-coverage inputs are invalid")
        if not bool(
            torch.all(
                (source_radar_index_map == -1)
                | (
                    (source_radar_index_map >= 0)
                    & (source_radar_index_map < len(source_registry.radar_site_digests))
                )
            )
        ):
            raise ValueError("source index is outside the registered radar set")
        if not bool(
            torch.all(
                (source_history == -1)
                | (
                    (source_history >= 0)
                    & (source_history < len(source_registry.radar_site_digests))
                )
            )
        ):
            raise ValueError("input-history source index is outside the registry")
        _require_digest("input bundle", input_bundle_digest)
        _require_digest("full analysis input", full_analysis_input_digest)
        input_time = datetime.fromisoformat(
            input_plan.input_available_time.replace("Z", "+00:00")
        )
        resolution_time = datetime.fromisoformat(
            _canonical_time(resolved_at).replace("Z", "+00:00")
        )
        deadline = datetime.fromisoformat(
            input_plan.decision_deadline.replace("Z", "+00:00")
        )
        if not input_time <= resolution_time <= deadline:
            raise ValueError("source coverage resolution is outside its issue window")
        input_source = (
            (source_radar_index_map >= 0) & ~masks[0] & masks[1]
        )
        resolved = nominal_source_coverage_mask & input_source.unsqueeze(0)
        counts = tuple(
            int(value)
            for value in torch.count_nonzero(resolved, dim=(-2, -1)).tolist()
        )
        if any(value <= 0 for value in counts):
            raise ValueError("resolved source coverage is empty")
        canonical_resolved_at = _canonical_time(resolved_at)
        unsigned: dict[str, object] = {
            "_resolved_mask": resolved.detach().clone(),
            "_source_radar_index_map": source_radar_index_map.detach().clone(),
            "_input_history_source_radar_index_map": (
                source_history.detach().clone()
            ),
            "_outage_mask": masks[0].detach().clone(),
            "_dynamic_qc_valid_mask": masks[1].detach().clone(),
            "_nominal_source_coverage_mask": (
                nominal_source_coverage_mask.detach().clone()
            ),
            "issuance_domain_plan_digest": plan.plan_digest,
            "case_id": plan.case_id,
            "grid_contract_digest": plan.grid_contract_digest,
            "radar_source_contract_digest": plan.radar_source_contract_digest,
            "source_coverage_policy_digest": plan.source_coverage_policy_digest,
            "input_bundle_digest": input_bundle_digest,
            "full_analysis_input_digest": full_analysis_input_digest,
            "input_available_at": input_plan.input_available_time,
            "resolved_at": canonical_resolved_at,
            "decision_deadline": input_plan.decision_deadline,
            "publication_time": input_plan.publication_time,
            "source_radar_registry_digest": source_registry.registry_digest,
            "source_radar_site_digests": source_registry.radar_site_digests,
            "source_radar_count": len(source_registry.radar_site_digests),
            "source_selection_policy_digest": (
                source_registry.source_selection_policy_digest
            ),
            "data_ingestor_id": data_ingestor_id,
            "data_ingestor_public_key_hex": (
                data_ingestor_private_key.public_key()
                .public_bytes(
                    encoding=serialization.Encoding.Raw,
                    format=serialization.PublicFormat.Raw,
                )
                .hex()
            ),
            "source_radar_index_map_digest": tensor_digest(
                source_radar_index_map
            ),
            "input_history_source_radar_index_map_digest": tensor_digest(
                source_history
            ),
            "outage_mask_digest": tensor_digest(outage_mask),
            "dynamic_qc_valid_mask_digest": tensor_digest(
                dynamic_qc_valid_mask
            ),
            "nominal_source_coverage_mask_digest": tensor_digest(
                nominal_source_coverage_mask
            ),
            "resolved_source_coverage_mask_digest": tensor_digest(resolved),
            "resolved_cell_counts": counts,
            "contract": "resolved-source-coverage-artifact-v3",
        }
        signature_payload = {
            key: value
            for key, value in unsigned.items()
            if not key.startswith("_")
        }
        unsigned["data_ingestor_signature_hex"] = (
            data_ingestor_private_key.sign(
                json.dumps(
                    signature_payload,
                    sort_keys=True,
                    separators=(",", ":"),
                ).encode("utf-8")
            ).hex()
        )
        result = object.__new__(cls)
        for name, value in unsigned.items():
            object.__setattr__(result, name, value)
        object.__setattr__(result, "artifact_digest", json_digest(result.payload))
        validate_resolved_source_coverage_artifact(result)
        return result

    @property
    def payload(self) -> dict[str, object]:
        return {
            key: (list(value) if isinstance(value, tuple) else value)
            for key, value in self.__dict__.items()
            if not key.startswith("_") and key != "artifact_digest"
        }

    @property
    def resolved_mask(self) -> Tensor:
        return self._resolved_mask.detach().clone()

    @property
    def source_radar_index_map(self) -> Tensor:
        return self._source_radar_index_map.detach().clone()

    @property
    def input_history_source_radar_index_map(self) -> Tensor:
        return self._input_history_source_radar_index_map.detach().clone()

    @property
    def outage_mask(self) -> Tensor:
        return self._outage_mask.detach().clone()

    @property
    def dynamic_qc_valid_mask(self) -> Tensor:
        return self._dynamic_qc_valid_mask.detach().clone()


def validate_resolved_source_coverage_artifact(
    artifact: ResolvedSourceCoverageArtifact,
) -> None:
    try:
        expected_resolved = (
            artifact._nominal_source_coverage_mask
            & (
                (artifact._source_radar_index_map >= 0)
                & ~artifact._outage_mask
                & artifact._dynamic_qc_valid_mask
            ).unsqueeze(0)
        )
        counts = tuple(
            int(value)
            for value in torch.count_nonzero(
                artifact._resolved_mask,
                dim=(-2, -1),
            ).tolist()
        )
        if (
            artifact.contract != "resolved-source-coverage-artifact-v3"
            or artifact._resolved_mask.dtype is not torch.bool
            or artifact._resolved_mask.ndim != 3
            or artifact._source_radar_index_map.ndim != 2
            or artifact._input_history_source_radar_index_map.ndim != 3
            or artifact._input_history_source_radar_index_map.dtype
            != artifact._source_radar_index_map.dtype
            or artifact._input_history_source_radar_index_map.shape[1:]
            != artifact._source_radar_index_map.shape
            or artifact._input_history_source_radar_index_map.device
            != artifact._source_radar_index_map.device
            or artifact._source_radar_index_map.dtype not in (
                torch.int8,
                torch.int16,
                torch.int32,
                torch.int64,
            )
            or artifact._outage_mask.dtype is not torch.bool
            or artifact._dynamic_qc_valid_mask.dtype is not torch.bool
            or artifact._nominal_source_coverage_mask.dtype is not torch.bool
            or artifact._outage_mask.shape
            != artifact._source_radar_index_map.shape
            or artifact._dynamic_qc_valid_mask.shape
            != artifact._source_radar_index_map.shape
            or artifact._nominal_source_coverage_mask.shape
            != artifact._resolved_mask.shape
            or artifact._resolved_mask.shape[1:]
            != artifact._source_radar_index_map.shape
            or not torch.equal(expected_resolved, artifact._resolved_mask)
            or not bool(
                torch.all(
                    (artifact._source_radar_index_map == -1)
                    | (
                        (artifact._source_radar_index_map >= 0)
                        & (
                            artifact._source_radar_index_map
                            < artifact.source_radar_count
                        )
                    )
                )
            )
            or tensor_digest(artifact._source_radar_index_map)
            != artifact.source_radar_index_map_digest
            or tensor_digest(artifact._input_history_source_radar_index_map)
            != artifact.input_history_source_radar_index_map_digest
            or not bool(
                torch.all(
                    (artifact._input_history_source_radar_index_map == -1)
                    | (
                        (artifact._input_history_source_radar_index_map >= 0)
                        & (
                            artifact._input_history_source_radar_index_map
                            < artifact.source_radar_count
                        )
                    )
                )
            )
            or tensor_digest(artifact._outage_mask) != artifact.outage_mask_digest
            or tensor_digest(artifact._dynamic_qc_valid_mask)
            != artifact.dynamic_qc_valid_mask_digest
            or tensor_digest(artifact._nominal_source_coverage_mask)
            != artifact.nominal_source_coverage_mask_digest
            or tensor_digest(artifact._resolved_mask)
            != artifact.resolved_source_coverage_mask_digest
            or counts != artifact.resolved_cell_counts
            or any(value <= 0 for value in counts)
            or not datetime.fromisoformat(
                _canonical_time(artifact.input_available_at).replace("Z", "+00:00")
            )
            <= datetime.fromisoformat(
                _canonical_time(artifact.resolved_at).replace("Z", "+00:00")
            )
            <= datetime.fromisoformat(
                _canonical_time(artifact.decision_deadline).replace("Z", "+00:00")
            )
            < datetime.fromisoformat(
                _canonical_time(artifact.publication_time).replace("Z", "+00:00")
            )
            or artifact.source_radar_count <= 0
            or artifact.source_radar_count
            != len(artifact.source_radar_site_digests)
            or SourceRadarRegistry(
                radar_site_digests=artifact.source_radar_site_digests,
                source_selection_policy_digest=(
                    artifact.source_selection_policy_digest
                ),
            ).registry_digest
            != artifact.source_radar_registry_digest
            or artifact.artifact_digest != json_digest(artifact.payload)
        ):
            raise ValueError("resolved source-coverage artifact is invalid")
        for name in (
            "issuance_domain_plan_digest",
            "grid_contract_digest",
            "radar_source_contract_digest",
            "source_coverage_policy_digest",
            "input_bundle_digest",
            "full_analysis_input_digest",
            "source_radar_index_map_digest",
            "input_history_source_radar_index_map_digest",
            "outage_mask_digest",
            "dynamic_qc_valid_mask_digest",
            "nominal_source_coverage_mask_digest",
            "resolved_source_coverage_mask_digest",
            "source_radar_registry_digest",
            "source_selection_policy_digest",
        ):
            _require_digest(name, getattr(artifact, name))
        signature_payload = {
            key: value
            for key, value in artifact.payload.items()
            if key != "data_ingestor_signature_hex"
        }
        Ed25519PublicKey.from_public_bytes(
            bytes.fromhex(artifact.data_ingestor_public_key_hex)
        ).verify(
            bytes.fromhex(artifact.data_ingestor_signature_hex),
            json.dumps(
                signature_payload,
                sort_keys=True,
                separators=(",", ":"),
            ).encode("utf-8"),
        )
    except (AttributeError, InvalidSignature, RuntimeError, ValueError) as error:
        raise ValueError("resolved source-coverage artifact is invalid") from error


@dataclass(frozen=True, init=False)
class OperationalIssuanceDomainArtifact:
    """Resolved publication/source/exclusion masks fixed before scoring."""

    _eligible_mask: Tensor
    plan_digest: str
    grid_contract_digest: str
    radar_source_contract_digest: str
    lead_minutes: tuple[int, ...]
    publication_eligible_mask_digest: str
    source_coverage_mask_digest: str
    permanent_exclusion_mask_digest: str
    nominal_source_coverage_mask_digest: str
    resolved_source_coverage_artifact_digest: str | None
    resolved_input_bundle_digest: str | None
    resolved_full_analysis_input_digest: str | None
    resolved_source_radar_index_map_digest: str | None
    resolved_source_radar_registry_digest: str | None
    resolved_source_selection_policy_digest: str | None
    eligible_mask_digest: str
    eligible_cell_counts: tuple[int, ...]
    contract: str = "operational-issuance-domain-artifact-v2"
    artifact_digest: str = field(init=False)

    def __init__(self) -> None:
        raise TypeError("use OperationalIssuanceDomainArtifact.from_masks")

    @classmethod
    def from_masks(
        cls,
        plan: OperationalIssuanceDomainPlan,
        *,
        publication_eligible_mask: Tensor,
        source_coverage_mask: Tensor,
        permanent_exclusion_mask: Tensor,
        resolved_source_coverage: ResolvedSourceCoverageArtifact | None = None,
    ) -> OperationalIssuanceDomainArtifact:
        masks = (
            publication_eligible_mask,
            source_coverage_mask,
            permanent_exclusion_mask,
        )
        if (
            any(mask.dtype is not torch.bool or mask.ndim != 3 for mask in masks)
            or any(
                mask.shape != masks[0].shape or mask.device != masks[0].device
                for mask in masks[1:]
            )
            or masks[0].shape[0] != len(plan.lead_minutes)
        ):
            raise ValueError("operational issuance-domain masks are invalid")
        if plan.radar_source_kind == "mosaic" and resolved_source_coverage is None:
            raise ValueError("mosaic issuance requires resolved source coverage")
        mask_digests = tuple(tensor_digest(mask) for mask in masks)
        if mask_digests != (
            plan.publication_eligible_mask_digest,
            plan.source_coverage_mask_digest,
            plan.permanent_exclusion_mask_digest,
        ):
            raise ValueError(
                "operational issuance-domain masks were not preregistered"
            )
        resolved_source_mask = masks[1]
        if resolved_source_coverage is not None:
            validate_resolved_source_coverage_artifact(resolved_source_coverage)
            if (
                resolved_source_coverage.issuance_domain_plan_digest
                != plan.plan_digest
                or resolved_source_coverage.case_id != plan.case_id
                or resolved_source_coverage.grid_contract_digest
                != plan.grid_contract_digest
                or resolved_source_coverage.radar_source_contract_digest
                != plan.radar_source_contract_digest
                or resolved_source_coverage.source_coverage_policy_digest
                != plan.source_coverage_policy_digest
                or resolved_source_coverage.source_radar_registry_digest
                != plan.source_radar_registry_digest
                or resolved_source_coverage.source_radar_count
                != plan.source_radar_count
                or resolved_source_coverage.data_ingestor_id
                != plan.data_ingestor_id
                or resolved_source_coverage.data_ingestor_public_key_hex
                != plan.data_ingestor_public_key_hex
                or resolved_source_coverage.nominal_source_coverage_mask_digest
                != mask_digests[1]
                or resolved_source_coverage._resolved_mask.shape
                != masks[1].shape
                or resolved_source_coverage._resolved_mask.device
                != masks[1].device
            ):
                raise ValueError(
                    "resolved source coverage disagrees with its plan"
                )
            resolved_source_mask = resolved_source_coverage._resolved_mask
        eligible = masks[0] & resolved_source_mask & ~masks[2]
        counts = tuple(
            int(value)
            for value in torch.count_nonzero(eligible, dim=(-2, -1)).tolist()
        )
        if any(value <= 0 for value in counts):
            raise ValueError("operational issuance domain is empty")
        values: dict[str, object] = {
            "_eligible_mask": eligible.detach().clone(),
            "plan_digest": plan.plan_digest,
            "grid_contract_digest": plan.grid_contract_digest,
            "radar_source_contract_digest": plan.radar_source_contract_digest,
            "lead_minutes": plan.lead_minutes,
            "publication_eligible_mask_digest": mask_digests[0],
            "source_coverage_mask_digest": tensor_digest(resolved_source_mask),
            "permanent_exclusion_mask_digest": mask_digests[2],
            "nominal_source_coverage_mask_digest": mask_digests[1],
            "resolved_source_coverage_artifact_digest": (
                None
                if resolved_source_coverage is None
                else resolved_source_coverage.artifact_digest
            ),
            "resolved_input_bundle_digest": (
                None
                if resolved_source_coverage is None
                else resolved_source_coverage.input_bundle_digest
            ),
            "resolved_full_analysis_input_digest": (
                None
                if resolved_source_coverage is None
                else resolved_source_coverage.full_analysis_input_digest
            ),
            "resolved_source_radar_index_map_digest": (
                None
                if resolved_source_coverage is None
                else resolved_source_coverage.source_radar_index_map_digest
            ),
            "resolved_source_radar_registry_digest": (
                None
                if resolved_source_coverage is None
                else resolved_source_coverage.source_radar_registry_digest
            ),
            "resolved_source_selection_policy_digest": (
                None
                if resolved_source_coverage is None
                else resolved_source_coverage.source_selection_policy_digest
            ),
            "eligible_mask_digest": tensor_digest(eligible),
            "eligible_cell_counts": counts,
            "contract": "operational-issuance-domain-artifact-v2",
        }
        result = object.__new__(cls)
        for name, value in values.items():
            object.__setattr__(result, name, value)
        object.__setattr__(result, "artifact_digest", json_digest(result.payload))
        validate_operational_issuance_domain_artifact(result)
        return result

    @property
    def payload(self) -> dict[str, object]:
        return {
            "contract": self.contract,
            "plan_digest": self.plan_digest,
            "grid_contract_digest": self.grid_contract_digest,
            "radar_source_contract_digest": self.radar_source_contract_digest,
            "lead_minutes": list(self.lead_minutes),
            "publication_eligible_mask_digest": (
                self.publication_eligible_mask_digest
            ),
            "source_coverage_mask_digest": self.source_coverage_mask_digest,
            "nominal_source_coverage_mask_digest": (
                self.nominal_source_coverage_mask_digest
            ),
            "resolved_source_coverage_artifact_digest": (
                self.resolved_source_coverage_artifact_digest
            ),
            "resolved_input_bundle_digest": self.resolved_input_bundle_digest,
            "resolved_full_analysis_input_digest": (
                self.resolved_full_analysis_input_digest
            ),
            "resolved_source_radar_index_map_digest": (
                self.resolved_source_radar_index_map_digest
            ),
            "resolved_source_radar_registry_digest": (
                self.resolved_source_radar_registry_digest
            ),
            "resolved_source_selection_policy_digest": (
                self.resolved_source_selection_policy_digest
            ),
            "permanent_exclusion_mask_digest": (
                self.permanent_exclusion_mask_digest
            ),
            "eligible_mask_digest": self.eligible_mask_digest,
            "eligible_cell_counts": list(self.eligible_cell_counts),
        }

    @property
    def eligible_mask(self) -> Tensor:
        return self._eligible_mask.detach().clone()


def validate_operational_issuance_domain_artifact(
    artifact: OperationalIssuanceDomainArtifact,
) -> None:
    """Rehash the retained operational mask and its typed metadata."""

    try:
        mask = artifact._eligible_mask
        counts = tuple(
            int(value)
            for value in torch.count_nonzero(mask, dim=(-2, -1)).tolist()
        )
        if (
            artifact.contract != "operational-issuance-domain-artifact-v2"
            or mask.dtype is not torch.bool
            or mask.ndim != 3
            or mask.shape[0] != len(artifact.lead_minutes)
            or tensor_digest(mask) != artifact.eligible_mask_digest
            or counts != artifact.eligible_cell_counts
            or any(value <= 0 for value in counts)
            or artifact.artifact_digest != json_digest(artifact.payload)
        ):
            raise ValueError("operational issuance-domain artifact is invalid")
        for name in (
            "plan_digest",
            "grid_contract_digest",
            "radar_source_contract_digest",
            "publication_eligible_mask_digest",
            "source_coverage_mask_digest",
            "nominal_source_coverage_mask_digest",
            "permanent_exclusion_mask_digest",
            "eligible_mask_digest",
        ):
            _require_digest(name, getattr(artifact, name))
        if artifact.resolved_source_coverage_artifact_digest is not None:
            for name in (
                "resolved_source_coverage_artifact_digest",
                "resolved_input_bundle_digest",
                "resolved_full_analysis_input_digest",
                "resolved_source_radar_index_map_digest",
                "resolved_source_radar_registry_digest",
                "resolved_source_selection_policy_digest",
            ):
                value = getattr(artifact, name)
                if value is None:
                    raise ValueError(
                        "resolved operational issuance lineage is incomplete"
                    )
                _require_digest(name, value)
        elif (
            artifact.resolved_input_bundle_digest is not None
            or artifact.resolved_full_analysis_input_digest is not None
            or artifact.resolved_source_radar_index_map_digest is not None
            or artifact.resolved_source_radar_registry_digest is not None
            or artifact.resolved_source_selection_policy_digest is not None
        ):
            raise ValueError("static operational issuance lineage is invalid")
    except (AttributeError, RuntimeError, ValueError) as error:
        raise ValueError("operational issuance-domain artifact is invalid") from error


@dataclass(frozen=True)
class TrainingTargetSourceTrustStore:
    """Root-signed authority and scope registry for training truth sources."""

    authorities: tuple[
        tuple[
            str,
            str,
            int,
            str,
            str,
            str | None,
            tuple[str, ...],
            tuple[str, ...],
        ],
        ...,
    ]
    root_authority_id: str
    root_public_key_hex: str
    root_signature_hex: str
    contract: str = "training-target-source-trust-store-v1"
    content_digest: str = field(init=False)

    def __post_init__(self) -> None:
        if (
            self.contract != "training-target-source-trust-store-v1"
            or not self.root_authority_id
            or self.root_authority_id.strip() != self.root_authority_id
        ):
            raise ValueError("training target-source trust store is invalid")
        canonical: list[
            tuple[
                str,
                str,
                int,
                str,
                str,
                str | None,
                tuple[str, ...],
                tuple[str, ...],
            ]
        ] = []
        for item in sorted(self.authorities, key=lambda value: value[0]):
            if type(item) is not tuple or len(item) != 8:
                raise ValueError("training target-source authority is invalid")
            (
                authority_id,
                public_key_hex,
                key_epoch,
                not_before,
                not_after,
                revoked_at,
                source_contract_digests,
                radar_product_scope_digests,
            ) = item
            if (
                not authority_id
                or authority_id.strip() != authority_id
                or type(key_epoch) is not int
                or key_epoch <= 0
                or not source_contract_digests
                or not radar_product_scope_digests
                or len(set(source_contract_digests))
                != len(source_contract_digests)
                or len(set(radar_product_scope_digests))
                != len(radar_product_scope_digests)
            ):
                raise ValueError("training target-source authority is invalid")
            for digest in source_contract_digests + radar_product_scope_digests:
                _require_digest("training target-source scope", digest)
            canonical_not_before = _canonical_time(not_before)
            canonical_not_after = _canonical_time(not_after)
            canonical_revoked_at = (
                None if revoked_at is None else _canonical_time(revoked_at)
            )
            if (
                _canonical_datetime(canonical_not_before)
                >= _canonical_datetime(canonical_not_after)
                or (
                    canonical_revoked_at is not None
                    and _canonical_datetime(canonical_revoked_at)
                    < _canonical_datetime(canonical_not_before)
                )
            ):
                raise ValueError("training target-source lifetime is invalid")
            try:
                key = bytes.fromhex(public_key_hex)
                Ed25519PublicKey.from_public_bytes(key)
            except (TypeError, ValueError) as error:
                raise ValueError(
                    "training target-source authority key is invalid"
                ) from error
            if len(key) != 32:
                raise ValueError("training target-source authority key is invalid")
            canonical.append(
                (
                    authority_id,
                    public_key_hex,
                    key_epoch,
                    canonical_not_before,
                    canonical_not_after,
                    canonical_revoked_at,
                    tuple(sorted(source_contract_digests)),
                    tuple(sorted(radar_product_scope_digests)),
                )
            )
        if (
            not canonical
            or len({(item[0], item[2]) for item in canonical}) != len(canonical)
            or len({item[1] for item in canonical}) != len(canonical)
        ):
            raise ValueError("training target-source trust store is invalid")
        object.__setattr__(self, "authorities", tuple(canonical))
        try:
            root_key = bytes.fromhex(self.root_public_key_hex)
            Ed25519PublicKey.from_public_bytes(root_key).verify(
                bytes.fromhex(self.root_signature_hex),
                json_digest(self.unsigned_payload).encode("ascii"),
            )
        except (InvalidSignature, TypeError, ValueError) as error:
            raise ValueError(
                "training target-source trust store is unsigned"
            ) from error
        if len(root_key) != 32:
            raise ValueError("training target-source trust root is invalid")
        object.__setattr__(self, "content_digest", json_digest(self.payload))

    @classmethod
    def issue(
        cls,
        *,
        authorities: tuple[
            tuple[
                str,
                str,
                int,
                str,
                str,
                str | None,
                tuple[str, ...],
                tuple[str, ...],
            ],
            ...,
        ],
        root_authority_id: str,
        root_private_key: Ed25519PrivateKey,
    ) -> TrainingTargetSourceTrustStore:
        provisional = object.__new__(cls)
        object.__setattr__(provisional, "authorities", authorities)
        object.__setattr__(provisional, "root_authority_id", root_authority_id)
        object.__setattr__(
            provisional,
            "root_public_key_hex",
            root_private_key.public_key().public_bytes_raw().hex(),
        )
        object.__setattr__(provisional, "root_signature_hex", "")
        object.__setattr__(
            provisional, "contract", "training-target-source-trust-store-v1"
        )
        canonical = cls(
            authorities=authorities,
            root_authority_id=root_authority_id,
            root_public_key_hex=root_private_key.public_key().public_bytes_raw().hex(),
            root_signature_hex=root_private_key.sign(
                json_digest(provisional.unsigned_payload).encode("ascii")
            ).hex(),
        )
        return canonical

    @property
    def unsigned_payload(self) -> dict[str, object]:
        return {
            "authorities": [
                [*item[:6], list(item[6]), list(item[7])]
                for item in self.authorities
            ],
            "root_authority_id": self.root_authority_id,
            "root_public_key_hex": self.root_public_key_hex,
            "root_signature_hex": "",
            "contract": self.contract,
        }

    @property
    def payload(self) -> dict[str, object]:
        return self.unsigned_payload | {
            "root_signature_hex": self.root_signature_hex,
        }

    def approved_key(
        self,
        authority_id: str,
        *,
        key_epoch: int,
        at: str,
        source_contract_digest: str,
        radar_product_scope_digest: str,
    ) -> str | None:
        instant = _canonical_datetime(at)
        for item in self.authorities:
            if item[0] != authority_id or item[2] != key_epoch:
                continue
            if (
                not (
                    _canonical_datetime(item[3])
                    <= instant
                    <= _canonical_datetime(item[4])
                )
                or (item[5] is not None and instant >= _canonical_datetime(item[5]))
                or source_contract_digest not in item[6]
                or radar_product_scope_digest not in item[7]
            ):
                return None
            return item[1]
        return None


def _training_target_source_trust_store_from_json(
    text: str,
    *,
    expected_digest: str,
) -> TrainingTargetSourceTrustStore:
    try:
        payload = json.loads(text)
        if not isinstance(payload, dict) or text != json.dumps(
            payload, sort_keys=True, separators=(",", ":")
        ):
            raise TypeError
        values = dict(payload)
        stored_digest = values.pop("content_digest")
        raw_authorities = values.get("authorities")
        if not isinstance(raw_authorities, list):
            raise TypeError
        values["authorities"] = tuple(
            (
                str(item[0]),
                str(item[1]),
                int(item[2]),
                str(item[3]),
                str(item[4]),
                None if item[5] is None else str(item[5]),
                tuple(item[6]),
                tuple(item[7]),
            )
            for item in raw_authorities
            if isinstance(item, list) and len(item) == 8
        )
        store = TrainingTargetSourceTrustStore(**cast(Any, values))
    except (
        IndexError,
        KeyError,
        TypeError,
        ValueError,
        json.JSONDecodeError,
    ) as error:
        raise ValueError("training target-source trust store is invalid") from error
    if stored_digest != expected_digest or store.content_digest != expected_digest:
        raise ValueError("training target-source trust store digest mismatch")
    return store


@dataclass(frozen=True)
class TrainingTargetSourceReceipt:
    """Independent authority receipt for one immutable verification source."""

    target_source_identity_digest: str
    target_source_valid_time: str
    physical_event_digest: str
    source_object_digest: str
    observed_at: str
    authority_id: str
    authority_public_key_hex: str
    authority_key_epoch: int
    source_contract_digest: str
    radar_product_scope_digest: str
    target_source_trust_store_digest: str
    authority_signature_hex: str
    contract: str = "training-target-source-receipt-v2"
    receipt_digest: str = field(init=False)

    def __post_init__(self) -> None:
        if (
            self.contract != "training-target-source-receipt-v2"
            or not self.authority_id
            or self.authority_id.strip() != self.authority_id
        ):
            raise ValueError("training target source receipt is invalid")
        for name in (
            "target_source_identity_digest",
            "physical_event_digest",
            "source_object_digest",
            "source_contract_digest",
            "radar_product_scope_digest",
            "target_source_trust_store_digest",
        ):
            _require_digest(name, getattr(self, name))
        if type(self.authority_key_epoch) is not int or self.authority_key_epoch <= 0:
            raise ValueError("training target source key epoch is invalid")
        source_time = _canonical_time(self.target_source_valid_time)
        observed_at = _canonical_time(self.observed_at)
        object.__setattr__(self, "target_source_valid_time", source_time)
        object.__setattr__(self, "observed_at", observed_at)
        if _canonical_datetime(observed_at) < _canonical_datetime(source_time):
            raise ValueError("training target source chronology is invalid")
        unsigned = {
            key: value
            for key, value in self.payload.items()
            if key != "authority_signature_hex"
        }
        try:
            Ed25519PublicKey.from_public_bytes(
                bytes.fromhex(self.authority_public_key_hex)
            ).verify(
                bytes.fromhex(self.authority_signature_hex),
                json_digest(unsigned).encode("ascii"),
            )
        except (InvalidSignature, ValueError) as error:
            raise ValueError("training target source receipt is unsigned") from error
        object.__setattr__(self, "receipt_digest", json_digest(self.payload))

    @classmethod
    def issue(
        cls,
        *,
        target_source_identity_digest: str,
        target_source_valid_time: str,
        physical_event_digest: str,
        source_object_digest: str,
        observed_at: str,
        source_contract_digest: str,
        radar_product_scope_digest: str,
        trust_store: TrainingTargetSourceTrustStore,
        authority_id: str,
        authority_key_epoch: int,
        authority_private_key: Ed25519PrivateKey,
    ) -> TrainingTargetSourceReceipt:
        canonical_observed_at = _canonical_time(observed_at)
        unsigned: dict[str, object] = {
            "target_source_identity_digest": target_source_identity_digest,
            "target_source_valid_time": _canonical_time(
                target_source_valid_time
            ),
            "physical_event_digest": physical_event_digest,
            "source_object_digest": source_object_digest,
            "observed_at": canonical_observed_at,
            "authority_id": authority_id,
            "authority_public_key_hex": (
                authority_private_key.public_key().public_bytes_raw().hex()
            ),
            "authority_key_epoch": authority_key_epoch,
            "source_contract_digest": source_contract_digest,
            "radar_product_scope_digest": radar_product_scope_digest,
            "target_source_trust_store_digest": trust_store.content_digest,
            "contract": "training-target-source-receipt-v2",
        }
        if trust_store.approved_key(
            authority_id,
            key_epoch=authority_key_epoch,
            at=canonical_observed_at,
            source_contract_digest=source_contract_digest,
            radar_product_scope_digest=radar_product_scope_digest,
        ) != unsigned["authority_public_key_hex"]:
            raise ValueError("training target source authority is not approved")
        return cls(
            **cast(Any, unsigned),
            authority_signature_hex=authority_private_key.sign(
                json_digest(unsigned).encode("ascii")
            ).hex(),
        )

    @property
    def payload(self) -> dict[str, object]:
        return {
            key: value
            for key, value in self.__dict__.items()
            if key != "receipt_digest"
        }

    def validate_against(
        self,
        trust_store: TrainingTargetSourceTrustStore,
        *,
        at: str | None = None,
        require_bound_digest: bool = True,
    ) -> None:
        if (
            type(trust_store) is not TrainingTargetSourceTrustStore
            or (
                require_bound_digest
                and self.target_source_trust_store_digest
                != trust_store.content_digest
            )
            or trust_store.approved_key(
                self.authority_id,
                key_epoch=self.authority_key_epoch,
                at=self.observed_at if at is None else at,
                source_contract_digest=self.source_contract_digest,
                radar_product_scope_digest=self.radar_product_scope_digest,
            )
            != self.authority_public_key_hex
        ):
            raise ValueError("training target source receipt is untrusted")


def _training_target_source_receipt_from_json(
    text: str,
) -> TrainingTargetSourceReceipt:
    try:
        payload = json.loads(text)
        if not isinstance(payload, dict) or text != json.dumps(
            payload, sort_keys=True, separators=(",", ":")
        ):
            raise TypeError
        values = dict(payload)
        retained_digest = values.pop("receipt_digest")
        receipt = TrainingTargetSourceReceipt(**cast(Any, values))
    except (KeyError, TypeError, ValueError, json.JSONDecodeError) as error:
        raise ValueError("training target source receipt is invalid") from error
    if retained_digest != receipt.receipt_digest:
        raise ValueError("training target source receipt digest mismatch")
    return receipt


@dataclass(frozen=True)
class TrainingTargetDerivationArtifact:
    """Signed origin and chronology for one training target tensor."""

    case_id: str
    target_source_identity_digest: str
    target_source_valid_time: str
    target_qc_policy_digest: str
    target_censor_policy_digest: str
    target_algorithm_digest: str
    target_schema_digest: str
    target_tensor_digest: str
    generated_at: str
    training_cutoff_time: str
    processor_id: str
    processor_public_key_hex: str
    processor_signature_hex: str
    target_source_receipt_json: str
    target_plan_digest: str = ""
    target_source_receipt_digest: str = ""
    physical_event_digest: str = ""
    target_valid_mask_digest: str = ""
    target_quality_digest: str = ""
    target_units: str = ""
    target_shape: tuple[int, ...] = ()
    contract: str = "training-target-derivation-artifact-v4"
    artifact_digest: str = field(init=False)

    def __post_init__(self) -> None:
        if (
            self.contract != "training-target-derivation-artifact-v4"
            or not self.case_id
            or self.case_id.strip() != self.case_id
            or not self.processor_id
            or self.processor_id.strip() != self.processor_id
        ):
            raise ValueError("training target derivation is invalid")
        for name in (
            "target_source_identity_digest",
            "target_qc_policy_digest",
            "target_censor_policy_digest",
            "target_algorithm_digest",
            "target_schema_digest",
            "target_tensor_digest",
            "target_plan_digest",
            "target_source_receipt_digest",
            "physical_event_digest",
            "target_valid_mask_digest",
            "target_quality_digest",
        ):
            _require_digest(name, getattr(self, name))
        if (
            not self.target_units
            or self.target_units.strip() != self.target_units
            or not self.target_shape
            or any(type(value) is not int or value <= 0 for value in self.target_shape)
        ):
            raise ValueError("training target physical schema is invalid")
        canonical_source_time = _canonical_time(self.target_source_valid_time)
        canonical_generated = _canonical_time(self.generated_at)
        canonical_cutoff = _canonical_time(self.training_cutoff_time)
        object.__setattr__(
            self, "target_source_valid_time", canonical_source_time
        )
        object.__setattr__(self, "generated_at", canonical_generated)
        object.__setattr__(self, "training_cutoff_time", canonical_cutoff)
        source_time = _canonical_datetime(canonical_source_time)
        generated = _canonical_datetime(canonical_generated)
        cutoff = _canonical_datetime(canonical_cutoff)
        source_receipt = _training_target_source_receipt_from_json(
            self.target_source_receipt_json
        )
        if not (
            source_time <= generated < cutoff
            and source_receipt.target_source_identity_digest
            == self.target_source_identity_digest
            and source_receipt.target_source_valid_time
            == canonical_source_time
            and source_receipt.physical_event_digest
            == self.physical_event_digest
            and source_receipt.receipt_digest
            == self.target_source_receipt_digest
            and _canonical_datetime(source_receipt.observed_at) <= generated
        ):
            raise ValueError("training target chronology is invalid")
        unsigned = {
            key: value
            for key, value in self.payload.items()
            if key != "processor_signature_hex"
        }
        try:
            Ed25519PublicKey.from_public_bytes(
                bytes.fromhex(self.processor_public_key_hex)
            ).verify(
                bytes.fromhex(self.processor_signature_hex),
                json_digest(unsigned).encode("ascii"),
            )
        except (InvalidSignature, ValueError) as error:
            raise ValueError("training target derivation is unsigned") from error
        object.__setattr__(self, "artifact_digest", json_digest(self.payload))

    @classmethod
    def issue(
        cls,
        *,
        case_id: str,
        target_source_receipt: TrainingTargetSourceReceipt,
        target_qc_policy_digest: str,
        target_censor_policy_digest: str,
        target_algorithm_digest: str,
        target_schema_digest: str,
        target_tensor: Tensor,
        target_valid_mask: Tensor | None = None,
        target_quality: Tensor | None = None,
        target_units: str = "unitless",
        target_plan_digest: str | None = None,
        generated_at: str,
        training_cutoff_time: str,
        processor_id: str,
        processor_private_key: Ed25519PrivateKey,
    ) -> TrainingTargetDerivationArtifact:
        if (
            not isinstance(target_tensor, Tensor)
            or not target_tensor.is_floating_point()
            or target_tensor.numel() == 0
            or not bool(torch.all(torch.isfinite(target_tensor)))
        ):
            raise ValueError("training target tensor must be finite and nonempty")
        valid_mask = (
            torch.ones_like(target_tensor, dtype=torch.bool)
            if target_valid_mask is None
            else target_valid_mask
        )
        quality = (
            torch.ones_like(target_tensor)
            if target_quality is None
            else target_quality
        )
        if (
            valid_mask.dtype is not torch.bool
            or valid_mask.shape != target_tensor.shape
            or quality.shape != target_tensor.shape
            or not quality.is_floating_point()
            or not bool(torch.all(torch.isfinite(quality)))
            or not bool(torch.all((quality >= 0.0) & (quality <= 1.0)))
            or not bool(torch.any(valid_mask))
            or bool(torch.any(quality.masked_select(~valid_mask) != 0.0))
            or float(quality.masked_select(valid_mask).sum()) <= 0.0
            or bool(torch.any(target_tensor.masked_select(~valid_mask) != 0.0))
        ):
            raise ValueError("training target mask/quality is invalid")
        if type(target_source_receipt) is not TrainingTargetSourceReceipt:
            raise TypeError("current training target source receipt is required")
        canonical_source_time = target_source_receipt.target_source_valid_time
        target_source_identity_digest = (
            target_source_receipt.target_source_identity_digest
        )
        plan_digest = target_plan_digest or json_digest(
            {
                "contract": "training-target-plan-v1",
                "target_source_identity_digest": target_source_identity_digest,
                "target_source_valid_time": canonical_source_time,
                "target_qc_policy_digest": target_qc_policy_digest,
                "target_censor_policy_digest": target_censor_policy_digest,
                "target_algorithm_digest": target_algorithm_digest,
                "target_schema_digest": target_schema_digest,
            }
        )
        source_receipt_digest = target_source_receipt.receipt_digest
        event_digest = target_source_receipt.physical_event_digest
        unsigned: dict[str, object] = {
            "case_id": case_id,
            "target_source_identity_digest": target_source_identity_digest,
            "target_source_valid_time": canonical_source_time,
            "target_qc_policy_digest": target_qc_policy_digest,
            "target_censor_policy_digest": target_censor_policy_digest,
            "target_algorithm_digest": target_algorithm_digest,
            "target_schema_digest": target_schema_digest,
            "target_tensor_digest": tensor_digest(target_tensor),
            "target_plan_digest": plan_digest,
            "target_source_receipt_digest": source_receipt_digest,
            "target_source_receipt_json": json.dumps(
                target_source_receipt.payload
                | {"receipt_digest": target_source_receipt.receipt_digest},
                sort_keys=True,
                separators=(",", ":"),
            ),
            "physical_event_digest": event_digest,
            "target_valid_mask_digest": tensor_digest(valid_mask),
            "target_quality_digest": tensor_digest(quality),
            "target_units": target_units,
            "target_shape": tuple(target_tensor.shape),
            "generated_at": _canonical_time(generated_at),
            "training_cutoff_time": _canonical_time(training_cutoff_time),
            "processor_id": processor_id,
            "processor_public_key_hex": (
                processor_private_key.public_key().public_bytes_raw().hex()
            ),
            "contract": "training-target-derivation-artifact-v4",
        }
        return cls(
            **cast(Any, unsigned),
            processor_signature_hex=processor_private_key.sign(
                json_digest(unsigned).encode("ascii")
            ).hex(),
        )

    @property
    def payload(self) -> dict[str, object]:
        return {
            key: value
            for key, value in self.__dict__.items()
            if key != "artifact_digest"
        }


def _training_target_derivation_from_json(
    text: str,
) -> TrainingTargetDerivationArtifact:
    try:
        payload = json.loads(text)
    except json.JSONDecodeError as error:
        raise ValueError("training target derivation is invalid") from error
    if not isinstance(payload, dict):
        raise ValueError("training target derivation is invalid")
    values = dict(payload)
    stored_digest = values.pop("artifact_digest", None)
    if isinstance(values.get("target_shape"), list):
        values["target_shape"] = tuple(values["target_shape"])
    try:
        artifact = TrainingTargetDerivationArtifact(**cast(Any, values))
    except (TypeError, ValueError) as error:
        raise ValueError("training target derivation is invalid") from error
    canonical = json.dumps(
        artifact.payload | {"artifact_digest": artifact.artifact_digest},
        sort_keys=True,
        separators=(",", ":"),
    )
    if stored_digest != artifact.artifact_digest or text != canonical:
        raise ValueError("training target derivation digest mismatch")
    return artifact


def _validate_training_target_snapshot(
    target: Tensor,
    valid_mask: Tensor,
    quality: Tensor,
    *,
    expected_shape: tuple[int, ...],
) -> None:
    if (
        not target.is_floating_point()
        or target.numel() == 0
        or tuple(target.shape) != expected_shape
        or valid_mask.dtype is not torch.bool
        or tuple(valid_mask.shape) != expected_shape
        or not quality.is_floating_point()
        or tuple(quality.shape) != expected_shape
        or not bool(torch.all(torch.isfinite(target)))
        or not bool(torch.all(torch.isfinite(quality)))
        or not bool(torch.all((quality >= 0.0) & (quality <= 1.0)))
        or not bool(torch.any(valid_mask))
        or bool(torch.any(quality.masked_select(~valid_mask) != 0.0))
        or float(quality.masked_select(valid_mask).sum()) <= 0.0
        or bool(torch.any(target.masked_select(~valid_mask) != 0.0))
    ):
        raise ValueError("training target snapshot semantics are invalid")


def weighted_training_target_loss(
    prediction: Tensor,
    target: Tensor,
    valid_mask: Tensor,
    quality: Tensor,
    *,
    sample_weight: float = 1.0,
) -> Tensor:
    """Return the product-owned mask-first, quality-weighted squared loss."""

    if (
        not isinstance(prediction, Tensor)
        or prediction.shape != target.shape
        or not prediction.is_floating_point()
        or not bool(torch.all(torch.isfinite(prediction)))
        or not math.isfinite(sample_weight)
        or sample_weight <= 0.0
    ):
        raise ValueError("training loss prediction or sample weight is invalid")
    _validate_training_target_snapshot(
        target,
        valid_mask,
        quality,
        expected_shape=tuple(target.shape),
    )
    effective_weight = (
        valid_mask.to(dtype=quality.dtype) * quality * sample_weight
    )
    denominator = effective_weight.sum()
    if not bool(torch.isfinite(denominator)) or float(denominator) <= 0.0:
        raise ValueError("training target effective weight is zero")
    squared_error = (prediction - target).square()
    return (effective_weight * squared_error).sum() / denominator


def encode_training_tensor_archive(tensors: dict[str, Tensor]) -> str:
    """Encode one canonical, pickle-free NPZ training tensor archive."""

    if not tensors or any(
        not name or name.strip() != name or "/" in name or "\\" in name
        for name in tensors
    ):
        raise ValueError("training tensor archive member names are invalid")
    arrays: dict[str, Any] = {}
    for name, tensor in sorted(tensors.items()):
        if not isinstance(tensor, Tensor) or not tensor.is_floating_point():
            raise ValueError("training tensor archive requires floating tensors")
        arrays[name] = np.array(
            tensor.detach().contiguous().cpu().numpy(),
            copy=True,
        )
    stream = io.BytesIO()
    np.savez(stream, **arrays)
    return base64.b64encode(stream.getvalue()).decode("ascii")


def _validate_training_tensor_archive(
    encoded: str,
    *,
    expected_sha256: str,
    member_names: tuple[str, ...],
    tensor_digests: tuple[str, ...],
) -> None:
    if (
        not encoded
        or len(member_names) != len(tensor_digests)
        or len(set(member_names)) != len(member_names)
    ):
        raise ValueError("training tensor archive manifest is invalid")
    try:
        raw = base64.b64decode(encoded, validate=True)
    except (ValueError, binascii.Error) as error:
        raise ValueError("training tensor archive encoding is invalid") from error
    if base64.b64encode(raw).decode("ascii") != encoded:
        raise ValueError("training tensor archive encoding is not canonical")
    if hashlib.sha256(raw).hexdigest() != expected_sha256:
        raise ValueError("training tensor archive checksum mismatch")
    if len(raw) > 512 * 1024**2:
        raise ValueError("training tensor archive exceeds its byte budget")
    try:
        with zipfile.ZipFile(io.BytesIO(raw)) as archive:
            members = archive.infolist()
            if (
                len(members) != len(member_names)
                or any(
                    item.is_dir()
                    or item.filename != f"{name}.npy"
                    or item.file_size > 256 * 1024**2
                    for item, name in zip(
                        sorted(members, key=lambda value: value.filename),
                        sorted(member_names),
                        strict=True,
                    )
                )
                or sum(item.file_size for item in members) > 1024**3
            ):
                raise ValueError("training tensor archive membership is invalid")
        with np.load(io.BytesIO(raw), allow_pickle=False) as archive:
            if set(archive.files) != set(member_names):
                raise ValueError("training tensor archive membership is invalid")
            for name, expected_digest in zip(
                member_names,
                tensor_digests,
                strict=True,
            ):
                array = np.array(archive[name], copy=True)
                if (
                    array.dtype.hasobject
                    or array.dtype.fields is not None
                    or array.dtype.kind not in ("f",)
                    or tensor_digest(torch.from_numpy(array)) != expected_digest
                ):
                    raise ValueError("training tensor archive member mismatch")
    except (OSError, ValueError, zipfile.BadZipFile) as error:
        raise ValueError("training tensor archive is invalid") from error


@dataclass(frozen=True)
class TrainingTensorArchiveShard:
    """One immutable external NPZ shard and its ordered tensor manifest."""

    shard_id: str
    artifact_store_id: str
    relative_content_path: str
    archive_path: str
    archive_sha256: str
    archive_size_bytes: int
    member_names: tuple[str, ...]
    member_tensor_digests: tuple[str, ...]
    member_dtypes: tuple[str, ...]
    member_shapes: tuple[tuple[int, ...], ...]
    contract: str = "training-tensor-archive-shard-v2"
    shard_digest: str = field(init=False)

    def __post_init__(self) -> None:
        if (
            self.contract != "training-tensor-archive-shard-v2"
            or not self.shard_id
            or self.shard_id.strip() != self.shard_id
            or not self.artifact_store_id
            or self.artifact_store_id.strip() != self.artifact_store_id
            or self.artifact_store_id
            != "advar-content-addressed-training-store-v1"
            or not self.relative_content_path
            or self.relative_content_path.strip() != self.relative_content_path
            or Path(self.relative_content_path).is_absolute()
            or Path(self.relative_content_path).name != self.relative_content_path
            or type(self.archive_size_bytes) is not int
            or self.archive_size_bytes <= 0
            or not self.member_names
            or len(self.member_names) != len(set(self.member_names))
            or not (
                len(self.member_names)
                == len(self.member_tensor_digests)
                == len(self.member_dtypes)
                == len(self.member_shapes)
            )
        ):
            raise ValueError("training tensor shard manifest is invalid")
        _require_digest("training shard archive", self.archive_sha256)
        for digest in self.member_tensor_digests:
            _require_digest("training shard tensor", digest)
        if any(
            not name
            or name.strip() != name
            or name == "allow_pickle"
            or "/" in name
            or "\\" in name
            for name in self.member_names
        ) or any(
            not shape
            or any(type(value) is not int or value <= 0 for value in shape)
            for shape in self.member_shapes
        ):
            raise ValueError("training tensor shard members are invalid")
        path = Path(self.archive_path)
        if (
            not path.is_absolute()
            or self.relative_content_path != f"{self.archive_sha256}.npz"
            or path.name != self.relative_content_path
        ):
            raise ValueError("training tensor shard path must be absolute")
        object.__setattr__(self, "shard_digest", json_digest(self.identity_payload))
        _validate_training_tensor_archive_shard(self)

    @property
    def identity_payload(self) -> dict[str, object]:
        return {
            "shard_id": self.shard_id,
            "artifact_store_id": self.artifact_store_id,
            "relative_content_path": self.relative_content_path,
            "archive_sha256": self.archive_sha256,
            "archive_size_bytes": self.archive_size_bytes,
            "member_names": list(self.member_names),
            "member_tensor_digests": list(self.member_tensor_digests),
            "member_dtypes": list(self.member_dtypes),
            "member_shapes": [list(shape) for shape in self.member_shapes],
            "contract": self.contract,
        }

    @property
    def payload(self) -> dict[str, object]:
        return self.identity_payload | {
            "archive_path": self.archive_path,
            "shard_digest": self.shard_digest,
        }


def _stream_file_sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        while chunk := stream.read(1024 * 1024):
            digest.update(chunk)
    return digest.hexdigest()


def _validate_training_tensor_archive_shard(
    shard: TrainingTensorArchiveShard,
) -> None:
    _load_training_tensor_archive_shard_snapshot(shard)


def _load_training_tensor_archive_shard_snapshot(
    shard: TrainingTensorArchiveShard,
) -> dict[str, Tensor]:
    """Open once and return the exact validated bytes used by a trainer.

    Validation and NumPy decoding share one file descriptor and one in-memory
    byte snapshot.  A later path replacement therefore cannot alter the
    tensors returned to the product-owned training executor.
    """

    path = Path(shard.archive_path)
    descriptor: int | None = None
    try:
        before = path.stat(follow_symlinks=False)
        resolved_path = path.resolve(strict=True)
        parent = path.parent.stat(follow_symlinks=False)
    except OSError as error:
        raise ValueError("training tensor shard is unavailable") from error
    if (
        path != resolved_path
        or path.is_symlink()
        or not stat.S_ISREG(before.st_mode)
        or not stat.S_ISDIR(parent.st_mode)
        or path.name != f"{shard.archive_sha256}.npz"
        or before.st_size != shard.archive_size_bytes
        or before.st_size > 512 * 1024**2
        or before.st_uid not in {os.getuid(), 0}
        or before.st_mode & (stat.S_IWUSR | stat.S_IWGRP | stat.S_IWOTH)
        or parent.st_uid not in {os.getuid(), 0}
        or parent.st_mode & (stat.S_IWGRP | stat.S_IWOTH)
    ):
        raise ValueError("training tensor shard bytes are invalid")
    try:
        open_flags = os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0)
        descriptor = os.open(path, open_flags)
        opened = os.fstat(descriptor)
        if (
            opened.st_dev != before.st_dev
            or opened.st_ino != before.st_ino
            or opened.st_size != before.st_size
            or not stat.S_ISREG(opened.st_mode)
        ):
            raise ValueError("training tensor shard changed before open")
        chunks: list[bytes] = []
        remaining = shard.archive_size_bytes
        while remaining:
            chunk = os.read(descriptor, min(1024 * 1024, remaining))
            if not chunk:
                raise ValueError("training tensor shard was truncated")
            chunks.append(chunk)
            remaining -= len(chunk)
        if os.read(descriptor, 1):
            raise ValueError("training tensor shard grew during validation")
        raw = b"".join(chunks)
        if hashlib.sha256(raw).hexdigest() != shard.archive_sha256:
            raise ValueError("training tensor shard checksum mismatch")
        stream = io.BytesIO(raw)
        with zipfile.ZipFile(stream) as archive:
            infos = sorted(archive.infolist(), key=lambda item: item.filename)
            if (
                len(infos) != len(shard.member_names)
                or len(infos) > 4096
                or any(
                    info.is_dir()
                    or info.filename != f"{name}.npy"
                    or info.file_size > 256 * 1024**2
                    for info, name in zip(
                        infos,
                        sorted(shard.member_names),
                        strict=True,
                    )
                )
                or sum(info.file_size for info in infos) > 1024**3
            ):
                raise ValueError("training tensor shard membership is invalid")
        tensors: dict[str, Tensor] = {}
        with np.load(io.BytesIO(raw), allow_pickle=False) as archive:
            if set(archive.files) != set(shard.member_names):
                raise ValueError("training tensor shard membership is invalid")
            manifest = {
                name: (digest, dtype, shape)
                for name, digest, dtype, shape in zip(
                    shard.member_names,
                    shard.member_tensor_digests,
                    shard.member_dtypes,
                    shard.member_shapes,
                    strict=True,
                )
            }
            for name in shard.member_names:
                array = np.array(archive[name], copy=True)
                digest, dtype, shape = manifest[name]
                if (
                    array.dtype.hasobject
                    or array.dtype.fields is not None
                    or array.dtype.kind not in ("f", "b")
                    or str(array.dtype) != dtype
                    or tuple(array.shape) != shape
                    or array.size == 0
                    or (array.dtype.kind == "f" and not np.isfinite(array).all())
                    or tensor_digest(torch.from_numpy(array)) != digest
                ):
                    raise ValueError("training tensor shard member mismatch")
                tensors[name] = torch.from_numpy(array).detach().clone()
    except (OSError, ValueError, zipfile.BadZipFile) as error:
        raise ValueError("training tensor shard is invalid") from error
    finally:
        if descriptor is not None:
            os.close(descriptor)
    try:
        after = path.stat(follow_symlinks=False)
    except OSError as error:
        raise ValueError("training tensor shard changed after open") from error
    if (
        before.st_dev,
        before.st_ino,
        before.st_size,
        before.st_mtime_ns,
        stat.S_IMODE(before.st_mode),
    ) != (
        after.st_dev,
        after.st_ino,
        after.st_size,
        after.st_mtime_ns,
        stat.S_IMODE(after.st_mode),
    ):
        raise ValueError("training tensor shard changed during validation")
    return tensors


def load_training_tensor_archive_shard(
    shard: TrainingTensorArchiveShard,
) -> dict[str, Tensor]:
    """Return defensive tensors from one validated single-open snapshot."""

    if type(shard) is not TrainingTensorArchiveShard:
        raise TypeError("current training tensor shard is required")
    return {
        name: tensor.detach().clone()
        for name, tensor in _load_training_tensor_archive_shard_snapshot(
            shard
        ).items()
    }


def write_training_tensor_archive_shard(
    tensors: dict[str, Tensor],
    *,
    directory: str | Path,
    shard_id: str,
    artifact_store_id: str = "advar-content-addressed-training-store-v1",
) -> TrainingTensorArchiveShard:
    """Atomically publish one content-addressed, pickle-free NPZ shard."""

    if not tensors or not shard_id or shard_id.strip() != shard_id:
        raise ValueError("training tensor shard inputs are invalid")
    root = Path(directory).expanduser().resolve()
    root.mkdir(parents=True, exist_ok=True)
    arrays: dict[str, np.ndarray[Any, Any]] = {}
    names: list[str] = []
    digests: list[str] = []
    dtypes: list[str] = []
    shapes: list[tuple[int, ...]] = []
    for name, tensor in sorted(tensors.items()):
        if (
            not name
            or name.strip() != name
            or name == "allow_pickle"
            or "/" in name
            or "\\" in name
            or not isinstance(tensor, Tensor)
            or tensor.numel() == 0
            or tensor.dtype not in {
                torch.bool,
                torch.float16,
                torch.float32,
                torch.float64,
            }
            or (
                tensor.is_floating_point()
                and not bool(torch.all(torch.isfinite(tensor)))
            )
        ):
            raise ValueError("training tensor shard member is invalid")
        array = np.array(tensor.detach().contiguous().cpu().numpy(), copy=True)
        arrays[name] = array
        names.append(name)
        digests.append(tensor_digest(torch.from_numpy(array)))
        dtypes.append(str(array.dtype))
        shapes.append(tuple(array.shape))
    descriptor: int | None = None
    temporary_path: Path | None = None
    try:
        descriptor, raw_path = tempfile.mkstemp(
            prefix=f".{shard_id}.", suffix=".npz", dir=root
        )
        os.close(descriptor)
        descriptor = None
        temporary_path = Path(raw_path)
        savez = cast(Any, np.savez)
        savez(temporary_path, **arrays)
        with temporary_path.open("rb") as stream:
            os.fsync(stream.fileno())
        archive_sha256 = _stream_file_sha256(temporary_path)
        final_path = root / f"{archive_sha256}.npz"
        if final_path.exists():
            if _stream_file_sha256(final_path) != archive_sha256:
                raise ValueError("training tensor shard path equivocated")
            temporary_path.unlink()
        else:
            os.replace(temporary_path, final_path)
        os.chmod(final_path, stat.S_IRUSR | stat.S_IRGRP | stat.S_IROTH)
        directory_fd = os.open(root, os.O_RDONLY)
        try:
            os.fsync(directory_fd)
        finally:
            os.close(directory_fd)
        return TrainingTensorArchiveShard(
            shard_id=shard_id,
            artifact_store_id=artifact_store_id,
            relative_content_path=f"{archive_sha256}.npz",
            archive_path=str(final_path),
            archive_sha256=archive_sha256,
            archive_size_bytes=final_path.stat().st_size,
            member_names=tuple(names),
            member_tensor_digests=tuple(digests),
            member_dtypes=tuple(dtypes),
            member_shapes=tuple(shapes),
        )
    finally:
        if descriptor is not None:
            os.close(descriptor)
        if temporary_path is not None and temporary_path.exists():
            temporary_path.unlink()


@dataclass(frozen=True)
class TrainingDatasetMember:
    """One ordered feature/target training sample and its signed lineage."""

    case_id: str
    analysis_derivation_artifact_digest: str
    feature_archive_member: str
    feature_tensor_digest: str
    target_archive_member: str
    target_tensor_digest: str
    target_valid_mask_archive_member: str
    target_quality_archive_member: str
    target_derivation_artifact_json: str
    sample_weight: float
    split: Literal["train", "validation", "test"]
    augmentation_seed: int

    def __post_init__(self) -> None:
        if (
            not self.case_id
            or self.case_id.strip() != self.case_id
            or not self.feature_archive_member
            or self.feature_archive_member.strip() != self.feature_archive_member
            or "/" in self.feature_archive_member
            or "\\" in self.feature_archive_member
            or not self.target_archive_member
            or self.target_archive_member.strip() != self.target_archive_member
            or "/" in self.target_archive_member
            or "\\" in self.target_archive_member
            or not self.target_valid_mask_archive_member
            or self.target_valid_mask_archive_member.strip()
            != self.target_valid_mask_archive_member
            or "/" in self.target_valid_mask_archive_member
            or "\\" in self.target_valid_mask_archive_member
            or not self.target_quality_archive_member
            or self.target_quality_archive_member.strip()
            != self.target_quality_archive_member
            or "/" in self.target_quality_archive_member
            or "\\" in self.target_quality_archive_member
            or not math.isfinite(self.sample_weight)
            or self.sample_weight <= 0.0
            or self.split not in {"train", "validation", "test"}
            or type(self.augmentation_seed) is not int
            or self.augmentation_seed < 0
        ):
            raise ValueError("training dataset member is invalid")
        for name in (
            "analysis_derivation_artifact_digest",
            "feature_tensor_digest",
            "target_tensor_digest",
        ):
            _require_digest(name, getattr(self, name))
        target = _training_target_derivation_from_json(
            self.target_derivation_artifact_json
        )
        if target.case_id != self.case_id or (
            target.target_tensor_digest != self.target_tensor_digest
        ):
            raise ValueError("training target lineage disagrees with its member")

    @property
    def payload(self) -> dict[str, object]:
        return dict(self.__dict__)


@dataclass(frozen=True)
class NormalizationDerivationArtifact:
    """Train-only derivation of the normalization statistics shard."""

    ordered_train_member_digests: tuple[str, ...]
    train_case_ids: tuple[str, ...]
    channel_definitions: tuple[str, ...]
    normalization_algorithm_digest: str
    mask_weight_policy_digest: str
    statistics_tensor_digests: tuple[str, ...]
    normalization_shard_digest: str
    contract: str = "normalization-derivation-artifact-v1"
    artifact_digest: str = field(init=False)

    def __post_init__(self) -> None:
        if (
            self.contract != "normalization-derivation-artifact-v1"
            or not self.ordered_train_member_digests
            or len(self.ordered_train_member_digests)
            != len(self.train_case_ids)
            or len(set(self.train_case_ids)) != len(self.train_case_ids)
            or any(
                not value or value.strip() != value
                for value in self.train_case_ids
            )
            or not self.channel_definitions
            or len(set(self.channel_definitions))
            != len(self.channel_definitions)
            or any(
                not value or value.strip() != value
                for value in self.channel_definitions
            )
            or not self.statistics_tensor_digests
        ):
            raise ValueError("normalization derivation is invalid")
        for name, values in (
            ("train member", self.ordered_train_member_digests),
            ("normalization statistic", self.statistics_tensor_digests),
        ):
            for value in values:
                _require_digest(name, value)
        for name in (
            "normalization_algorithm_digest",
            "mask_weight_policy_digest",
            "normalization_shard_digest",
        ):
            _require_digest(name, getattr(self, name))
        if (
            self.normalization_algorithm_digest
            != TRAINING_NORMALIZATION_ALGORITHM_DIGEST
            or self.mask_weight_policy_digest
            != TRAINING_NORMALIZATION_MASK_WEIGHT_POLICY_DIGEST
        ):
            raise ValueError("normalization derivation algorithm is not product-owned")
        object.__setattr__(self, "artifact_digest", json_digest(self.payload))

    @classmethod
    def from_training_dataset(
        cls,
        *,
        members: tuple[TrainingDatasetMember, ...],
        normalization_shard: TrainingTensorArchiveShard,
        channel_definitions: tuple[str, ...],
        normalization_algorithm_digest: str,
        mask_weight_policy_digest: str,
    ) -> NormalizationDerivationArtifact:
        train_members = tuple(item for item in members if item.split == "train")
        if not train_members:
            raise ValueError("normalization requires train-split members")
        return cls(
            ordered_train_member_digests=tuple(
                json_digest(item.payload) for item in train_members
            ),
            train_case_ids=tuple(item.case_id for item in train_members),
            channel_definitions=channel_definitions,
            normalization_algorithm_digest=normalization_algorithm_digest,
            mask_weight_policy_digest=mask_weight_policy_digest,
            statistics_tensor_digests=(
                normalization_shard.member_tensor_digests
            ),
            normalization_shard_digest=normalization_shard.shard_digest,
        )

    @property
    def payload(self) -> dict[str, object]:
        return {
            "ordered_train_member_digests": list(
                self.ordered_train_member_digests
            ),
            "train_case_ids": list(self.train_case_ids),
            "channel_definitions": list(self.channel_definitions),
            "normalization_algorithm_digest": (
                self.normalization_algorithm_digest
            ),
            "mask_weight_policy_digest": self.mask_weight_policy_digest,
            "statistics_tensor_digests": list(
                self.statistics_tensor_digests
            ),
            "normalization_shard_digest": self.normalization_shard_digest,
            "contract": self.contract,
        }

    @property
    def json(self) -> str:
        return json.dumps(
            self.payload | {"artifact_digest": self.artifact_digest},
            sort_keys=True,
            separators=(",", ":"),
        )


def _normalization_derivation_from_json(
    text: str,
    *,
    expected_digest: str,
) -> NormalizationDerivationArtifact:
    try:
        payload = json.loads(text)
        if not isinstance(payload, dict):
            raise TypeError
        values = dict(payload)
        stored_digest = values.pop("artifact_digest")
        for name in (
            "ordered_train_member_digests",
            "train_case_ids",
            "channel_definitions",
            "statistics_tensor_digests",
        ):
            values[name] = tuple(values[name])
        artifact = NormalizationDerivationArtifact(**cast(Any, values))
    except (KeyError, TypeError, ValueError) as error:
        raise ValueError("normalization derivation is invalid") from error
    if (
        stored_digest != expected_digest
        or artifact.artifact_digest != expected_digest
        or text != artifact.json
    ):
        raise ValueError("normalization derivation digest mismatch")
    return artifact


def recompute_training_normalization_statistics(
    feature_tensors: tuple[Tensor, ...],
    *,
    channel_definitions: tuple[str, ...],
) -> Tensor:
    """Recompute exact train-only per-channel mean/population standard deviation."""

    if (
        not feature_tensors
        or not channel_definitions
        or any(
            not isinstance(tensor, Tensor)
            or not tensor.is_floating_point()
            or tensor.ndim < 2
            or tensor.shape[0] != len(channel_definitions)
            or tensor.numel() == 0
            or not bool(torch.all(torch.isfinite(tensor)))
            for tensor in feature_tensors
        )
    ):
        raise ValueError("normalization feature tensors are invalid")
    flattened = tuple(
        tensor.detach().to(device="cpu", dtype=torch.float64).reshape(
            len(channel_definitions), -1
        )
        for tensor in feature_tensors
    )
    total_count = sum(item.shape[1] for item in flattened)
    if total_count <= 0:
        raise ValueError("normalization feature tensors are empty")
    channel_sum = sum(
        (item.sum(dim=1) for item in flattened),
        start=torch.zeros(len(channel_definitions), dtype=torch.float64),
    )
    mean = channel_sum / float(total_count)
    squared_error_sum = sum(
        (((item - mean[:, None]) ** 2).sum(dim=1) for item in flattened),
        start=torch.zeros(len(channel_definitions), dtype=torch.float64),
    )
    standard_deviation = torch.sqrt(squared_error_sum / float(total_count))
    result = torch.stack((mean, standard_deviation))
    if not bool(torch.all(torch.isfinite(result))):
        raise ValueError("normalization statistics are nonfinite")
    return result


@dataclass(frozen=True)
class TrainingFeatureDatasetArtifact:
    """Exact ordered feature/target dataset archive manifest.

    Feature digests are reproduced by the product-owned five-channel builder
    recorded in each signed analysis derivation. Target bytes live in the
    content-addressed target archive and are bound with their generation
    contract, order, split, weight, normalization and augmentation seed.
    """

    members: tuple[TrainingDatasetMember, ...]
    normalization_statistics_digest: str
    feature_algorithm_digest: str
    feature_schema_digest: str
    target_algorithm_digest: str
    target_schema_digest: str
    feature_archive_shards: tuple[TrainingTensorArchiveShard, ...]
    target_archive_shards: tuple[TrainingTensorArchiveShard, ...]
    normalization_statistics_shard: TrainingTensorArchiveShard
    normalization_derivation_artifact_json: str
    normalization_derivation_artifact_digest: str
    maximum_shard_count: int = 4096
    maximum_total_archive_bytes: int = 64 * 1024**3
    maximum_total_expanded_bytes: int = 256 * 1024**3
    maximum_member_count: int = 1_000_000
    contract: str = "training-feature-dataset-artifact-v5"
    dataset_digest: str = field(init=False)

    def __post_init__(self) -> None:
        count = len(self.members)
        if (
            self.contract != "training-feature-dataset-artifact-v5"
            or count == 0
            or len(set(self.sample_order)) != count
            or len(set(self.feature_archive_member_names)) != count
            or len(set(self.target_archive_member_names)) != count
            or len(set(self.target_valid_mask_archive_member_names)) != count
            or len(set(self.target_quality_archive_member_names)) != count
            or type(self.maximum_shard_count) is not int
            or not 0 < self.maximum_shard_count <= 4096
            or type(self.maximum_total_archive_bytes) is not int
            or not 0 < self.maximum_total_archive_bytes <= 64 * 1024**3
            or type(self.maximum_total_expanded_bytes) is not int
            or not 0 < self.maximum_total_expanded_bytes <= 256 * 1024**3
            or type(self.maximum_member_count) is not int
            or not 0 < self.maximum_member_count <= 1_000_000
        ):
            raise ValueError("training feature dataset manifest is invalid")
        for name, values in (
            (
                "training member derivation",
                self.member_analysis_derivation_artifact_digests,
            ),
            ("training feature tensor", self.member_feature_tensor_digests),
            ("training target tensor", self.member_target_tensor_digests),
        ):
            for value in values:
                _require_digest(name, value)
        for name in (
            "normalization_statistics_digest",
            "feature_algorithm_digest",
            "feature_schema_digest",
            "target_algorithm_digest",
            "target_schema_digest",
            "normalization_derivation_artifact_digest",
        ):
            _require_digest(name, getattr(self, name))
        if (
            not self.feature_archive_shards
            or not self.target_archive_shards
            or any(
                type(item) is not TrainingTensorArchiveShard
                for item in (
                    *self.feature_archive_shards,
                    *self.target_archive_shards,
                    self.normalization_statistics_shard,
                )
            )
            or len({item.shard_id for item in self.feature_archive_shards})
            != len(self.feature_archive_shards)
            or len({item.shard_id for item in self.target_archive_shards})
            != len(self.target_archive_shards)
        ):
            raise ValueError("training feature dataset shards are invalid")
        all_shards = (
            *self.feature_archive_shards,
            *self.target_archive_shards,
            self.normalization_statistics_shard,
        )
        try:
            total_expanded_bytes = sum(
                math.prod(shape) * np.dtype(dtype).itemsize
                for shard in all_shards
                for dtype, shape in zip(
                    shard.member_dtypes,
                    shard.member_shapes,
                    strict=True,
                )
            )
        except TypeError as error:
            raise ValueError("training dataset dtype budget is invalid") from error
        if (
            len(all_shards) > self.maximum_shard_count
            or sum(item.archive_size_bytes for item in all_shards)
            > self.maximum_total_archive_bytes
            or total_expanded_bytes > self.maximum_total_expanded_bytes
            or sum(len(item.member_names) for item in all_shards)
            > self.maximum_member_count
            or len({item.shard_digest for item in all_shards}) != len(all_shards)
            or len({item.artifact_store_id for item in all_shards}) != 1
        ):
            raise ValueError("training dataset exceeds its aggregate budget")
        target_derivations = tuple(
            _training_target_derivation_from_json(
                item.target_derivation_artifact_json
            )
            for item in self.members
        )
        splits_by_event: dict[str, set[str]] = {}
        for member, target in zip(
            self.members,
            target_derivations,
            strict=True,
        ):
            splits_by_event.setdefault(target.physical_event_digest, set()).add(
                member.split
            )
        if any(len(splits) != 1 for splits in splits_by_event.values()):
            raise ValueError("one physical event spans multiple training splits")
        if (
            tuple(item.case_id for item in target_derivations)
            != self.sample_order
            or tuple(item.target_tensor_digest for item in target_derivations)
            != self.member_target_tensor_digests
            or {item.target_algorithm_digest for item in target_derivations}
            != {self.target_algorithm_digest}
            or {item.target_schema_digest for item in target_derivations}
            != {self.target_schema_digest}
        ):
            raise ValueError("training target derivations disagree with dataset")
        feature_manifest = {
            name: digest
            for shard in self.feature_archive_shards
            for name, digest in zip(
                shard.member_names,
                shard.member_tensor_digests,
                strict=True,
            )
        }
        target_manifest = {
            name: digest
            for shard in self.target_archive_shards
            for name, digest in zip(
                shard.member_names,
                shard.member_tensor_digests,
                strict=True,
            )
        }
        feature_schema = {
            name: (dtype, shape)
            for shard in self.feature_archive_shards
            for name, dtype, shape in zip(
                shard.member_names,
                shard.member_dtypes,
                shard.member_shapes,
                strict=True,
            )
        }
        target_archive_schema = {
            name: (dtype, shape)
            for shard in self.target_archive_shards
            for name, dtype, shape in zip(
                shard.member_names,
                shard.member_dtypes,
                shard.member_shapes,
                strict=True,
            )
        }
        if (
            len(feature_manifest)
            != sum(len(item.member_names) for item in self.feature_archive_shards)
            or len(target_manifest)
            != sum(len(item.member_names) for item in self.target_archive_shards)
            or tuple(
                feature_manifest.get(name)
                for name in self.feature_archive_member_names
            )
            != self.member_feature_tensor_digests
            or tuple(target_manifest.get(name) for name in self.target_archive_member_names)
            != self.member_target_tensor_digests
            or tuple(
                target_manifest.get(name)
                for name in self.target_valid_mask_archive_member_names
            )
            != tuple(item.target_valid_mask_digest for item in target_derivations)
            or tuple(
                target_manifest.get(name)
                for name in self.target_quality_archive_member_names
            )
            != tuple(item.target_quality_digest for item in target_derivations)
            or self.normalization_statistics_shard.member_tensor_digests
            != (self.normalization_statistics_digest,)
            or any(
                feature_schema.get(member.feature_archive_member, ("", ()))[0]
                not in {"float16", "float32", "float64"}
                for member in self.members
            )
            or any(
                target_archive_schema.get(
                    member.target_archive_member, ("", ())
                )[0]
                not in {"float16", "float32", "float64"}
                or target_archive_schema.get(
                    member.target_archive_member, ("", ())
                )[1]
                != target.target_shape
                or target_archive_schema.get(
                    member.target_valid_mask_archive_member, ("", ())
                )
                != ("bool", target.target_shape)
                or target_archive_schema.get(
                    member.target_quality_archive_member, ("", ())
                )[0]
                not in {"float16", "float32", "float64"}
                or target_archive_schema.get(
                    member.target_quality_archive_member, ("", ())
                )[1]
                != target.target_shape
                for member, target in zip(
                    self.members, target_derivations, strict=True
                )
            )
        ):
            raise ValueError("training feature dataset shard manifest disagrees")
        target_shard_by_member = {
            name: shard.shard_id
            for shard in self.target_archive_shards
            for name in shard.member_names
        }
        if any(
            len(
                {
                    target_shard_by_member[member.target_archive_member],
                    target_shard_by_member[
                        member.target_valid_mask_archive_member
                    ],
                    target_shard_by_member[member.target_quality_archive_member],
                }
            )
            != 1
            for member in self.members
        ):
            raise ValueError(
                "one training target sample must be contained in one shard"
            )
        members_by_target_name = {
            member.target_archive_member: (member, target)
            for member, target in zip(
                self.members,
                target_derivations,
                strict=True,
            )
        }
        for shard in self.target_archive_shards:
            snapshot = _load_training_tensor_archive_shard_snapshot(shard)
            for target_name in set(snapshot) & set(members_by_target_name):
                member, target_lineage = members_by_target_name[target_name]
                _validate_training_target_snapshot(
                    snapshot[target_name],
                    snapshot[member.target_valid_mask_archive_member],
                    snapshot[member.target_quality_archive_member],
                    expected_shape=target_lineage.target_shape,
                )
        normalization = _normalization_derivation_from_json(
            self.normalization_derivation_artifact_json,
            expected_digest=self.normalization_derivation_artifact_digest,
        )
        train_members = tuple(item for item in self.members if item.split == "train")
        if (
            normalization.ordered_train_member_digests
            != tuple(json_digest(item.payload) for item in train_members)
            or normalization.train_case_ids
            != tuple(item.case_id for item in train_members)
            or normalization.normalization_shard_digest
            != self.normalization_statistics_shard.shard_digest
            or normalization.statistics_tensor_digests
            != self.normalization_statistics_shard.member_tensor_digests
        ):
            raise ValueError(
                "normalization derivation is not train-split exact"
            )
        feature_snapshots: dict[str, Tensor] = {}
        for shard in self.feature_archive_shards:
            snapshot = _load_training_tensor_archive_shard_snapshot(shard)
            if set(feature_snapshots) & set(snapshot):
                raise ValueError("training feature shard members overlap")
            feature_snapshots.update(snapshot)
        try:
            train_feature_tensors = tuple(
                feature_snapshots[item.feature_archive_member]
                for item in train_members
            )
        except KeyError as error:
            raise ValueError("normalization train feature is missing") from error
        recomputed_statistics = recompute_training_normalization_statistics(
            train_feature_tensors,
            channel_definitions=normalization.channel_definitions,
        )
        normalization_snapshot = _load_training_tensor_archive_shard_snapshot(
            self.normalization_statistics_shard
        )
        if (
            set(normalization_snapshot) != {"normalization"}
            or not torch.equal(
                normalization_snapshot["normalization"],
                recomputed_statistics,
            )
            or tensor_digest(recomputed_statistics)
            != self.normalization_statistics_digest
        ):
            raise ValueError(
                "normalization statistics were not recomputed from train features"
            )
        for shard in (
            *self.feature_archive_shards,
            *self.target_archive_shards,
            self.normalization_statistics_shard,
        ):
            _validate_training_tensor_archive_shard(shard)
        object.__setattr__(
            self,
            "dataset_digest",
            json_digest(self.identity_payload),
        )

    @property
    def payload(self) -> dict[str, object]:
        return {
            key: (
                [item.payload for item in value]
                if key in {"members", "feature_archive_shards", "target_archive_shards"}
                else value.payload
                if key == "normalization_statistics_shard"
                else value
            )
            for key, value in self.__dict__.items()
            if key != "dataset_digest"
        }

    @property
    def identity_payload(self) -> dict[str, object]:
        """Return the portable semantic preimage without host absolute paths."""

        return {
            key: (
                [item.payload for item in value]
                if key == "members"
                else [
                    item.identity_payload | {"shard_digest": item.shard_digest}
                    for item in value
                ]
                if key in {"feature_archive_shards", "target_archive_shards"}
                else value.identity_payload
                | {"shard_digest": value.shard_digest}
                if key == "normalization_statistics_shard"
                else value
            )
            for key, value in self.__dict__.items()
            if key != "dataset_digest"
        }

    @property
    def member_analysis_derivation_artifact_digests(self) -> tuple[str, ...]:
        return tuple(item.analysis_derivation_artifact_digest for item in self.members)

    @property
    def member_feature_tensor_digests(self) -> tuple[str, ...]:
        return tuple(item.feature_tensor_digest for item in self.members)

    @property
    def member_target_tensor_digests(self) -> tuple[str, ...]:
        return tuple(item.target_tensor_digest for item in self.members)

    @property
    def member_target_derivation_artifact_jsons(self) -> tuple[str, ...]:
        return tuple(item.target_derivation_artifact_json for item in self.members)

    @property
    def target_derivations(self) -> tuple[TrainingTargetDerivationArtifact, ...]:
        return tuple(
            _training_target_derivation_from_json(text)
            for text in self.member_target_derivation_artifact_jsons
        )

    @property
    def feature_archive_member_names(self) -> tuple[str, ...]:
        return tuple(item.feature_archive_member for item in self.members)

    @property
    def target_archive_member_names(self) -> tuple[str, ...]:
        return tuple(item.target_archive_member for item in self.members)

    @property
    def target_valid_mask_archive_member_names(self) -> tuple[str, ...]:
        return tuple(
            item.target_valid_mask_archive_member for item in self.members
        )

    @property
    def target_quality_archive_member_names(self) -> tuple[str, ...]:
        return tuple(item.target_quality_archive_member for item in self.members)

    @property
    def sample_order(self) -> tuple[str, ...]:
        return tuple(item.case_id for item in self.members)

    @property
    def sample_weights(self) -> tuple[float, ...]:
        return tuple(item.sample_weight for item in self.members)

    @property
    def split_labels(self) -> tuple[str, ...]:
        return tuple(item.split for item in self.members)

    @property
    def augmentation_seeds(self) -> tuple[int, ...]:
        return tuple(item.augmentation_seed for item in self.members)

    def load_validated_tensor_snapshots(self) -> dict[str, Tensor]:
        """Compatibility eager loader for bounded research-sized datasets."""

        if self.dataset_digest != json_digest(self.identity_payload):
            raise ValueError("training feature dataset manifest changed")
        expanded_bytes = sum(
            math.prod(shape) * np.dtype(dtype).itemsize
            for shard in (
                *self.feature_archive_shards,
                *self.target_archive_shards,
                self.normalization_statistics_shard,
            )
            for dtype, shape in zip(
                shard.member_dtypes,
                shard.member_shapes,
                strict=True,
            )
        )
        if expanded_bytes > 1024**3:
            raise ValueError(
                "eager training tensor loading exceeds the 1 GiB compatibility limit"
            )
        tensors: dict[str, Tensor] = {}
        for _shard_id, snapshot in self.iter_validated_tensor_shards():
            for name, tensor in snapshot.items():
                if name in tensors:
                    raise ValueError("training tensor member is duplicated")
                tensors[name] = tensor
        expected = {
            *self.feature_archive_member_names,
            *self.target_archive_member_names,
            *self.target_valid_mask_archive_member_names,
            *self.target_quality_archive_member_names,
            *self.normalization_statistics_shard.member_names,
        }
        if set(tensors) != expected:
            raise ValueError("training tensor snapshot membership changed")
        return {
            name: tensor.detach().clone()
            for name, tensor in tensors.items()
        }

    def iter_validated_tensor_shards(
        self,
    ) -> Iterator[tuple[str, dict[str, Tensor]]]:
        """Yield one verified shard snapshot at a time in manifest order."""

        if self.dataset_digest != json_digest(self.identity_payload):
            raise ValueError("training feature dataset manifest changed")
        seen: set[str] = set()
        for shard in (
            *self.feature_archive_shards,
            *self.target_archive_shards,
            self.normalization_statistics_shard,
        ):
            snapshot = load_training_tensor_archive_shard(shard)
            if seen & set(snapshot):
                raise ValueError("training tensor member is duplicated")
            seen.update(snapshot)
            yield shard.shard_id, snapshot
        expected = {
            *self.feature_archive_member_names,
            *self.target_archive_member_names,
            *self.target_valid_mask_archive_member_names,
            *self.target_quality_archive_member_names,
            *self.normalization_statistics_shard.member_names,
        }
        if seen != expected:
            raise ValueError("training tensor snapshot membership changed")

    @property
    def training_tensor_snapshot_set_digest(self) -> str:
        """Address the exact ordered tensor identities authorized for training."""

        members = sorted(
            (
                (name, digest)
                for shard in (
                    *self.feature_archive_shards,
                    *self.target_archive_shards,
                    self.normalization_statistics_shard,
                )
                for name, digest in zip(
                    shard.member_names,
                    shard.member_tensor_digests,
                    strict=True,
                )
            ),
            key=lambda item: item[0],
        )
        return json_digest(
            {
                "contract": "training-tensor-snapshot-set-v1",
                "training_dataset_digest": self.dataset_digest,
                "members": [
                    {"name": name, "tensor_digest": digest}
                    for name, digest in members
                ],
            }
        )

    def validated_execution_handle(self) -> ValidatedTrainingDatasetHandle:
        """Open and seal the only tensor snapshot authorized for execution."""

        return ValidatedTrainingDatasetHandle.from_dataset(self)


@dataclass(frozen=True, slots=True)
class ValidatedTrainingDatasetHandle:
    """Bounded streaming training input manifest and execution identity."""

    training_dataset_digest: str
    training_tensor_snapshot_set_digest: str
    _dataset_payload_json: str = field(repr=False)
    _ordered_shard_digests: tuple[str, ...] = field(repr=False)
    contract: str = "validated-training-dataset-handle-v2"

    @classmethod
    def from_dataset(
        cls,
        dataset: TrainingFeatureDatasetArtifact,
    ) -> ValidatedTrainingDatasetHandle:
        if type(dataset) is not TrainingFeatureDatasetArtifact:
            raise TypeError("current training feature dataset is required")
        for _shard_id, _snapshot in dataset.iter_validated_tensor_shards():
            pass
        handle = cls(
            training_dataset_digest=dataset.dataset_digest,
            training_tensor_snapshot_set_digest=(
                dataset.training_tensor_snapshot_set_digest
            ),
            _dataset_payload_json=json.dumps(
                dataset.payload | {"dataset_digest": dataset.dataset_digest},
                sort_keys=True,
                separators=(",", ":"),
            ),
            _ordered_shard_digests=tuple(
                item.shard_digest
                for item in (
                    *dataset.feature_archive_shards,
                    *dataset.target_archive_shards,
                    dataset.normalization_statistics_shard,
                )
            ),
        )
        handle.validate_integrity()
        return handle

    def validate_integrity(self) -> None:
        if (
            self.contract != "validated-training-dataset-handle-v2"
            or not self._ordered_shard_digests
            or len(set(self._ordered_shard_digests))
            != len(self._ordered_shard_digests)
        ):
            raise ValueError("validated training dataset handle is invalid")
        dataset = _training_feature_dataset_from_json(
            self._dataset_payload_json,
            expected_digest=self.training_dataset_digest,
        )
        if (
            dataset.training_tensor_snapshot_set_digest
            != self.training_tensor_snapshot_set_digest
            or self._ordered_shard_digests
            != tuple(
                item.shard_digest
                for item in (
                    *dataset.feature_archive_shards,
                    *dataset.target_archive_shards,
                    dataset.normalization_statistics_shard,
                )
            )
        ):
            raise ValueError("validated training tensor snapshot changed")

    def iter_tensor_shards(self) -> Iterator[tuple[str, dict[str, Tensor]]]:
        """Stream defensive snapshots from the exact sealed shard manifest."""

        self.validate_integrity()
        dataset = _training_feature_dataset_from_json(
            self._dataset_payload_json,
            expected_digest=self.training_dataset_digest,
        )
        yield from dataset.iter_validated_tensor_shards()

    def tensor_snapshots(self) -> dict[str, Tensor]:
        """Return defensive clones of the signed execution snapshot."""

        self.validate_integrity()
        snapshots: dict[str, Tensor] = {}
        for _shard_id, snapshot in self.iter_tensor_shards():
            snapshots.update(snapshot)
        return snapshots


def _training_feature_dataset_from_json(
    text: str,
    *,
    expected_digest: str,
) -> TrainingFeatureDatasetArtifact:
    try:
        payload = json.loads(text)
    except json.JSONDecodeError as error:
        raise ValueError("training feature dataset is invalid") from error
    if not isinstance(payload, dict):
        raise ValueError("training feature dataset is invalid")
    values = dict(payload)
    stored_digest = values.pop("dataset_digest", None)
    raw_members = values.get("members")
    if not isinstance(raw_members, list) or any(
        not isinstance(item, dict) for item in raw_members
    ):
        raise ValueError("training feature dataset is invalid")
    try:
        values["members"] = tuple(
            TrainingDatasetMember(**cast(Any, item)) for item in raw_members
        )
        for name in ("feature_archive_shards", "target_archive_shards"):
            raw_shards = values.get(name)
            if not isinstance(raw_shards, list):
                raise TypeError
            decoded_shards: list[TrainingTensorArchiveShard] = []
            for raw_shard in raw_shards:
                if not isinstance(raw_shard, dict):
                    raise TypeError
                shard_values = dict(raw_shard)
                stored_shard_digest = shard_values.pop("shard_digest", None)
                shard_values["member_names"] = tuple(
                    shard_values["member_names"]
                )
                shard_values["member_tensor_digests"] = tuple(
                    shard_values["member_tensor_digests"]
                )
                shard_values["member_dtypes"] = tuple(
                    shard_values["member_dtypes"]
                )
                shard_values["member_shapes"] = tuple(
                    tuple(shape) for shape in shard_values["member_shapes"]
                )
                decoded_shard = TrainingTensorArchiveShard(
                    **cast(Any, shard_values)
                )
                if decoded_shard.shard_digest != stored_shard_digest:
                    raise ValueError("training tensor shard digest mismatch")
                decoded_shards.append(decoded_shard)
            values[name] = tuple(decoded_shards)
        raw_normalization = values.get("normalization_statistics_shard")
        if not isinstance(raw_normalization, dict):
            raise TypeError
        normalization_values = dict(raw_normalization)
        stored_normalization_shard_digest = normalization_values.pop(
            "shard_digest", None
        )
        normalization_values["member_names"] = tuple(
            normalization_values["member_names"]
        )
        normalization_values["member_tensor_digests"] = tuple(
            normalization_values["member_tensor_digests"]
        )
        normalization_values["member_dtypes"] = tuple(
            normalization_values["member_dtypes"]
        )
        normalization_values["member_shapes"] = tuple(
            tuple(shape) for shape in normalization_values["member_shapes"]
        )
        decoded_normalization = TrainingTensorArchiveShard(
            **cast(Any, normalization_values)
        )
        if (
            decoded_normalization.shard_digest
            != stored_normalization_shard_digest
        ):
            raise ValueError("training tensor shard digest mismatch")
        values["normalization_statistics_shard"] = decoded_normalization
    except (TypeError, ValueError) as error:
        raise ValueError("training feature dataset is invalid") from error
    try:
        artifact = TrainingFeatureDatasetArtifact(**cast(Any, values))
    except (TypeError, ValueError) as error:
        raise ValueError("training feature dataset is invalid") from error
    canonical = json.dumps(
        artifact.payload | {"dataset_digest": artifact.dataset_digest},
        sort_keys=True,
        separators=(",", ":"),
    )
    if (
        artifact.dataset_digest != expected_digest
        or stored_digest != expected_digest
        or text != canonical
    ):
        raise ValueError("training feature dataset digest mismatch")
    return artifact


@dataclass(frozen=True)
class TrainingDatasetDerivationArtifact:
    """Content-addressed signed-member training lineage preimage.

    The artifact binds every signed analysis-input derivation preimage and its
    declared feature contract to the dataset consumed by training.  It does
    not claim to execute an arbitrary native decoder or feature pipeline.
    """

    training_raw_registry_receipt_digest: str
    raw_volume_identity_digests: tuple[str, ...]
    sampling_unit_digests: tuple[str, ...]
    training_input_bundle_digests: tuple[str, ...]
    training_full_analysis_input_digests: tuple[str, ...]
    training_grid_contract_digests: tuple[str, ...]
    training_member_analysis_derivation_artifact_jsons: tuple[str, ...]
    decoder_algorithm_digest: str
    qc_algorithm_digest: str
    regrid_algorithm_digest: str
    feature_algorithm_digest: str
    feature_schema_digest: str
    signed_training_member_manifest_digest: str
    training_feature_dataset_artifact_digest: str
    training_feature_dataset_artifact_json: str
    training_physical_event_catalog_plan_digest: str
    training_physical_event_catalog_plan_json: str
    training_physical_event_catalog_result_digest: str
    training_physical_event_catalog_result_json: str
    training_target_source_trust_store_digest: str
    training_target_source_trust_store_json: str
    contract: str = "training-dataset-derivation-artifact-v7"
    training_dataset_digest: str = field(init=False)
    artifact_digest: str = field(init=False)

    def __post_init__(self) -> None:
        if self.contract != "training-dataset-derivation-artifact-v7":
            raise ValueError("unsupported training-dataset derivation artifact")
        for name in (
            "training_raw_registry_receipt_digest",
            "decoder_algorithm_digest",
            "qc_algorithm_digest",
            "regrid_algorithm_digest",
            "feature_algorithm_digest",
            "feature_schema_digest",
            "signed_training_member_manifest_digest",
            "training_feature_dataset_artifact_digest",
            "training_physical_event_catalog_plan_digest",
            "training_physical_event_catalog_result_digest",
            "training_target_source_trust_store_digest",
        ):
            _require_digest(name, getattr(self, name))
        for name, values in (
            ("raw volume identity", self.raw_volume_identity_digests),
            ("sampling unit", self.sampling_unit_digests),
            ("training input bundle", self.training_input_bundle_digests),
            (
                "training full-analysis input",
                self.training_full_analysis_input_digests,
            ),
            ("training grid contract", self.training_grid_contract_digests),
        ):
            if not values or len(values) != len(set(values)):
                raise ValueError(f"{name} derivation inputs are invalid")
            for value in values:
                _require_digest(name, value)
        if (
            not self.training_member_analysis_derivation_artifact_jsons
            or len(self.training_member_analysis_derivation_artifact_jsons)
            != len(self.training_input_bundle_digests)
        ):
            raise ValueError("training member derivation preimages are incomplete")
        member_derivations = tuple(
            _analysis_input_derivation_from_json(text)
            for text in self.training_member_analysis_derivation_artifact_jsons
        )
        feature_dataset = _training_feature_dataset_from_json(
            self.training_feature_dataset_artifact_json,
            expected_digest=self.training_feature_dataset_artifact_digest,
        )
        event_plan, event_result = _decode_training_physical_event_catalog(
            plan_json=self.training_physical_event_catalog_plan_json,
            expected_plan_digest=(
                self.training_physical_event_catalog_plan_digest
            ),
            result_json=self.training_physical_event_catalog_result_json,
            expected_result_digest=(
                self.training_physical_event_catalog_result_digest
            ),
        )
        target_source_trust = _training_target_source_trust_store_from_json(
            self.training_target_source_trust_store_json,
            expected_digest=self.training_target_source_trust_store_digest,
        )
        expected_member_manifest_digest = json_digest(
            {
                "contract": "signed-training-member-manifest-v1",
                "members": sorted(
                    (
                        {
                            "analysis_input_derivation_artifact_digest": (
                                item.artifact_digest
                            ),
                            "processor_id": item.processor_id,
                            "processor_public_key_hex": (
                                item.processor_public_key_hex
                            ),
                        }
                        for item in member_derivations
                    ),
                    key=lambda value: str(
                        value[
                            "analysis_input_derivation_artifact_digest"
                        ]
                    ),
                ),
            }
        )
        if (
            tuple(sorted(item.input_bundle_digest for item in member_derivations))
            != tuple(sorted(self.training_input_bundle_digests))
            or tuple(
                sorted(item.full_analysis_input_digest for item in member_derivations)
            )
            != tuple(sorted(self.training_full_analysis_input_digests))
            or tuple(sorted(item.grid_contract_digest for item in member_derivations))
            != tuple(sorted(self.training_grid_contract_digests))
            or tuple(
                sorted(
                    {
                        digest
                        for item in member_derivations
                        for digest in item.canonical_raw_volume_identity_digests
                    }
                )
            )
            != tuple(sorted(self.raw_volume_identity_digests))
            or {item.decoder_version_digest for item in member_derivations}
            != {self.decoder_algorithm_digest}
            or {item.qc_algorithm_digest for item in member_derivations}
            != {self.qc_algorithm_digest}
            or {item.regrid_algorithm_digest for item in member_derivations}
            != {self.regrid_algorithm_digest}
            or self.signed_training_member_manifest_digest
            != expected_member_manifest_digest
            or feature_dataset.member_analysis_derivation_artifact_digests
            != tuple(item.artifact_digest for item in member_derivations)
            or feature_dataset.sample_order
            != tuple(item.case_id for item in member_derivations)
            or feature_dataset.member_feature_tensor_digests
            != tuple(
                item.learned_model_input_features_digest
                for item in member_derivations
            )
            or feature_dataset.feature_algorithm_digest
            != self.feature_algorithm_digest
            or feature_dataset.feature_schema_digest
            != self.feature_schema_digest
        ):
            raise ValueError("training member derivations disagree with the dataset")
        event_membership: dict[str, tuple[str, str, str, str]] = {}
        for event in event_result.event_evidences:
            for case_id, full_input_digest in zip(
                event.member_case_ids,
                event.member_full_analysis_input_digests,
                strict=True,
            ):
                if case_id in event_membership:
                    raise ValueError(
                        "training case belongs to multiple physical events"
                    )
                event_membership[case_id] = (
                    full_input_digest,
                    event.physical_event_identity_digest,
                    event.start_time,
                    event.end_time,
                )
        target_by_case = {
            item.case_id: item for item in feature_dataset.target_derivations
        }
        for target in target_by_case.values():
            source = _training_target_source_receipt_from_json(
                target.target_source_receipt_json
            )
            source.validate_against(target_source_trust)
            source.validate_against(target_source_trust, at=target.generated_at)
            source.validate_against(
                target_source_trust,
                at=target.training_cutoff_time,
            )
        if (
            tuple(event_plan.holdout_case_ids) != feature_dataset.sample_order
            or set(event_membership) != set(feature_dataset.sample_order)
            or set(target_by_case) != set(feature_dataset.sample_order)
            or any(
                event_membership[member.case_id][0]
                != derivation.full_analysis_input_digest
                or event_membership[member.case_id][1]
                != target_by_case[member.case_id].physical_event_digest
                or not (
                    _canonical_datetime(event_membership[member.case_id][2])
                    <= _canonical_datetime(
                        target_by_case[member.case_id].target_source_valid_time
                    )
                    < _canonical_datetime(event_membership[member.case_id][3])
                )
                for member, derivation in zip(
                    feature_dataset.members,
                    member_derivations,
                    strict=True,
                )
            )
        ):
            raise ValueError(
                "training target event disagrees with signed training catalog"
            )
        object.__setattr__(
            self,
            "training_dataset_digest",
            feature_dataset.dataset_digest,
        )
        object.__setattr__(
            self,
            "artifact_digest",
            json_digest(self.identity_payload),
        )

    @property
    def training_case_ids(self) -> tuple[str, ...]:
        feature_dataset = _training_feature_dataset_from_json(
            self.training_feature_dataset_artifact_json,
            expected_digest=self.training_feature_dataset_artifact_digest,
        )
        return feature_dataset.sample_order

    @property
    def target_derivations(self) -> tuple[TrainingTargetDerivationArtifact, ...]:
        feature_dataset = _training_feature_dataset_from_json(
            self.training_feature_dataset_artifact_json,
            expected_digest=self.training_feature_dataset_artifact_digest,
        )
        return tuple(
            _training_target_derivation_from_json(text)
            for text in feature_dataset.member_target_derivation_artifact_jsons
        )

    @property
    def training_physical_event_catalog(
        self,
    ) -> tuple[PhysicalEventCatalogPlan, PhysicalEventCatalogResult]:
        return _decode_training_physical_event_catalog(
            plan_json=self.training_physical_event_catalog_plan_json,
            expected_plan_digest=(
                self.training_physical_event_catalog_plan_digest
            ),
            result_json=self.training_physical_event_catalog_result_json,
            expected_result_digest=(
                self.training_physical_event_catalog_result_digest
            ),
        )

    @property
    def training_tensor_snapshot_set_digest(self) -> str:
        feature_dataset = _training_feature_dataset_from_json(
            self.training_feature_dataset_artifact_json,
            expected_digest=self.training_feature_dataset_artifact_digest,
        )
        return feature_dataset.training_tensor_snapshot_set_digest

    @property
    def normalization_derivation_artifact_digest(self) -> str:
        feature_dataset = _training_feature_dataset_from_json(
            self.training_feature_dataset_artifact_json,
            expected_digest=self.training_feature_dataset_artifact_digest,
        )
        return feature_dataset.normalization_derivation_artifact_digest

    @property
    def training_target_source_trust_store(
        self,
    ) -> TrainingTargetSourceTrustStore:
        return _training_target_source_trust_store_from_json(
            self.training_target_source_trust_store_json,
            expected_digest=self.training_target_source_trust_store_digest,
        )

    def validate_target_source_trust_at(
        self,
        trust_store: TrainingTargetSourceTrustStore,
        *,
        at: str,
    ) -> None:
        """Revalidate every training truth source at an execution boundary."""

        if (
            type(trust_store) is not TrainingTargetSourceTrustStore
            or trust_store.root_authority_id
            != self.training_target_source_trust_store.root_authority_id
            or trust_store.root_public_key_hex
            != self.training_target_source_trust_store.root_public_key_hex
        ):
            raise ValueError("training target-source trust root changed")
        canonical_at = _canonical_time(at)
        for target in self.target_derivations:
            source = _training_target_source_receipt_from_json(
                target.target_source_receipt_json
            )
            source.validate_against(
                trust_store,
                at=canonical_at,
                require_bound_digest=False,
            )

    @property
    def dataset_payload(self) -> dict[str, object]:
        return {
            "contract": "derived-training-dataset-v7",
            "training_raw_registry_receipt_digest": (
                self.training_raw_registry_receipt_digest
            ),
            "raw_volume_identity_digests": sorted(
                self.raw_volume_identity_digests
            ),
            "sampling_unit_digests": sorted(self.sampling_unit_digests),
            "training_input_bundle_digests": sorted(
                self.training_input_bundle_digests
            ),
            "training_full_analysis_input_digests": sorted(
                self.training_full_analysis_input_digests
            ),
            "training_grid_contract_digests": sorted(
                self.training_grid_contract_digests
            ),
            "training_member_analysis_derivation_artifact_jsons": list(
                self.training_member_analysis_derivation_artifact_jsons
            ),
            "decoder_algorithm_digest": self.decoder_algorithm_digest,
            "qc_algorithm_digest": self.qc_algorithm_digest,
            "regrid_algorithm_digest": self.regrid_algorithm_digest,
            "feature_algorithm_digest": self.feature_algorithm_digest,
            "feature_schema_digest": self.feature_schema_digest,
            "signed_training_member_manifest_digest": (
                self.signed_training_member_manifest_digest
            ),
            "training_feature_dataset_artifact_digest": (
                self.training_feature_dataset_artifact_digest
            ),
            "training_feature_dataset_artifact_json": (
                self.training_feature_dataset_artifact_json
            ),
            "training_physical_event_catalog_plan_digest": (
                self.training_physical_event_catalog_plan_digest
            ),
            "training_physical_event_catalog_plan_json": (
                self.training_physical_event_catalog_plan_json
            ),
            "training_physical_event_catalog_result_digest": (
                self.training_physical_event_catalog_result_digest
            ),
            "training_physical_event_catalog_result_json": (
                self.training_physical_event_catalog_result_json
            ),
            "training_target_source_trust_store_digest": (
                self.training_target_source_trust_store_digest
            ),
            "training_target_source_trust_store_json": (
                self.training_target_source_trust_store_json
            ),
        }

    @property
    def payload(self) -> dict[str, object]:
        return self.dataset_payload | {
            "contract": self.contract,
            "training_dataset_digest": self.training_dataset_digest,
        }

    @property
    def identity_payload(self) -> dict[str, object]:
        """Semantic derivation identity independent of host shard locators."""

        result = dict(self.payload)
        result.pop("training_feature_dataset_artifact_json")
        return result


def _training_dataset_derivation_from_json(
    text: str,
    *,
    expected_digest: str,
) -> TrainingDatasetDerivationArtifact:
    try:
        payload = json.loads(text)
    except json.JSONDecodeError as error:
        raise ValueError("training-dataset derivation is invalid") from error
    if not isinstance(payload, dict):
        raise ValueError("training-dataset derivation is invalid")
    values = dict(payload)
    stored_dataset_digest = values.pop("training_dataset_digest", None)
    for name in (
        "raw_volume_identity_digests",
        "sampling_unit_digests",
        "training_input_bundle_digests",
        "training_full_analysis_input_digests",
        "training_grid_contract_digests",
        "training_member_analysis_derivation_artifact_jsons",
    ):
        retained = values.get(name)
        if not isinstance(retained, list):
            raise ValueError("training-dataset derivation is invalid")
        values[name] = tuple(retained)
    try:
        artifact = TrainingDatasetDerivationArtifact(**cast(Any, values))
    except (TypeError, ValueError) as error:
        raise ValueError("training-dataset derivation is invalid") from error
    if (
        artifact.artifact_digest != expected_digest
        or artifact.training_dataset_digest != stored_dataset_digest
        or text
        != json.dumps(artifact.payload, sort_keys=True, separators=(",", ":"))
    ):
        raise ValueError("training-dataset derivation digest mismatch")
    return artifact


def _validate_training_derivation_processor_authority(
    artifact: TrainingDatasetDerivationArtifact,
    *,
    processor_id: str,
    processor_public_key_hex: str,
    target_source_authority_id: str,
    target_source_authority_public_key_hex: str,
    target_source_trust_store: TrainingTargetSourceTrustStore,
) -> None:
    """Bind processors and independent target sources to preregistered keys."""

    members = tuple(
        _analysis_input_derivation_from_json(text)
        for text in artifact.training_member_analysis_derivation_artifact_jsons
    )
    feature_dataset = _training_feature_dataset_from_json(
        artifact.training_feature_dataset_artifact_json,
        expected_digest=artifact.training_feature_dataset_artifact_digest,
    )
    targets = tuple(
        _training_target_derivation_from_json(text)
        for text in feature_dataset.member_target_derivation_artifact_jsons
    )
    if (
        type(target_source_trust_store) is not TrainingTargetSourceTrustStore
        or artifact.training_target_source_trust_store_digest
        != target_source_trust_store.content_digest
    ):
        raise ValueError("training target source authority trust store changed")
    if any(
        item.processor_id != processor_id
        or item.processor_public_key_hex != processor_public_key_hex
        for item in members
    ) or any(
        item.processor_id != processor_id
        or item.processor_public_key_hex != processor_public_key_hex
        for item in targets
    ):
        raise ValueError("training member processor authority is untrusted")
    for target in targets:
        source = _training_target_source_receipt_from_json(
            target.target_source_receipt_json
        )
        if (
            source.authority_id != target_source_authority_id
            or source.authority_public_key_hex
            != target_source_authority_public_key_hex
        ):
            raise ValueError("training target source authority is untrusted")
        source.validate_against(target_source_trust_store)
        source.validate_against(target_source_trust_store, at=target.generated_at)
        source.validate_against(
            target_source_trust_store,
            at=target.training_cutoff_time,
        )


@dataclass(frozen=True)
class RegimeClassifierManifest:
    """Training lineage for one preregistered deployment classifier."""

    classifier_digest: str
    training_dataset_digest: str
    training_case_ids: tuple[str, ...]
    training_input_bundle_digests: tuple[str, ...]
    training_full_analysis_input_digests: tuple[str, ...]
    training_physical_event_digests: tuple[str, ...]
    training_storm_ids: tuple[str, ...]
    training_days: tuple[str, ...]
    training_radar_ids: tuple[str, ...]
    training_grid_contract_digests: tuple[str, ...]
    training_raw_volume_identity_digests: tuple[str, ...]
    training_sampling_unit_digests: tuple[str, ...]
    training_raw_registry_receipt_digest: str
    training_raw_registry_receipt_payload_json: str
    training_dataset_derivation_artifact_digest: str
    training_dataset_derivation_artifact_json: str
    training_time_windows: tuple[tuple[str, str], ...]
    training_algorithm_digest: str
    numerical_runtime_digest: str
    reference_label_contract_digest: str
    signed_training_member_manifest_digest: str
    contract: str = "neural-prior-regime-classifier-manifest-v10"
    manifest_digest: str = field(init=False)

    def __post_init__(self) -> None:
        if self.contract != "neural-prior-regime-classifier-manifest-v10":
            raise ValueError("unsupported regime-classifier manifest")
        for name in (
            "classifier_digest",
            "training_dataset_digest",
            "training_algorithm_digest",
            "numerical_runtime_digest",
            "reference_label_contract_digest",
            "signed_training_member_manifest_digest",
            "training_raw_registry_receipt_digest",
            "training_dataset_derivation_artifact_digest",
        ):
            _require_digest(name, getattr(self, name))
        for name, values in (
            ("training case", self.training_case_ids),
            ("training storm", self.training_storm_ids),
            ("training day", self.training_days),
            ("training radar", self.training_radar_ids),
        ):
            if (
                not values
                or len(set(values)) != len(values)
                or any(not value or value.strip() != value for value in values)
            ):
                raise ValueError(f"classifier {name} identities are invalid")
        for name, values in (
            ("training input", self.training_input_bundle_digests),
            (
                "training full-analysis input",
                self.training_full_analysis_input_digests,
            ),
            ("training grid contract", self.training_grid_contract_digests),
            ("training physical event", self.training_physical_event_digests),
            (
                "training raw volume identity",
                self.training_raw_volume_identity_digests,
            ),
            ("training sampling unit", self.training_sampling_unit_digests),
        ):
            if not values or len(set(values)) != len(values):
                raise ValueError(f"classifier {name} digests are invalid")
            for value in values:
                _require_digest(name, value)
        registry_receipt = _training_raw_registry_receipt_from_json(
            self.training_raw_registry_receipt_payload_json,
            expected_digest=self.training_raw_registry_receipt_digest,
        )
        if (
            registry_receipt.raw_volume_identity_digests
            != tuple(sorted(self.training_raw_volume_identity_digests))
            or registry_receipt.sampling_unit_digests
            != tuple(sorted(self.training_sampling_unit_digests))
        ):
            raise ValueError("classifier training raw registry preimage disagrees")
        derivation = _training_dataset_derivation_from_json(
            self.training_dataset_derivation_artifact_json,
            expected_digest=self.training_dataset_derivation_artifact_digest,
        )
        if (
            derivation.training_dataset_digest != self.training_dataset_digest
            or derivation.training_case_ids != self.training_case_ids
            or derivation.training_raw_registry_receipt_digest
            != self.training_raw_registry_receipt_digest
            or derivation.raw_volume_identity_digests
            != tuple(sorted(self.training_raw_volume_identity_digests))
            or derivation.sampling_unit_digests
            != tuple(sorted(self.training_sampling_unit_digests))
            or derivation.training_input_bundle_digests
            != tuple(sorted(self.training_input_bundle_digests))
            or derivation.training_full_analysis_input_digests
            != tuple(sorted(self.training_full_analysis_input_digests))
            or derivation.training_grid_contract_digests
            != tuple(sorted(self.training_grid_contract_digests))
            or derivation.signed_training_member_manifest_digest
            != self.signed_training_member_manifest_digest
            or {
                item.physical_event_digest
                for item in derivation.target_derivations
            }
            != set(self.training_physical_event_digests)
        ):
            raise ValueError("classifier training-dataset derivation disagrees")
        windows = tuple(
            (_canonical_time(start), _canonical_time(end))
            for start, end in self.training_time_windows
        )
        if not windows or any(
            _canonical_datetime(start) >= _canonical_datetime(end)
            for start, end in windows
        ):
            raise ValueError("classifier training windows are invalid")
        if any(
            not any(
                _canonical_datetime(start)
                <= _canonical_datetime(item.target_source_valid_time)
                < _canonical_datetime(end)
                for start, end in windows
            )
            for item in derivation.target_derivations
        ):
            raise ValueError("classifier target is outside its training window")
        object.__setattr__(self, "training_time_windows", windows)
        object.__setattr__(self, "manifest_digest", json_digest(self.payload))

    @property
    def payload(self) -> dict[str, object]:
        return {
            "contract": self.contract,
            "classifier_digest": self.classifier_digest,
            "training_dataset_digest": self.training_dataset_digest,
            "training_case_ids": list(self.training_case_ids),
            "training_input_bundle_digests": list(
                self.training_input_bundle_digests
            ),
            "training_full_analysis_input_digests": list(
                self.training_full_analysis_input_digests
            ),
            "training_physical_event_digests": list(
                self.training_physical_event_digests
            ),
            "training_storm_ids": list(self.training_storm_ids),
            "training_days": list(self.training_days),
            "training_radar_ids": list(self.training_radar_ids),
            "training_grid_contract_digests": list(
                self.training_grid_contract_digests
            ),
            "training_raw_volume_identity_digests": list(
                self.training_raw_volume_identity_digests
            ),
            "training_sampling_unit_digests": list(
                self.training_sampling_unit_digests
            ),
            "training_raw_registry_receipt_digest": (
                self.training_raw_registry_receipt_digest
            ),
            "training_raw_registry_receipt_payload_json": (
                self.training_raw_registry_receipt_payload_json
            ),
            "training_dataset_derivation_artifact_digest": (
                self.training_dataset_derivation_artifact_digest
            ),
            "training_dataset_derivation_artifact_json": (
                self.training_dataset_derivation_artifact_json
            ),
            "training_time_windows": [list(value) for value in self.training_time_windows],
            "training_algorithm_digest": self.training_algorithm_digest,
            "numerical_runtime_digest": self.numerical_runtime_digest,
            "reference_label_contract_digest": self.reference_label_contract_digest,
            "signed_training_member_manifest_digest": (
                self.signed_training_member_manifest_digest
            ),
        }


@dataclass(frozen=True)
class RegimeReferencePlan:
    """Preregistered rule for producing a weather-regime label after issue."""

    case_id: str
    labeler_id: str
    labeler_public_key_hex: str
    source_contract_digest: str
    labeling_valid_time: str
    adjudication_policy_digest: str
    contract: str = "neural-prior-regime-reference-plan-v1"
    plan_digest: str = field(init=False)

    def __post_init__(self) -> None:
        if (
            self.contract != "neural-prior-regime-reference-plan-v1"
            or not self.case_id
            or self.case_id.strip() != self.case_id
            or not self.labeler_id
            or self.labeler_id.strip() != self.labeler_id
        ):
            raise ValueError("regime-reference plan identity is invalid")
        if (
            len(self.labeler_public_key_hex) != 64
            or any(
                character not in "0123456789abcdef"
                for character in self.labeler_public_key_hex
            )
        ):
            raise ValueError("regime-reference labeler key is invalid")
        try:
            Ed25519PublicKey.from_public_bytes(
                bytes.fromhex(self.labeler_public_key_hex)
            )
        except ValueError as error:
            raise ValueError("regime-reference labeler key is invalid") from error
        for name in ("source_contract_digest", "adjudication_policy_digest"):
            _require_digest(name, getattr(self, name))
        object.__setattr__(
            self,
            "labeling_valid_time",
            _canonical_time(self.labeling_valid_time),
        )
        object.__setattr__(self, "plan_digest", json_digest(self.payload))

    @property
    def payload(self) -> dict[str, object]:
        return {
            key: value
            for key, value in self.__dict__.items()
            if key != "plan_digest"
        }


@dataclass(frozen=True, init=False)
class RegimeReferenceEvidence:
    """Signed post-event weather label bound to one completed holdout case."""

    reference_plan_digest: str
    full_analysis_input_digest: str
    verification_bundle_digest: str
    observed_regime: str
    observed_storm_id: str
    labeler_id: str
    labeled_at: str
    labeler_signature: str
    contract: str = "neural-prior-regime-reference-evidence-v1"
    evidence_digest: str = field(init=False)

    def __init__(self) -> None:
        raise TypeError("use RegimeReferenceEvidence.from_plan")

    @property
    def payload(self) -> dict[str, object]:
        return {
            key: value
            for key, value in self.__dict__.items()
            if key != "evidence_digest"
        }

    @classmethod
    def from_plan(
        cls,
        plan: RegimeReferencePlan,
        *,
        full_analysis_input_digest: str,
        verification_bundle_digest: str,
        observed_regime: str,
        observed_storm_id: str,
        labeled_at: str,
        labeler_private_key: Ed25519PrivateKey,
    ) -> RegimeReferenceEvidence:
        labeled = _canonical_time(labeled_at)
        if _canonical_datetime(labeled) < _canonical_datetime(
            plan.labeling_valid_time
        ):
            raise ValueError("regime reference was labeled before its valid time")
        for name, value in (
            ("full_analysis_input_digest", full_analysis_input_digest),
            ("verification_bundle_digest", verification_bundle_digest),
        ):
            _require_digest(name, value)
        for name, value in (
            ("observed_regime", observed_regime),
            ("observed_storm_id", observed_storm_id),
        ):
            if not value or value.strip() != value:
                raise ValueError(f"{name} must be canonical")
        values: dict[str, object] = {
            "reference_plan_digest": plan.plan_digest,
            "full_analysis_input_digest": full_analysis_input_digest,
            "verification_bundle_digest": verification_bundle_digest,
            "observed_regime": observed_regime,
            "observed_storm_id": observed_storm_id,
            "labeler_id": plan.labeler_id,
            "labeled_at": labeled,
            "labeler_signature": "",
            "contract": "neural-prior-regime-reference-evidence-v1",
        }
        signature = labeler_private_key.sign(
            json_digest(values).encode("ascii")
        ).hex()
        return _new_regime_reference_evidence(
            **{**values, "labeler_signature": signature}
        )


def _new_regime_reference_evidence(
    **values: object,
) -> RegimeReferenceEvidence:
    result = object.__new__(RegimeReferenceEvidence)
    for name, value in values.items():
        object.__setattr__(result, name, value)
    object.__setattr__(result, "evidence_digest", json_digest(result.payload))
    return result


def validate_regime_reference_evidence(
    evidence: RegimeReferenceEvidence,
    plan: RegimeReferencePlan,
) -> None:
    if (
        evidence.contract != "neural-prior-regime-reference-evidence-v1"
        or evidence.reference_plan_digest != plan.plan_digest
        or evidence.labeler_id != plan.labeler_id
        or evidence.evidence_digest != json_digest(evidence.payload)
        or _canonical_datetime(evidence.labeled_at)
        < _canonical_datetime(plan.labeling_valid_time)
        or len(evidence.labeler_signature) != 128
    ):
        raise ValueError("regime-reference evidence is invalid")
    unsigned = dict(evidence.payload)
    unsigned["labeler_signature"] = ""
    try:
        Ed25519PublicKey.from_public_bytes(
            bytes.fromhex(plan.labeler_public_key_hex)
        ).verify(
            bytes.fromhex(evidence.labeler_signature),
            json_digest(unsigned).encode("ascii"),
        )
    except (InvalidSignature, ValueError) as error:
        raise ValueError("regime-reference signature mismatch") from error


def regime_reference_public_key_hex(
    private_key: Ed25519PrivateKey,
) -> str:
    """Return the canonical raw public key committed by a reference plan."""

    return private_key.public_key().public_bytes(
        serialization.Encoding.Raw,
        serialization.PublicFormat.Raw,
    ).hex()


@dataclass(frozen=True)
class PhysicalEventCatalogPlan:
    """Outcome-blind commitment for grouping all holdout cases into events."""

    holdout_case_ids: tuple[str, ...]
    association_algorithm_digest: str
    spatial_membership_rule_digest: str
    adjudication_policy_digest: str
    adjudicator_id: str
    adjudicator_public_key_hex: str
    catalog_completion_deadline: str
    spatial_reference_digest: str
    motion_association_rule_digest: str
    scheduler_id: str
    scheduler_public_key_hex: str
    scheduler_trust_store_digest: str
    maximum_association_time_gap_minutes: float = 30.0
    minimum_association_spatial_iou: float = 0.1
    maximum_association_centroid_speed_mps: float = 40.0
    association_motion_buffer_m: float = 5_000.0
    contract: str = "physical-event-catalog-plan-v3"
    plan_digest: str = field(init=False)

    def __post_init__(self) -> None:
        if self.contract != "physical-event-catalog-plan-v3":
            raise ValueError("unsupported physical event-catalog plan")
        if (
            not self.holdout_case_ids
            or len(set(self.holdout_case_ids)) != len(self.holdout_case_ids)
            or any(not value or value.strip() != value for value in self.holdout_case_ids)
        ):
            raise ValueError("event-catalog plan cases must be nonempty and unique")
        for name in (
            "association_algorithm_digest",
            "spatial_membership_rule_digest",
            "adjudication_policy_digest",
            "spatial_reference_digest",
            "motion_association_rule_digest",
            "scheduler_trust_store_digest",
        ):
            _require_digest(name, getattr(self, name))
        if (
            not math.isfinite(self.maximum_association_time_gap_minutes)
            or self.maximum_association_time_gap_minutes < 0.0
            or not math.isfinite(self.minimum_association_spatial_iou)
            or not 0.0 <= self.minimum_association_spatial_iou <= 1.0
            or not math.isfinite(self.maximum_association_centroid_speed_mps)
            or self.maximum_association_centroid_speed_mps <= 0.0
            or not math.isfinite(self.association_motion_buffer_m)
            or self.association_motion_buffer_m < 0.0
        ):
            raise ValueError("event association thresholds are invalid")
        if not self.adjudicator_id or self.adjudicator_id.strip() != self.adjudicator_id:
            raise ValueError("event-catalog adjudicator ID must be canonical")
        if len(self.adjudicator_public_key_hex) != 64:
            raise ValueError("event-catalog adjudicator public key is invalid")
        try:
            bytes.fromhex(self.adjudicator_public_key_hex)
        except ValueError as error:
            raise ValueError("event-catalog adjudicator public key is invalid") from error
        if (
            not self.scheduler_id
            or self.scheduler_id.strip() != self.scheduler_id
            or len(self.scheduler_public_key_hex) != 64
            or self.scheduler_id == self.adjudicator_id
            or self.scheduler_public_key_hex == self.adjudicator_public_key_hex
        ):
            raise ValueError("event-catalog scheduler authority is invalid")
        try:
            bytes.fromhex(self.scheduler_public_key_hex)
        except ValueError as error:
            raise ValueError("event-catalog scheduler authority is invalid") from error
        object.__setattr__(
            self,
            "catalog_completion_deadline",
            _canonical_time(self.catalog_completion_deadline),
        )
        object.__setattr__(self, "plan_digest", json_digest(self.payload))

    @property
    def payload(self) -> dict[str, object]:
        return {
            key: value
            for key, value in self.__dict__.items()
            if key != "plan_digest"
        }


@dataclass(frozen=True, init=False)
class TrustedProcessStartReceipt:
    """Scheduler-signed proof that a catalog existed before a trusted job start."""

    catalog_plan_digest: str
    catalog_result_digest: str
    process_kind: Literal["candidate_training", "candidate_scoring"]
    subject_digests: tuple[str, ...]
    process_algorithm_digest: str
    process_runtime_digest: str
    execution_contract_digest: str
    job_id: str
    launch_nonce: str
    scheduler_sequence_number: int
    previous_receipt_digest: str | None
    started_at: str
    scheduler_id: str
    scheduler_public_key_hex: str
    scheduler_trust_store_digest: str
    scheduler_signature: str
    contract: str = "trusted-process-start-receipt-v2"
    receipt_digest: str = field(init=False)

    def __init__(self) -> None:
        raise TypeError("use TrustedProcessStartReceipt.from_plan")

    @property
    def payload(self) -> dict[str, object]:
        return {
            key: (list(value) if key == "subject_digests" else value)
            for key, value in self.__dict__.items()
            if key != "receipt_digest"
        }

    @classmethod
    def from_plan(
        cls,
        plan: PhysicalEventCatalogPlan,
        *,
        catalog_result_digest: str,
        process_kind: Literal["candidate_training", "candidate_scoring"],
        subject_digests: tuple[str, ...],
        process_algorithm_digest: str,
        process_runtime_digest: str,
        execution_contract_digest: str,
        job_id: str,
        launch_nonce: str,
        scheduler_sequence_number: int,
        previous_receipt_digest: str | None,
        started_at: str,
        scheduler_private_key: Ed25519PrivateKey,
    ) -> TrustedProcessStartReceipt:
        values: dict[str, object] = {
            "catalog_plan_digest": plan.plan_digest,
            "catalog_result_digest": catalog_result_digest,
            "process_kind": process_kind,
            "subject_digests": subject_digests,
            "process_algorithm_digest": process_algorithm_digest,
            "process_runtime_digest": process_runtime_digest,
            "execution_contract_digest": execution_contract_digest,
            "job_id": job_id,
            "launch_nonce": launch_nonce,
            "scheduler_sequence_number": scheduler_sequence_number,
            "previous_receipt_digest": previous_receipt_digest,
            "started_at": _canonical_time(started_at),
            "scheduler_id": plan.scheduler_id,
            "scheduler_public_key_hex": regime_reference_public_key_hex(
                scheduler_private_key
            ),
            "scheduler_trust_store_digest": plan.scheduler_trust_store_digest,
            "scheduler_signature": "",
            "contract": "trusted-process-start-receipt-v2",
        }
        unsigned = _trusted_process_start_payload(values)
        values["scheduler_signature"] = scheduler_private_key.sign(
            json_digest(unsigned).encode("ascii")
        ).hex()
        receipt = _new_trusted_process_start_receipt(**values)
        validate_trusted_process_start_receipt(receipt, plan)
        return receipt


def _trusted_process_start_payload(values: dict[str, object]) -> dict[str, object]:
    subjects = values.get("subject_digests")
    if not isinstance(subjects, tuple) or not all(
        isinstance(value, str) for value in subjects
    ):
        raise ValueError("trusted process subjects are invalid")
    payload = {
        key: value for key, value in values.items() if key != "receipt_digest"
    }
    payload["subject_digests"] = list(subjects)
    return payload


def _new_trusted_process_start_receipt(
    **values: object,
) -> TrustedProcessStartReceipt:
    receipt = object.__new__(TrustedProcessStartReceipt)
    for name, value in values.items():
        object.__setattr__(receipt, name, value)
    object.__setattr__(receipt, "receipt_digest", json_digest(receipt.payload))
    return receipt


def validate_trusted_process_start_receipt(
    receipt: TrustedProcessStartReceipt,
    plan: PhysicalEventCatalogPlan,
    *,
    catalog_result: PhysicalEventCatalogResult | None = None,
) -> None:
    _validate_trusted_process_start_receipt_integrity(receipt)
    if (
        receipt.catalog_plan_digest != plan.plan_digest
        or receipt.scheduler_id != plan.scheduler_id
        or receipt.scheduler_public_key_hex != plan.scheduler_public_key_hex
        or receipt.scheduler_trust_store_digest
        != plan.scheduler_trust_store_digest
    ):
        raise ValueError("trusted process-start receipt authority is invalid")
    if catalog_result is not None and (
        receipt.catalog_result_digest != catalog_result.result_digest
        or _canonical_datetime(catalog_result.cataloged_at)
        >= _canonical_datetime(receipt.started_at)
    ):
        raise ValueError("trusted process start does not follow its event catalog")


def _validate_trusted_process_start_receipt_integrity(
    receipt: TrustedProcessStartReceipt,
) -> None:
    try:
        if (
            receipt.contract != "trusted-process-start-receipt-v2"
            or receipt.process_kind not in ("candidate_training", "candidate_scoring")
            or not receipt.subject_digests
            or len(set(receipt.subject_digests)) != len(receipt.subject_digests)
            or not receipt.job_id
            or receipt.job_id.strip() != receipt.job_id
            or type(receipt.scheduler_sequence_number) is not int
            or receipt.scheduler_sequence_number <= 0
            or receipt.receipt_digest != json_digest(receipt.payload)
            or len(receipt.scheduler_signature) != 128
        ):
            raise ValueError("trusted process-start receipt is invalid")
        _canonical_time(receipt.started_at)
        _require_digest("start receipt catalog result", receipt.catalog_result_digest)
        _require_digest("start receipt algorithm", receipt.process_algorithm_digest)
        _require_digest("start receipt runtime", receipt.process_runtime_digest)
        _require_digest(
            "start receipt execution contract",
            receipt.execution_contract_digest,
        )
        _require_digest("start receipt launch nonce", receipt.launch_nonce)
        _require_digest(
            "start receipt scheduler trust store",
            receipt.scheduler_trust_store_digest,
        )
        if receipt.previous_receipt_digest is not None:
            _require_digest(
                "start receipt predecessor",
                receipt.previous_receipt_digest,
            )
        for digest in receipt.subject_digests:
            _require_digest("start receipt subject", digest)
        unsigned = dict(receipt.payload)
        unsigned["scheduler_signature"] = ""
        Ed25519PublicKey.from_public_bytes(
            bytes.fromhex(receipt.scheduler_public_key_hex)
        ).verify(
            bytes.fromhex(receipt.scheduler_signature),
            json_digest(unsigned).encode("ascii"),
        )
    except (InvalidSignature, ValueError) as error:
        raise ValueError("trusted process-start receipt is invalid") from error


@dataclass(frozen=True, init=False)
class TrustedProcessCompletionReceipt:
    """Scheduler-signed result bound to one ledger-recorded process start."""

    start_receipt_digest: str
    catalog_plan_digest: str
    catalog_result_digest: str
    process_kind: Literal["candidate_training", "candidate_scoring"]
    subject_digests: tuple[str, ...]
    process_algorithm_digest: str
    process_runtime_digest: str
    execution_contract_digest: str
    job_id: str
    launch_nonce: str
    scheduler_sequence_number: int
    started_at: str
    completed_at: str
    output_artifact_digest: str
    process_log_digest: str
    scheduler_id: str
    scheduler_public_key_hex: str
    scheduler_trust_store_digest: str
    scheduler_signature: str
    contract: str = "trusted-process-completion-receipt-v1"
    receipt_digest: str = field(init=False)

    def __init__(self) -> None:
        raise TypeError("use TrustedProcessCompletionReceipt.from_start")

    @property
    def payload(self) -> dict[str, object]:
        return {
            key: (list(value) if key == "subject_digests" else value)
            for key, value in self.__dict__.items()
            if key != "receipt_digest"
        }

    @classmethod
    def from_start(
        cls,
        start: TrustedProcessStartReceipt,
        *,
        completed_at: str,
        output_artifact_digest: str,
        process_log_digest: str,
        scheduler_private_key: Ed25519PrivateKey,
    ) -> TrustedProcessCompletionReceipt:
        values: dict[str, object] = {
            "start_receipt_digest": start.receipt_digest,
            "catalog_plan_digest": start.catalog_plan_digest,
            "catalog_result_digest": start.catalog_result_digest,
            "process_kind": start.process_kind,
            "subject_digests": start.subject_digests,
            "process_algorithm_digest": start.process_algorithm_digest,
            "process_runtime_digest": start.process_runtime_digest,
            "execution_contract_digest": start.execution_contract_digest,
            "job_id": start.job_id,
            "launch_nonce": start.launch_nonce,
            "scheduler_sequence_number": start.scheduler_sequence_number,
            "started_at": start.started_at,
            "completed_at": _canonical_time(completed_at),
            "output_artifact_digest": output_artifact_digest,
            "process_log_digest": process_log_digest,
            "scheduler_id": start.scheduler_id,
            "scheduler_public_key_hex": regime_reference_public_key_hex(
                scheduler_private_key
            ),
            "scheduler_trust_store_digest": start.scheduler_trust_store_digest,
            "scheduler_signature": "",
            "contract": "trusted-process-completion-receipt-v1",
        }
        unsigned = _trusted_process_completion_payload(values)
        values["scheduler_signature"] = scheduler_private_key.sign(
            json_digest(unsigned).encode("ascii")
        ).hex()
        receipt = _new_trusted_process_completion_receipt(**values)
        validate_trusted_process_completion_receipt(receipt, start)
        return receipt


def _trusted_process_completion_payload(
    values: dict[str, object],
) -> dict[str, object]:
    subjects = values.get("subject_digests")
    if not isinstance(subjects, tuple) or not all(
        isinstance(value, str) for value in subjects
    ):
        raise ValueError("trusted process completion subjects are invalid")
    payload = {
        key: value for key, value in values.items() if key != "receipt_digest"
    }
    payload["subject_digests"] = list(subjects)
    return payload


def _new_trusted_process_completion_receipt(
    **values: object,
) -> TrustedProcessCompletionReceipt:
    receipt = object.__new__(TrustedProcessCompletionReceipt)
    for name, value in values.items():
        object.__setattr__(receipt, name, value)
    object.__setattr__(receipt, "receipt_digest", json_digest(receipt.payload))
    return receipt


def validate_trusted_process_completion_receipt(
    receipt: TrustedProcessCompletionReceipt,
    start: TrustedProcessStartReceipt,
) -> None:
    try:
        if (
            receipt.contract != "trusted-process-completion-receipt-v1"
            or receipt.start_receipt_digest != start.receipt_digest
            or receipt.catalog_plan_digest != start.catalog_plan_digest
            or receipt.catalog_result_digest != start.catalog_result_digest
            or receipt.process_kind != start.process_kind
            or receipt.subject_digests != start.subject_digests
            or receipt.process_algorithm_digest != start.process_algorithm_digest
            or receipt.process_runtime_digest != start.process_runtime_digest
            or receipt.execution_contract_digest != start.execution_contract_digest
            or receipt.job_id != start.job_id
            or receipt.launch_nonce != start.launch_nonce
            or receipt.scheduler_sequence_number
            != start.scheduler_sequence_number
            or receipt.started_at != start.started_at
            or receipt.scheduler_id != start.scheduler_id
            or receipt.scheduler_public_key_hex
            != start.scheduler_public_key_hex
            or receipt.scheduler_trust_store_digest
            != start.scheduler_trust_store_digest
            or _canonical_datetime(receipt.completed_at)
            <= _canonical_datetime(start.started_at)
            or receipt.receipt_digest != json_digest(receipt.payload)
            or len(receipt.scheduler_signature) != 128
        ):
            raise ValueError("trusted process-completion receipt is invalid")
        for name, value in (
            ("completion output", receipt.output_artifact_digest),
            ("completion log", receipt.process_log_digest),
        ):
            _require_digest(name, value)
        unsigned = dict(receipt.payload)
        unsigned["scheduler_signature"] = ""
        Ed25519PublicKey.from_public_bytes(
            bytes.fromhex(receipt.scheduler_public_key_hex)
        ).verify(
            bytes.fromhex(receipt.scheduler_signature),
            json_digest(unsigned).encode("ascii"),
        )
    except (InvalidSignature, ValueError) as error:
        raise ValueError("trusted process-completion receipt is invalid") from error


@dataclass(frozen=True)
class PhysicalEventTrackArtifact:
    """Replayable, timestamped object track in one declared projected CRS."""

    timestamps: tuple[str, ...]
    centroid_xy_m: tuple[tuple[float, float], ...]
    object_mask_digests: tuple[str, ...]
    source_radar_ids: tuple[str, ...]
    association_edge_digests: tuple[str, ...]
    spatial_reference_digest: str
    contract: str = "physical-event-track-artifact-v1"
    artifact_digest: str = field(init=False)

    def __post_init__(self) -> None:
        timestamps = tuple(_canonical_time(value) for value in self.timestamps)
        parsed = tuple(
            datetime.fromisoformat(value.replace("Z", "+00:00"))
            for value in timestamps
        )
        if (
            self.contract != "physical-event-track-artifact-v1"
            or len(timestamps) < 2
            or len(set(timestamps)) != len(timestamps)
            or any(first >= second for first, second in zip(parsed, parsed[1:]))
            or len(self.centroid_xy_m) != len(timestamps)
            or len(self.object_mask_digests) != len(timestamps)
            or len(self.source_radar_ids) != len(timestamps)
            or len(self.association_edge_digests) != len(timestamps) - 1
            or any(
                len(point) != 2
                or any(not math.isfinite(value) for value in point)
                for point in self.centroid_xy_m
            )
            or any(not value or value.strip() != value for value in self.source_radar_ids)
        ):
            raise ValueError("physical event track artifact is invalid")
        segment_velocities = _track_segment_velocities(
            timestamps,
            self.centroid_xy_m,
        )
        if any(math.hypot(*velocity) > 40.0 for velocity in segment_velocities):
            raise ValueError("physical event track segment speed exceeds 40 m/s")
        if any(
            math.hypot(
                second[0] - first[0],
                second[1] - first[1],
            )
            / max(
                1.0,
                (
                    parsed[index + 2] - parsed[index]
                ).total_seconds()
                / 2.0,
            )
            > 0.25
            for index, (first, second) in enumerate(
                zip(segment_velocities, segment_velocities[1:])
            )
        ):
            raise ValueError("physical event track acceleration exceeds 0.25 m/s^2")
        _require_digest("track spatial reference", self.spatial_reference_digest)
        for value in self.object_mask_digests:
            _require_digest("track object mask", value)
        for value in self.association_edge_digests:
            _require_digest("track association edge", value)
        object.__setattr__(self, "timestamps", timestamps)
        object.__setattr__(self, "artifact_digest", json_digest(self.payload))

    @property
    def payload(self) -> dict[str, object]:
        return {
            "contract": self.contract,
            "timestamps": list(self.timestamps),
            "centroid_xy_m": [list(point) for point in self.centroid_xy_m],
            "object_mask_digests": list(self.object_mask_digests),
            "source_radar_ids": list(self.source_radar_ids),
            "association_edge_digests": list(self.association_edge_digests),
            "spatial_reference_digest": self.spatial_reference_digest,
        }

    @property
    def mean_velocity_xy_mps(self) -> tuple[float, float]:
        start = datetime.fromisoformat(self.timestamps[0].replace("Z", "+00:00"))
        end = datetime.fromisoformat(self.timestamps[-1].replace("Z", "+00:00"))
        seconds = (end - start).total_seconds()
        return (
            (self.centroid_xy_m[-1][0] - self.centroid_xy_m[0][0]) / seconds,
            (self.centroid_xy_m[-1][1] - self.centroid_xy_m[0][1]) / seconds,
        )

    @property
    def terminal_velocity_xy_mps(self) -> tuple[float, float]:
        """Velocity of the final observed segment for forward association."""

        return _track_segment_velocities(
            self.timestamps,
            self.centroid_xy_m,
        )[-1]


def validate_physical_event_track_artifact(
    artifact: PhysicalEventTrackArtifact,
) -> None:
    """Rehash a replayable track instead of trusting its retained digest."""

    try:
        timestamps = tuple(_canonical_time(value) for value in artifact.timestamps)
        parsed = tuple(
            datetime.fromisoformat(value.replace("Z", "+00:00"))
            for value in timestamps
        )
        if (
            artifact.contract != "physical-event-track-artifact-v1"
            or artifact.artifact_digest != json_digest(artifact.payload)
            or timestamps != artifact.timestamps
            or len(timestamps) < 2
            or any(first >= second for first, second in zip(parsed, parsed[1:]))
            or len(artifact.centroid_xy_m) != len(timestamps)
            or len(artifact.object_mask_digests) != len(timestamps)
            or len(artifact.source_radar_ids) != len(timestamps)
            or len(artifact.association_edge_digests) != len(timestamps) - 1
            or any(
                len(point) != 2
                or any(not math.isfinite(value) for value in point)
                for point in artifact.centroid_xy_m
            )
            or any(
                not value or value.strip() != value
                for value in artifact.source_radar_ids
            )
        ):
            raise ValueError("physical event track artifact is invalid")
        _require_digest("track spatial reference", artifact.spatial_reference_digest)
        for value in artifact.object_mask_digests:
            _require_digest("track object mask", value)
        for value in artifact.association_edge_digests:
            _require_digest("track association edge", value)
        segment_velocities = _track_segment_velocities(
            timestamps,
            artifact.centroid_xy_m,
        )
        if any(math.hypot(*velocity) > 40.0 for velocity in segment_velocities):
            raise ValueError("physical event track segment speed exceeds 40 m/s")
        if any(
            math.hypot(second[0] - first[0], second[1] - first[1])
            / max(
                1.0,
                (parsed[index + 2] - parsed[index]).total_seconds() / 2.0,
            )
            > 0.25
            for index, (first, second) in enumerate(
                zip(segment_velocities, segment_velocities[1:])
            )
        ):
            raise ValueError("physical event track acceleration exceeds 0.25 m/s^2")
    except (AttributeError, ValueError) as error:
        raise ValueError("physical event track artifact is invalid") from error


@dataclass(frozen=True, init=False)
class PhysicalEventCatalogEvidence:
    """Signed, immutable mapping from holdout cases to one physical event."""

    event_id: str
    member_case_ids: tuple[str, ...]
    member_full_analysis_input_digests: tuple[str, ...]
    start_time: str
    end_time: str
    spatial_envelope_xy_m: tuple[float, float, float, float]
    start_centroid_xy_m: tuple[float, float]
    end_centroid_xy_m: tuple[float, float]
    mean_velocity_xy_mps: tuple[float, float]
    object_track_artifact: PhysicalEventTrackArtifact
    object_track_artifact_digest: str
    participating_radar_ids: tuple[str, ...]
    association_algorithm_digest: str
    adjudication_policy_digest: str
    adjudicator_id: str
    adjudicator_public_key_hex: str
    adjudicator_signature: str
    physical_event_identity_digest: str
    contract: str = "physical-event-catalog-evidence-v4"
    event_digest: str = field(init=False)

    def __init__(self) -> None:
        raise TypeError("use PhysicalEventCatalogEvidence.from_members")

    @property
    def payload(self) -> dict[str, object]:
        result = {
            key: value
            for key, value in self.__dict__.items()
            if key not in ("event_digest", "object_track_artifact")
        }
        result["object_track_artifact"] = (
            self.object_track_artifact.payload
            | {"artifact_digest": self.object_track_artifact.artifact_digest}
        )
        return result

    @classmethod
    def from_members(
        cls,
        *,
        event_id: str,
        member_case_ids: tuple[str, ...],
        member_full_analysis_input_digests: tuple[str, ...],
        start_time: str,
        end_time: str,
        spatial_envelope_xy_m: tuple[float, float, float, float],
        object_track_artifact: PhysicalEventTrackArtifact,
        participating_radar_ids: tuple[str, ...],
        association_algorithm_digest: str,
        adjudication_policy_digest: str,
        adjudicator_id: str,
        adjudicator_private_key: Ed25519PrivateKey,
    ) -> PhysicalEventCatalogEvidence:
        values: dict[str, object] = {
            "event_id": event_id,
            "member_case_ids": member_case_ids,
            "member_full_analysis_input_digests": (
                member_full_analysis_input_digests
            ),
            "start_time": _canonical_time(start_time),
            "end_time": _canonical_time(end_time),
            "spatial_envelope_xy_m": spatial_envelope_xy_m,
            "start_centroid_xy_m": object_track_artifact.centroid_xy_m[0],
            "end_centroid_xy_m": object_track_artifact.centroid_xy_m[-1],
            "mean_velocity_xy_mps": object_track_artifact.mean_velocity_xy_mps,
            "object_track_artifact": object_track_artifact,
            "object_track_artifact_digest": object_track_artifact.artifact_digest,
            "participating_radar_ids": participating_radar_ids,
            "association_algorithm_digest": association_algorithm_digest,
            "adjudication_policy_digest": adjudication_policy_digest,
            "adjudicator_id": adjudicator_id,
            "adjudicator_public_key_hex": regime_reference_public_key_hex(
                adjudicator_private_key
            ),
            "adjudicator_signature": "",
            "physical_event_identity_digest": "",
            "contract": "physical-event-catalog-evidence-v4",
        }
        values["physical_event_identity_digest"] = (
            _physical_event_identity_digest(values)
        )
        unsigned = {
            key: value
            for key, value in values.items()
            if key != "object_track_artifact"
        }
        unsigned["object_track_artifact"] = (
            object_track_artifact.payload
            | {"artifact_digest": object_track_artifact.artifact_digest}
        )
        signature = adjudicator_private_key.sign(
            json_digest(unsigned).encode("ascii")
        ).hex()
        return _new_physical_event_catalog_evidence(
            **{**values, "adjudicator_signature": signature}
        )


def _new_physical_event_catalog_evidence(
    **values: object,
) -> PhysicalEventCatalogEvidence:
    result = object.__new__(PhysicalEventCatalogEvidence)
    for name, value in values.items():
        object.__setattr__(result, name, value)
    object.__setattr__(result, "event_digest", json_digest(result.payload))
    validate_physical_event_catalog(result)
    return result


def _physical_event_identity_digest(values: dict[str, object]) -> str:
    return json_digest(
        {
            "contract": "physical-event-identity-v2",
            "start_time": values["start_time"],
            "end_time": values["end_time"],
            "spatial_envelope_xy_m": values["spatial_envelope_xy_m"],
            "start_centroid_xy_m": values["start_centroid_xy_m"],
            "end_centroid_xy_m": values["end_centroid_xy_m"],
            "mean_velocity_xy_mps": values["mean_velocity_xy_mps"],
            "object_track_artifact_digest": values[
                "object_track_artifact_digest"
            ],
            "participating_radar_ids": values["participating_radar_ids"],
            "association_algorithm_digest": values[
                "association_algorithm_digest"
            ],
            "adjudication_policy_digest": values["adjudication_policy_digest"],
        }
    )


def validate_physical_event_catalog(
    evidence: PhysicalEventCatalogEvidence,
) -> None:
    try:
        validate_physical_event_track_artifact(evidence.object_track_artifact)
        start = _canonical_datetime(evidence.start_time)
        end = _canonical_datetime(evidence.end_time)
        minimum_x, minimum_y, maximum_x, maximum_y = (
            evidence.spatial_envelope_xy_m
        )
        motion_values = (
            *evidence.start_centroid_xy_m,
            *evidence.end_centroid_xy_m,
            *evidence.mean_velocity_xy_mps,
        )
        if (
            evidence.contract != "physical-event-catalog-evidence-v4"
            or not evidence.event_id
            or evidence.event_id.strip() != evidence.event_id
            or not evidence.adjudicator_id
            or evidence.adjudicator_id.strip() != evidence.adjudicator_id
            or not evidence.member_case_ids
            or len(set(evidence.member_case_ids)) != len(evidence.member_case_ids)
            or any(not value or value.strip() != value for value in evidence.member_case_ids)
            or len(evidence.member_case_ids)
            != len(evidence.member_full_analysis_input_digests)
            or not evidence.participating_radar_ids
            or len(set(evidence.participating_radar_ids))
            != len(evidence.participating_radar_ids)
            or any(
                not value or value.strip() != value
                for value in evidence.participating_radar_ids
            )
            or start >= end
            or any(
                not math.isfinite(value)
                for value in evidence.spatial_envelope_xy_m
            )
            or minimum_x >= maximum_x
            or minimum_y >= maximum_y
            or len(evidence.start_centroid_xy_m) != 2
            or len(evidence.end_centroid_xy_m) != 2
            or len(evidence.mean_velocity_xy_mps) != 2
            or any(not math.isfinite(value) for value in motion_values)
            or evidence.start_time != evidence.object_track_artifact.timestamps[0]
            or evidence.end_time != evidence.object_track_artifact.timestamps[-1]
            or evidence.start_centroid_xy_m
            != evidence.object_track_artifact.centroid_xy_m[0]
            or evidence.end_centroid_xy_m
            != evidence.object_track_artifact.centroid_xy_m[-1]
            or any(
                not math.isclose(actual, expected, rel_tol=1.0e-12, abs_tol=1.0e-12)
                for actual, expected in zip(
                    evidence.mean_velocity_xy_mps,
                    evidence.object_track_artifact.mean_velocity_xy_mps,
                    strict=True,
                )
            )
            or evidence.object_track_artifact_digest
            != evidence.object_track_artifact.artifact_digest
            or set(evidence.participating_radar_ids)
            != set(evidence.object_track_artifact.source_radar_ids)
            or not (
                minimum_x
                <= evidence.start_centroid_xy_m[0]
                <= maximum_x
                and minimum_y
                <= evidence.start_centroid_xy_m[1]
                <= maximum_y
                and minimum_x
                <= evidence.end_centroid_xy_m[0]
                <= maximum_x
                and minimum_y
                <= evidence.end_centroid_xy_m[1]
                <= maximum_y
            )
            or any(
                not (
                    minimum_x <= point[0] <= maximum_x
                    and minimum_y <= point[1] <= maximum_y
                )
                for point in evidence.object_track_artifact.centroid_xy_m
            )
            or len(evidence.adjudicator_public_key_hex) != 64
            or len(evidence.adjudicator_signature) != 128
            or evidence.physical_event_identity_digest
            != _physical_event_identity_digest(evidence.payload)
            or evidence.event_digest != json_digest(evidence.payload)
        ):
            raise ValueError("physical event-catalog evidence is invalid")
        for name, value in (
            ("association algorithm", evidence.association_algorithm_digest),
            ("adjudication policy", evidence.adjudication_policy_digest),
            ("object track artifact", evidence.object_track_artifact_digest),
        ):
            _require_digest(name, value)
        for value in evidence.member_full_analysis_input_digests:
            _require_digest("event member input", value)
        unsigned = dict(evidence.payload)
        unsigned["adjudicator_signature"] = ""
        Ed25519PublicKey.from_public_bytes(
            bytes.fromhex(evidence.adjudicator_public_key_hex)
        ).verify(
            bytes.fromhex(evidence.adjudicator_signature),
            json_digest(unsigned).encode("ascii"),
        )
    except (AttributeError, InvalidSignature, ValueError) as error:
        raise ValueError("physical event-catalog evidence is invalid") from error


@dataclass(frozen=True)
class PhysicalEventCaseSpatialEvidence:
    """Outcome-blind proof that one case belongs inside one physical event."""

    case_id: str
    full_analysis_input_digest: str
    physical_event_identity_digest: str
    observed_spatial_envelope_xy_m: tuple[float, float, float, float]
    event_spatial_envelope_xy_m: tuple[float, float, float, float]
    spatial_membership_rule_digest: str
    source_object_evidence_digest: str
    track_artifact_digest: str
    track_sample_index: int
    track_sample_time: str
    track_object_mask_digest: str
    input_available_time: str
    spatial_reference_digest: str
    contract: str = "physical-event-case-spatial-evidence-v2"
    evidence_digest: str = field(init=False)

    def __post_init__(self) -> None:
        for name, value in (
            ("case input", self.full_analysis_input_digest),
            ("physical event identity", self.physical_event_identity_digest),
            ("spatial membership rule", self.spatial_membership_rule_digest),
            ("source object evidence", self.source_object_evidence_digest),
            ("track artifact", self.track_artifact_digest),
            ("track object mask", self.track_object_mask_digest),
            ("spatial reference", self.spatial_reference_digest),
        ):
            _require_digest(name, value)
        observed = self.observed_spatial_envelope_xy_m
        event = self.event_spatial_envelope_xy_m
        if (
            self.contract != "physical-event-case-spatial-evidence-v2"
            or not self.case_id
            or self.case_id.strip() != self.case_id
            or any(not math.isfinite(value) for value in (*observed, *event))
            or observed[0] >= observed[2]
            or observed[1] >= observed[3]
            or event[0] >= event[2]
            or event[1] >= event[3]
            or observed[0] < event[0]
            or observed[1] < event[1]
            or observed[2] > event[2]
            or observed[3] > event[3]
            or type(self.track_sample_index) is not int
            or self.track_sample_index < 0
            or self.source_object_evidence_digest
            != self.track_object_mask_digest
        ):
            raise ValueError(
                "physical event case spatial envelope is invalid or outside its event"
            )
        object.__setattr__(
            self,
            "input_available_time",
            _canonical_time(self.input_available_time),
        )
        object.__setattr__(
            self,
            "track_sample_time",
            _canonical_time(self.track_sample_time),
        )
        object.__setattr__(self, "evidence_digest", json_digest(self.payload))

    @property
    def payload(self) -> dict[str, object]:
        return {
            "case_id": self.case_id,
            "full_analysis_input_digest": self.full_analysis_input_digest,
            "physical_event_identity_digest": (
                self.physical_event_identity_digest
            ),
            "observed_spatial_envelope_xy_m": list(
                self.observed_spatial_envelope_xy_m
            ),
            "event_spatial_envelope_xy_m": list(
                self.event_spatial_envelope_xy_m
            ),
            "spatial_membership_rule_digest": (
                self.spatial_membership_rule_digest
            ),
            "source_object_evidence_digest": self.source_object_evidence_digest,
            "track_artifact_digest": self.track_artifact_digest,
            "track_sample_index": self.track_sample_index,
            "track_sample_time": self.track_sample_time,
            "track_object_mask_digest": self.track_object_mask_digest,
            "input_available_time": self.input_available_time,
            "spatial_reference_digest": self.spatial_reference_digest,
            "contract": self.contract,
        }


@dataclass(frozen=True, init=False)
class PhysicalEventCatalogResult:
    """Signed, candidate-neutral result covering one entire holdout plan."""

    catalog_plan_digest: str
    event_evidences: tuple[PhysicalEventCatalogEvidence, ...]
    case_spatial_membership_evidences: tuple[
        PhysicalEventCaseSpatialEvidence, ...
    ]
    cataloged_at: str
    adjudicator_id: str
    adjudicator_public_key_hex: str
    adjudicator_signature: str
    association_graph_digest: str
    contract: str = "physical-event-catalog-result-v3"
    result_digest: str = field(init=False)

    def __init__(self) -> None:
        raise TypeError("use PhysicalEventCatalogResult.from_plan")

    @property
    def payload(self) -> dict[str, object]:
        return {
            "catalog_plan_digest": self.catalog_plan_digest,
            "event_evidences": [
                item.payload | {"event_digest": item.event_digest}
                for item in self.event_evidences
            ],
            "case_spatial_membership_evidences": [
                item.payload | {"evidence_digest": item.evidence_digest}
                for item in self.case_spatial_membership_evidences
            ],
            "cataloged_at": self.cataloged_at,
            "adjudicator_id": self.adjudicator_id,
            "adjudicator_public_key_hex": self.adjudicator_public_key_hex,
            "adjudicator_signature": self.adjudicator_signature,
            "association_graph_digest": self.association_graph_digest,
            "contract": self.contract,
        }

    @classmethod
    def from_plan(
        cls,
        plan: PhysicalEventCatalogPlan,
        *,
        event_evidences: tuple[PhysicalEventCatalogEvidence, ...],
        case_spatial_membership_evidences: tuple[
            PhysicalEventCaseSpatialEvidence, ...
        ],
        cataloged_at: str,
        adjudicator_private_key: Ed25519PrivateKey,
    ) -> PhysicalEventCatalogResult:
        values: dict[str, object] = {
            "catalog_plan_digest": plan.plan_digest,
            "event_evidences": event_evidences,
            "case_spatial_membership_evidences": case_spatial_membership_evidences,
            "cataloged_at": _canonical_time(cataloged_at),
            "adjudicator_id": plan.adjudicator_id,
            "adjudicator_public_key_hex": regime_reference_public_key_hex(
                adjudicator_private_key
            ),
            "adjudicator_signature": "",
            "association_graph_digest": "",
            "contract": "physical-event-catalog-result-v3",
        }
        values["association_graph_digest"] = _event_association_graph_digest(
            plan.plan_digest,
            event_evidences,
        )
        unsigned = _physical_event_catalog_result_payload(values)
        signature = adjudicator_private_key.sign(
            json_digest(unsigned).encode("ascii")
        ).hex()
        result = _new_physical_event_catalog_result(
            **{**values, "adjudicator_signature": signature}
        )
        validate_physical_event_catalog_result(result, plan)
        return result


def _physical_event_catalog_result_payload(
    values: dict[str, object],
) -> dict[str, object]:
    events = cast(tuple[PhysicalEventCatalogEvidence, ...], values["event_evidences"])
    memberships = cast(
        tuple[PhysicalEventCaseSpatialEvidence, ...],
        values["case_spatial_membership_evidences"],
    )
    return {
        "catalog_plan_digest": values["catalog_plan_digest"],
        "event_evidences": [
            item.payload | {"event_digest": item.event_digest} for item in events
        ],
        "case_spatial_membership_evidences": [
            item.payload | {"evidence_digest": item.evidence_digest}
            for item in memberships
        ],
        "cataloged_at": values["cataloged_at"],
        "adjudicator_id": values["adjudicator_id"],
        "adjudicator_public_key_hex": values["adjudicator_public_key_hex"],
        "adjudicator_signature": values["adjudicator_signature"],
        "association_graph_digest": values["association_graph_digest"],
        "contract": values["contract"],
    }


def _new_physical_event_catalog_result(
    **values: object,
) -> PhysicalEventCatalogResult:
    result = object.__new__(PhysicalEventCatalogResult)
    for name, value in values.items():
        object.__setattr__(result, name, value)
    object.__setattr__(result, "result_digest", json_digest(result.payload))
    unsigned = dict(result.payload)
    unsigned["adjudicator_signature"] = ""
    try:
        if (
            result.contract != "physical-event-catalog-result-v3"
            or len(result.adjudicator_public_key_hex) != 64
            or len(result.adjudicator_signature) != 128
        ):
            raise ValueError("physical event-catalog result is invalid")
        Ed25519PublicKey.from_public_bytes(
            bytes.fromhex(result.adjudicator_public_key_hex)
        ).verify(
            bytes.fromhex(result.adjudicator_signature),
            json_digest(unsigned).encode("ascii"),
        )
    except (InvalidSignature, ValueError) as error:
        raise ValueError("physical event-catalog result signature mismatch") from error
    return result


def _event_association_graph_digest(
    plan_digest: str,
    events: tuple[PhysicalEventCatalogEvidence, ...],
) -> str:
    """Address the candidate-neutral event components used for inference."""

    return json_digest(
        {
            "contract": "physical-event-association-graph-v1",
            "catalog_plan_digest": plan_digest,
            "components": [
                {
                    "physical_event_identity_digest": (
                        event.physical_event_identity_digest
                    ),
                    "member_case_ids": sorted(event.member_case_ids),
                    "member_full_analysis_input_digests": sorted(
                        event.member_full_analysis_input_digests
                    ),
                }
                for event in sorted(
                    events,
                    key=lambda item: item.physical_event_identity_digest,
                )
            ],
        }
    )


def _event_spatial_iou(
    first: tuple[float, float, float, float],
    second: tuple[float, float, float, float],
) -> float:
    intersection_x = max(0.0, min(first[2], second[2]) - max(first[0], second[0]))
    intersection_y = max(0.0, min(first[3], second[3]) - max(first[1], second[1]))
    intersection = intersection_x * intersection_y
    first_area = (first[2] - first[0]) * (first[3] - first[1])
    second_area = (second[2] - second[0]) * (second[3] - second[1])
    union = first_area + second_area - intersection
    return 0.0 if union <= 0.0 else intersection / union


def _track_centroid_at(
    track: PhysicalEventTrackArtifact,
    when: datetime,
) -> tuple[float, float]:
    times = tuple(
        datetime.fromisoformat(value.replace("Z", "+00:00"))
        for value in track.timestamps
    )
    if when <= times[0]:
        return track.centroid_xy_m[0]
    if when >= times[-1]:
        return track.centroid_xy_m[-1]
    for index, (start, end) in enumerate(zip(times, times[1:])):
        if start <= when <= end:
            fraction = (when - start).total_seconds() / (end - start).total_seconds()
            first = track.centroid_xy_m[index]
            second = track.centroid_xy_m[index + 1]
            return (
                first[0] + fraction * (second[0] - first[0]),
                first[1] + fraction * (second[1] - first[1]),
            )
    raise ValueError("event track does not bracket the requested time")


def _track_segment_velocities(
    timestamps: tuple[str, ...],
    centroids: tuple[tuple[float, float], ...],
) -> tuple[tuple[float, float], ...]:
    parsed = tuple(
        datetime.fromisoformat(value.replace("Z", "+00:00"))
        for value in timestamps
    )
    return tuple(
        (
            (second_point[0] - first_point[0])
            / (second_time - first_time).total_seconds(),
            (second_point[1] - first_point[1])
            / (second_time - first_time).total_seconds(),
        )
        for first_time, second_time, first_point, second_point in zip(
            parsed[:-1],
            parsed[1:],
            centroids[:-1],
            centroids[1:],
            strict=True,
        )
    )


def _overlap_track_distance(
    first: PhysicalEventTrackArtifact,
    second: PhysicalEventTrackArtifact,
) -> float | None:
    first_times = tuple(
        datetime.fromisoformat(value.replace("Z", "+00:00"))
        for value in first.timestamps
    )
    second_times = tuple(
        datetime.fromisoformat(value.replace("Z", "+00:00"))
        for value in second.timestamps
    )
    overlap_start = max(first_times[0], second_times[0])
    overlap_end = min(first_times[-1], second_times[-1])
    if overlap_start > overlap_end:
        return None
    boundary_times = tuple(
        sorted(
            {
                overlap_start,
                overlap_end,
                *(value for value in first_times if overlap_start <= value <= overlap_end),
                *(value for value in second_times if overlap_start <= value <= overlap_end),
            }
        )
    )
    if len(boundary_times) == 1:
        return math.dist(
            _track_centroid_at(first, boundary_times[0]),
            _track_centroid_at(second, boundary_times[0]),
        )
    minimum = math.inf
    for start, end in zip(
        boundary_times[:-1], boundary_times[1:], strict=True
    ):
        seconds = (end - start).total_seconds()
        first_start = _track_centroid_at(first, start)
        first_end = _track_centroid_at(first, end)
        second_start = _track_centroid_at(second, start)
        second_end = _track_centroid_at(second, end)
        relative_start = (
            first_start[0] - second_start[0],
            first_start[1] - second_start[1],
        )
        relative_velocity = (
            ((first_end[0] - second_end[0]) - relative_start[0]) / seconds,
            ((first_end[1] - second_end[1]) - relative_start[1]) / seconds,
        )
        speed_squared = (
            relative_velocity[0] ** 2 + relative_velocity[1] ** 2
        )
        closest_seconds = (
            0.0
            if speed_squared == 0.0
            else max(
                0.0,
                min(
                    seconds,
                    -(
                        relative_start[0] * relative_velocity[0]
                        + relative_start[1] * relative_velocity[1]
                    )
                    / speed_squared,
                ),
            )
        )
        distance = math.hypot(
            relative_start[0] + relative_velocity[0] * closest_seconds,
            relative_start[1] + relative_velocity[1] * closest_seconds,
        )
        minimum = min(minimum, distance)
    return minimum


def _events_associate(
    first: PhysicalEventCatalogEvidence,
    second: PhysicalEventCatalogEvidence,
    plan: PhysicalEventCatalogPlan,
) -> bool:
    first_start = datetime.fromisoformat(first.start_time.replace("Z", "+00:00"))
    first_end = datetime.fromisoformat(first.end_time.replace("Z", "+00:00"))
    second_start = datetime.fromisoformat(second.start_time.replace("Z", "+00:00"))
    second_end = datetime.fromisoformat(second.end_time.replace("Z", "+00:00"))
    gap_seconds = max(
        0.0,
        (second_start - first_end).total_seconds(),
        (first_start - second_end).total_seconds(),
    )
    overlap_distance = _overlap_track_distance(
        first.object_track_artifact,
        second.object_track_artifact,
    )
    if first_end <= second_start:
        earlier = first
        later = second
    elif second_end <= first_start:
        earlier = second
        later = first
    else:
        earlier = first
        later = second
    predicted_x = (
        earlier.end_centroid_xy_m[0]
        + earlier.object_track_artifact.terminal_velocity_xy_mps[0] * gap_seconds
    )
    predicted_y = (
        earlier.end_centroid_xy_m[1]
        + earlier.object_track_artifact.terminal_velocity_xy_mps[1] * gap_seconds
    )
    centroid_distance = math.hypot(
        later.start_centroid_xy_m[0] - predicted_x,
        later.start_centroid_xy_m[1] - predicted_y,
    )
    maximum_motion_distance = plan.association_motion_buffer_m
    return (
        gap_seconds <= plan.maximum_association_time_gap_minutes * 60.0
        and (
            _event_spatial_iou(
                first.spatial_envelope_xy_m,
                second.spatial_envelope_xy_m,
            )
            >= plan.minimum_association_spatial_iou
            or (
                overlap_distance is not None
                and overlap_distance <= plan.association_motion_buffer_m
            )
            or centroid_distance <= maximum_motion_distance
        )
    )


def validate_physical_event_catalog_result(
    result: PhysicalEventCatalogResult,
    plan: PhysicalEventCatalogPlan,
    *,
    candidate_scoring_started_at: str | None = None,
) -> None:
    try:
        cataloged_at = _canonical_time(result.cataloged_at)
        if (
            result.contract != "physical-event-catalog-result-v3"
            or result.catalog_plan_digest != plan.plan_digest
            or result.adjudicator_id != plan.adjudicator_id
            or result.adjudicator_public_key_hex != plan.adjudicator_public_key_hex
            or result.result_digest != json_digest(result.payload)
            or result.association_graph_digest
            != _event_association_graph_digest(plan.plan_digest, result.event_evidences)
            or _canonical_datetime(cataloged_at)
            > _canonical_datetime(plan.catalog_completion_deadline)
            or len(result.adjudicator_signature) != 128
        ):
            raise ValueError("physical event-catalog result is invalid")
        events = result.event_evidences
        if not events or len({item.event_digest for item in events}) != len(events):
            raise ValueError("physical event-catalog result is incomplete")
        if any(
            _events_associate(first, second, plan)
            for index, first in enumerate(events)
            for second in events[index + 1 :]
        ):
            raise ValueError(
                "physical event association graph has split connected components"
            )
        member_cases: list[str] = []
        for event in events:
            validate_physical_event_catalog(event)
            if (
                event.association_algorithm_digest
                != plan.association_algorithm_digest
                or event.adjudication_policy_digest
                != plan.adjudication_policy_digest
                or event.object_track_artifact.spatial_reference_digest
                != plan.spatial_reference_digest
                or event.adjudicator_id != plan.adjudicator_id
                or event.adjudicator_public_key_hex != plan.adjudicator_public_key_hex
                or math.hypot(*event.mean_velocity_xy_mps)
                > plan.maximum_association_centroid_speed_mps
                or any(
                    math.hypot(*velocity)
                    > plan.maximum_association_centroid_speed_mps
                    for velocity in _track_segment_velocities(
                        event.object_track_artifact.timestamps,
                        event.object_track_artifact.centroid_xy_m,
                    )
                )
            ):
                raise ValueError("physical event-catalog result disagrees with its plan")
            member_cases.extend(event.member_case_ids)
        if (
            len(member_cases) != len(set(member_cases))
            or set(member_cases) != set(plan.holdout_case_ids)
        ):
            raise ValueError("physical event-catalog result membership is incomplete")
        event_by_case = {
            case_id: event
            for event in events
            for case_id in event.member_case_ids
        }
        input_by_case = {
            case_id: input_digest
            for event in events
            for case_id, input_digest in zip(
                event.member_case_ids,
                event.member_full_analysis_input_digests,
                strict=True,
            )
        }
        spatial = result.case_spatial_membership_evidences
        if (
            len(spatial) != len(plan.holdout_case_ids)
            or len({item.case_id for item in spatial}) != len(spatial)
            or {item.case_id for item in spatial} != set(plan.holdout_case_ids)
        ):
            raise ValueError("physical event spatial-membership evidence is incomplete")
        for item in spatial:
            event = event_by_case[item.case_id]
            track = event.object_track_artifact
            if (
                item.evidence_digest != json_digest(item.payload)
                or item.full_analysis_input_digest != input_by_case[item.case_id]
                or item.physical_event_identity_digest
                != event.physical_event_identity_digest
                or item.event_spatial_envelope_xy_m
                != event.spatial_envelope_xy_m
                or item.spatial_membership_rule_digest
                != plan.spatial_membership_rule_digest
                or item.spatial_reference_digest != plan.spatial_reference_digest
                or item.track_artifact_digest != track.artifact_digest
                or item.track_sample_index >= len(track.timestamps)
                or item.track_sample_time
                != track.timestamps[item.track_sample_index]
                or item.track_object_mask_digest
                != track.object_mask_digests[item.track_sample_index]
                or item.source_object_evidence_digest
                != track.object_mask_digests[item.track_sample_index]
            ):
                raise ValueError(
                    "physical event spatial-membership evidence disagrees with catalog"
                )
        if max(
            _canonical_datetime(item.input_available_time) for item in spatial
        ) > _canonical_datetime(cataloged_at):
            raise ValueError(
                "physical event catalog predates member input availability"
            )
        if candidate_scoring_started_at is not None and (
            _canonical_datetime(cataloged_at)
            >= _canonical_datetime(candidate_scoring_started_at)
        ):
            raise ValueError(
                "physical event catalog must be fixed before candidate scoring"
            )
        unsigned = dict(result.payload)
        unsigned["adjudicator_signature"] = ""
        Ed25519PublicKey.from_public_bytes(
            bytes.fromhex(plan.adjudicator_public_key_hex)
        ).verify(
            bytes.fromhex(result.adjudicator_signature),
            json_digest(unsigned).encode("ascii"),
        )
    except InvalidSignature as error:
        raise ValueError("physical event-catalog result signature mismatch") from error


def _physical_event_catalog_plan_json(plan: PhysicalEventCatalogPlan) -> str:
    return json.dumps(
        plan.payload | {"plan_digest": plan.plan_digest},
        sort_keys=True,
        separators=(",", ":"),
    )


def _physical_event_catalog_result_json(
    result: PhysicalEventCatalogResult,
) -> str:
    return json.dumps(
        result.payload | {"result_digest": result.result_digest},
        sort_keys=True,
        separators=(",", ":"),
    )


def _decode_training_physical_event_catalog(
    *,
    plan_json: str,
    expected_plan_digest: str,
    result_json: str,
    expected_result_digest: str,
) -> tuple[PhysicalEventCatalogPlan, PhysicalEventCatalogResult]:
    """Decode and verify the signed training event catalog embedded in lineage."""

    try:
        raw_plan = json.loads(plan_json)
        raw_result = json.loads(result_json)
        if not isinstance(raw_plan, dict) or not isinstance(raw_result, dict):
            raise TypeError
        plan_values = dict(raw_plan)
        stored_plan_digest = plan_values.pop("plan_digest")
        plan_values["holdout_case_ids"] = tuple(
            plan_values["holdout_case_ids"]
        )
        plan = PhysicalEventCatalogPlan(**cast(Any, plan_values))
        if (
            stored_plan_digest != expected_plan_digest
            or plan.plan_digest != expected_plan_digest
            or plan_json != _physical_event_catalog_plan_json(plan)
        ):
            raise ValueError

        result_values = dict(raw_result)
        stored_result_digest = result_values.pop("result_digest")
        events: list[PhysicalEventCatalogEvidence] = []
        for raw_event in result_values.pop("event_evidences"):
            event_values = dict(raw_event)
            stored_event_digest = event_values.pop("event_digest")
            track_values = dict(event_values["object_track_artifact"])
            stored_track_digest = track_values.pop("artifact_digest")
            for name in (
                "timestamps",
                "object_mask_digests",
                "source_radar_ids",
                "association_edge_digests",
            ):
                track_values[name] = tuple(track_values[name])
            track_values["centroid_xy_m"] = tuple(
                tuple(item) for item in track_values["centroid_xy_m"]
            )
            track = PhysicalEventTrackArtifact(**cast(Any, track_values))
            if track.artifact_digest != stored_track_digest:
                raise ValueError
            event_values["object_track_artifact"] = track
            for name in (
                "member_case_ids",
                "member_full_analysis_input_digests",
                "spatial_envelope_xy_m",
                "start_centroid_xy_m",
                "end_centroid_xy_m",
                "mean_velocity_xy_mps",
                "participating_radar_ids",
            ):
                event_values[name] = tuple(event_values[name])
            event = _new_physical_event_catalog_evidence(**event_values)
            if event.event_digest != stored_event_digest:
                raise ValueError
            events.append(event)
        result_values["event_evidences"] = tuple(events)
        spatial: list[PhysicalEventCaseSpatialEvidence] = []
        for raw_evidence in result_values.pop(
            "case_spatial_membership_evidences"
        ):
            evidence_values = dict(raw_evidence)
            stored_evidence_digest = evidence_values.pop("evidence_digest")
            evidence_values["observed_spatial_envelope_xy_m"] = tuple(
                evidence_values["observed_spatial_envelope_xy_m"]
            )
            evidence_values["event_spatial_envelope_xy_m"] = tuple(
                evidence_values["event_spatial_envelope_xy_m"]
            )
            evidence = PhysicalEventCaseSpatialEvidence(
                **cast(Any, evidence_values)
            )
            if evidence.evidence_digest != stored_evidence_digest:
                raise ValueError
            spatial.append(evidence)
        result_values["case_spatial_membership_evidences"] = tuple(spatial)
        result = _new_physical_event_catalog_result(**result_values)
        if (
            stored_result_digest != expected_result_digest
            or result.result_digest != expected_result_digest
            or result_json != _physical_event_catalog_result_json(result)
        ):
            raise ValueError
        validate_physical_event_catalog_result(result, plan)
    except (KeyError, TypeError, ValueError) as error:
        raise ValueError("training physical event catalog is invalid") from error
    return plan, result


@dataclass(frozen=True)
class NeuralPriorHoldoutPlanCase:
    """One case committed before forecasts and verification are available."""

    case_id: str
    storm_id: str
    day: str
    radar_id: str
    regime: str
    range_regime: str
    input_plan_digest: str
    verification_plan_digest: str
    metric_contract_digest: str
    uncertainty_target_plan_digest: str
    state_calibration_target_plan_digest: str
    range_band_contract_digest: str
    reference_active_range_regimes: tuple[str, ...]
    regime_reference_plan_digest: str
    operational_issuance_domain_plan_digest: str
    meteorological_sampling_unit_digest: str
    issue_time: str

    def __post_init__(self) -> None:
        _validate_holdout_case_identity(self)
        for name in (
            "input_plan_digest",
            "verification_plan_digest",
            "metric_contract_digest",
            "uncertainty_target_plan_digest",
            "state_calibration_target_plan_digest",
            "range_band_contract_digest",
            "regime_reference_plan_digest",
            "operational_issuance_domain_plan_digest",
            "meteorological_sampling_unit_digest",
        ):
            _require_digest(name, getattr(self, name))
        if (
            len(set(self.reference_active_range_regimes))
            != len(self.reference_active_range_regimes)
            or any(not value for value in self.reference_active_range_regimes)
        ):
            raise ValueError("reference active range regimes are invalid")
        object.__setattr__(self, "issue_time", _canonical_time(self.issue_time))


