@dataclass(frozen=True)
class PromotionExperimentTrial:
    """One preregistered candidate/rule/classifier trial in a cohort."""

    candidate_prior_digest: str
    promotion_decision_rule_digest: str
    classifier_manifest_digests: tuple[str, ...]
    contract: str = "neural-prior-promotion-experiment-trial-v1"
    trial_digest: str = field(init=False)

    def __post_init__(self) -> None:
        if (
            self.contract != "neural-prior-promotion-experiment-trial-v1"
            or not self.classifier_manifest_digests
            or len(set(self.classifier_manifest_digests))
            != len(self.classifier_manifest_digests)
        ):
            raise ValueError("promotion experiment trial is invalid")
        _require_digest("experiment candidate", self.candidate_prior_digest)
        _require_digest(
            "experiment decision rule", self.promotion_decision_rule_digest
        )
        for digest in self.classifier_manifest_digests:
            _require_digest("experiment classifier manifest", digest)
        object.__setattr__(self, "trial_digest", json_digest(self.payload))

    @property
    def payload(self) -> dict[str, object]:
        return {
            "contract": self.contract,
            "candidate_prior_digest": self.candidate_prior_digest,
            "promotion_decision_rule_digest": (
                self.promotion_decision_rule_digest
            ),
            "classifier_manifest_digests": list(
                self.classifier_manifest_digests
            ),
        }


def _promotion_experiment_scope_digest(
    *,
    holdout_cohort_digest: str,
    parent_prior_digest: str,
    trials: tuple[PromotionExperimentTrial, ...],
    winner_selection_rule_digest: str,
) -> str:
    """Identify one experiment scope before its global reservation exists."""

    return json_digest(
        {
            "contract": "neural-prior-promotion-experiment-scope-v1",
            "holdout_cohort_digest": holdout_cohort_digest,
            "parent_prior_digest": parent_prior_digest,
            "trial_digests": [item.trial_digest for item in trials],
            "winner_selection_rule_digest": winner_selection_rule_digest,
        }
    )


@dataclass(frozen=True)
class PromotionExperimentFamily:
    """Outcome-blind multiplicity contract shared by overlapping plans."""

    holdout_cohort_digest: str
    meteorological_sampling_unit_digests: tuple[str, ...]
    raw_observation_slot_digests: tuple[str, ...]
    global_sampling_reservation: GlobalSamplingReservationReceipt
    parent_prior_digest: str
    trials: tuple[PromotionExperimentTrial, ...]
    winner_selection_rule_digest: str
    contract: str = "neural-prior-promotion-experiment-family-v4"
    family_digest: str = field(init=False)

    def __post_init__(self) -> None:
        if (
            self.contract != "neural-prior-promotion-experiment-family-v4"
            or not self.trials
            or not self.meteorological_sampling_unit_digests
            or len(set(self.meteorological_sampling_unit_digests))
            != len(self.meteorological_sampling_unit_digests)
            or not self.raw_observation_slot_digests
            or len(set(self.raw_observation_slot_digests))
            != len(self.raw_observation_slot_digests)
            or len({item.trial_digest for item in self.trials})
            != len(self.trials)
        ):
            raise ValueError("promotion experiment family is invalid")
        for name in (
            "holdout_cohort_digest",
            "parent_prior_digest",
            "winner_selection_rule_digest",
        ):
            _require_digest(name, getattr(self, name))
        for digest in self.meteorological_sampling_unit_digests:
            _require_digest("meteorological sampling unit", digest)
        for digest in self.raw_observation_slot_digests:
            _require_digest("raw observation slot", digest)
        expected_scope = _promotion_experiment_scope_digest(
            holdout_cohort_digest=self.holdout_cohort_digest,
            parent_prior_digest=self.parent_prior_digest,
            trials=self.trials,
            winner_selection_rule_digest=self.winner_selection_rule_digest,
        )
        if (
            type(self.global_sampling_reservation)
            is not GlobalSamplingReservationReceipt
            or self.global_sampling_reservation.experiment_scope_digest
            != expected_scope
            or self.global_sampling_reservation.raw_observation_slot_digests
            != tuple(sorted(self.raw_observation_slot_digests))
        ):
            raise ValueError("global sampling reservation disagrees with family")
        object.__setattr__(self, "family_digest", json_digest(self.payload))

    @property
    def total_family_size(self) -> int:
        return sum(len(item.classifier_manifest_digests) for item in self.trials)

    @property
    def payload(self) -> dict[str, object]:
        return {
            "contract": self.contract,
            "holdout_cohort_digest": self.holdout_cohort_digest,
            "meteorological_sampling_unit_digests": list(
                self.meteorological_sampling_unit_digests
            ),
            "raw_observation_slot_digests": list(
                self.raw_observation_slot_digests
            ),
            "global_sampling_reservation": (
                self.global_sampling_reservation.payload
                | {
                    "receipt_digest": (
                        self.global_sampling_reservation.receipt_digest
                    )
                }
            ),
            "parent_prior_digest": self.parent_prior_digest,
            "trials": [item.payload for item in self.trials],
            "winner_selection_rule_digest": self.winner_selection_rule_digest,
            "total_family_size": self.total_family_size,
        }


@dataclass(frozen=True)
class NeuralPriorHoldoutPlan:
    """Root-approved holdout commitment created before any evaluated issue."""

    plan_id: str
    parent_prior_digest: str
    candidate_family_digests: tuple[str, ...]
    cases: tuple[NeuralPriorHoldoutPlanCase, ...]
    input_plans: tuple[NeuralPriorInputPlan, ...]
    raw_observation_slot_plans: tuple[RawObservationSlotPlan, ...]
    meteorological_sampling_units: tuple[MeteorologicalSamplingUnit, ...]
    raw_ingestor_trust_store: RawIngestorTrustStore
    training_target_source_trust_store: TrainingTargetSourceTrustStore
    analysis_processor_id: str
    analysis_processor_public_key_hex: str
    training_target_source_authority_id: str
    training_target_source_authority_public_key_hex: str
    uncertainty_target_plans: tuple[PriorUncertaintyTargetPlan, ...]
    state_calibration_target_plans: tuple[
        NeuralPriorStateCalibrationPlan, ...
    ]
    verification_observation_error_plans: tuple[
        VerificationObservationErrorPlan, ...
    ]
    range_band_contracts: tuple[RangeBandContract, ...]
    range_geometry_contracts: tuple[
        RangeGeometryContract | MosaicRangeGeometryContract, ...
    ]
    operational_issuance_domain_plans: tuple[
        OperationalIssuanceDomainPlan, ...
    ]
    regime_reference_plans: tuple[RegimeReferencePlan, ...]
    regime_classifier_manifests: tuple[RegimeClassifierManifest, ...]
    promotion_experiment_family: PromotionExperimentFamily
    promotion_decision_rule_digest: str
    reference_label_contract_digest: str
    physical_event_catalog_plan: PhysicalEventCatalogPlan
    scoring_algorithm_digest: str
    scoring_runtime_digest: str
    metric_engine_digest: str
    verification_resolver_digest: str
    registered_at: str
    mode: Literal["prospective", "sealed_historical"] = "prospective"
    sealed_historical_dataset_digest: str | None = None
    candidate_training_started_at: str | None = None
    contract: str = "neural-prior-holdout-plan-v32"
    plan_digest: str = field(init=False)

    def __post_init__(self) -> None:
        if self.contract != "neural-prior-holdout-plan-v32":
            raise ValueError("unsupported neural-prior holdout plan")
        if not self.plan_id or self.plan_id.strip() != self.plan_id:
            raise ValueError("holdout plan ID must be canonical")
        _require_digest("parent_prior_digest", self.parent_prior_digest)
        if len(self.candidate_family_digests) != 1:
            raise ValueError("current scoring contract requires exactly one candidate")
        for digest in self.candidate_family_digests:
            _require_digest("candidate family digest", digest)
        if self.parent_prior_digest in self.candidate_family_digests:
            raise ValueError("candidate family cannot contain the parent prior")
        case_ids = tuple(item.case_id for item in self.cases)
        if not case_ids or len(set(case_ids)) != len(case_ids):
            raise ValueError("holdout plan cases must be nonempty and unique")
        if set(self.promotion_experiment_family.meteorological_sampling_unit_digests) != {
            item.meteorological_sampling_unit_digest for item in self.cases
        }:
            raise ValueError("experiment family sampling units disagree with holdout cases")
        input_plans = tuple(item.input_plan_digest for item in self.cases)
        if len(set(input_plans)) != len(input_plans):
            raise ValueError("holdout cases must use distinct input plans")
        retained_plans = {item.plan_digest: item for item in self.input_plans}
        if set(retained_plans) != set(input_plans):
            raise ValueError("holdout input-plan payloads are incomplete")
        raw_slots = {
            item.slot_digest: item for item in self.raw_observation_slot_plans
        }
        if (
            not raw_slots
            or len(raw_slots) != len(self.raw_observation_slot_plans)
            or set(raw_slots)
            != set(self.promotion_experiment_family.raw_observation_slot_digests)
        ):
            raise ValueError("holdout raw observation slots are incomplete")
        sampling_units = {
            item.sampling_unit_digest: item
            for item in self.meteorological_sampling_units
        }
        if (
            len(sampling_units) != len(self.meteorological_sampling_units)
            or set(sampling_units)
            != set(
                self.promotion_experiment_family.meteorological_sampling_unit_digests
            )
        ):
            raise ValueError("holdout meteorological sampling units are incomplete")
        for case in self.cases:
            input_plan = retained_plans[case.input_plan_digest]
            sampling_unit = sampling_units.get(
                case.meteorological_sampling_unit_digest
            )
            if sampling_unit is None:
                raise ValueError(
                    "holdout sampling unit is not derived from raw weather identity"
                )
            case_raw_slots = tuple(
                raw_slots[digest]
                for digest in sampling_unit.raw_observation_slot_digests
            )
            # A mosaic may contribute one raw volume per radar for the same
            # input instant.  Compare the covered instants, not a single-site
            # one-volume-per-time multiset.
            if {
                item.acquisition_valid_time for item in case_raw_slots
            } != set(input_plan.valid_times):
                raise ValueError(
                    "holdout raw observation slot times disagree with its input plan"
                )
        if (
            type(self.raw_ingestor_trust_store) is not RawIngestorTrustStore
            or type(self.training_target_source_trust_store)
            is not TrainingTargetSourceTrustStore
            or not self.analysis_processor_id
            or self.analysis_processor_id.strip() != self.analysis_processor_id
            or not self.training_target_source_authority_id
            or self.training_target_source_authority_id.strip()
            != self.training_target_source_authority_id
            or self.training_target_source_authority_id
            == self.analysis_processor_id
        ):
            raise ValueError("holdout data-provenance authorities are invalid")
        try:
            processor_key = bytes.fromhex(self.analysis_processor_public_key_hex)
            Ed25519PublicKey.from_public_bytes(processor_key)
            target_source_key = bytes.fromhex(
                self.training_target_source_authority_public_key_hex
            )
            Ed25519PublicKey.from_public_bytes(target_source_key)
        except (ValueError, TypeError) as error:
            raise ValueError("analysis processor authority key is invalid") from error
        if (
            len(processor_key) != 32
            or len(target_source_key) != 32
            or target_source_key == processor_key
            or not any(
                item[0] == self.training_target_source_authority_id
                and item[1]
                == self.training_target_source_authority_public_key_hex
                for item in self.training_target_source_trust_store.authorities
            )
        ):
            raise ValueError("analysis processor authority key is invalid")
        for classifier_manifest in self.regime_classifier_manifests:
            classifier_derivation = _training_dataset_derivation_from_json(
                classifier_manifest.training_dataset_derivation_artifact_json,
                expected_digest=(
                    classifier_manifest.training_dataset_derivation_artifact_digest
                ),
            )
            _validate_training_derivation_processor_authority(
                classifier_derivation,
                processor_id=self.analysis_processor_id,
                processor_public_key_hex=self.analysis_processor_public_key_hex,
                target_source_authority_id=(
                    self.training_target_source_authority_id
                ),
                target_source_authority_public_key_hex=(
                    self.training_target_source_authority_public_key_hex
                ),
                target_source_trust_store=(
                    self.training_target_source_trust_store
                ),
            )
        target_plans = tuple(
            item.uncertainty_target_plan_digest for item in self.cases
        )
        retained_targets = {
            item.plan_digest: item for item in self.uncertainty_target_plans
        }
        if set(retained_targets) != set(target_plans):
            raise ValueError("holdout uncertainty-target plans are incomplete")
        state_target_plans = tuple(
            item.state_calibration_target_plan_digest for item in self.cases
        )
        retained_state_targets = {
            item.plan_digest: item for item in self.state_calibration_target_plans
        }
        if set(retained_state_targets) != set(state_target_plans):
            raise ValueError("holdout state-calibration plans are incomplete")
        retained_observation_error_plans = {
            item.plan_digest: item
            for item in self.verification_observation_error_plans
        }
        referenced_observation_error_plans = {
            item.verification_observation_error_plan_digest
            for item in (
                *self.uncertainty_target_plans,
                *self.state_calibration_target_plans,
            )
        }
        if any(
            item.contract != "verification-observation-error-plan-v12"
            for item in self.verification_observation_error_plans
        ):
            raise ValueError(
                "current holdout requires observation-error plan v12"
            )
        if (
            len(retained_observation_error_plans)
            != len(self.verification_observation_error_plans)
            or set(retained_observation_error_plans)
            != referenced_observation_error_plans
            or any(
                retained_observation_error_plans[
                    item.verification_observation_error_plan_digest
                ].attenuation_qc_digest
                != item.qc_pipeline_digest
                or retained_observation_error_plans[
                    item.verification_observation_error_plan_digest
                ].censoring_rule_digest
                != item.censor_policy_digest
                for item in (
                    *self.uncertainty_target_plans,
                    *self.state_calibration_target_plans,
                )
            )
        ):
            raise ValueError(
                "holdout verification observation-error plans are incomplete"
            )
        retained_range_contracts = {
            item.contract_digest: item for item in self.range_band_contracts
        }
        expected_range_contracts = {
            item.range_band_contract_digest for item in self.cases
        }
        if (
            len(retained_range_contracts) != len(self.range_band_contracts)
            or set(retained_range_contracts) != expected_range_contracts
        ):
            raise ValueError("holdout range-band contracts are incomplete")
        for case in self.cases:
            range_contract = retained_range_contracts[
                case.range_band_contract_digest
            ]
            if (
                range_contract.case_id != case.case_id
                or (
                    range_contract.dynamic_source_resolution
                    and bool(case.reference_active_range_regimes)
                )
                or (
                    not range_contract.dynamic_source_resolution
                    and range_contract.reference_active_range_regimes
                    != case.reference_active_range_regimes
                )
                or range_contract.grid_contract_digest
                != next(
                    item.grid_contract_digest
                    for item in self.input_plans
                    if item.plan_digest == case.input_plan_digest
                )
            ):
                raise ValueError("holdout range-band contract disagrees with its case")
        retained_geometries = {
            item.contract_digest: item for item in self.range_geometry_contracts
        }
        expected_geometries = {
            item.range_geometry_contract_digest
            for item in self.range_band_contracts
        }
        if (
            not retained_geometries
            or len(retained_geometries) != len(self.range_geometry_contracts)
            or set(retained_geometries) != expected_geometries
            or any(
                retained_geometries[item.range_geometry_contract_digest].grid_contract_digest
                != item.grid_contract_digest
                or retained_geometries[item.range_geometry_contract_digest].range_regime_labels
                != item.range_regime_labels
                for item in self.range_band_contracts
            )
        ):
            raise ValueError("holdout range geometry contracts are incomplete")
        if any(
            item.dynamic_source_resolution
            != (
                type(retained_geometries[item.range_geometry_contract_digest])
                is MosaicRangeGeometryContract
            )
            for item in self.range_band_contracts
        ):
            raise ValueError(
                "range-band source resolution disagrees with its geometry"
            )
        for case in self.cases:
            range_contract = retained_range_contracts[
                case.range_band_contract_digest
            ]
            geometry = retained_geometries[
                range_contract.range_geometry_contract_digest
            ]
            if type(geometry) is not RangeGeometryContract:
                continue
            sampling_unit = sampling_units[
                case.meteorological_sampling_unit_digest
            ]
            case_raw_slots = tuple(
                raw_slots[digest]
                for digest in sampling_unit.raw_observation_slot_digests
            )
            if {
                item.radar_site_digest for item in case_raw_slots
            } != {geometry.radar_site_digest}:
                raise ValueError(
                    "single-site raw observations disagree with range geometry"
                )
        issuance_plans = {
            item.plan_digest: item
            for item in self.operational_issuance_domain_plans
        }
        if (
            len(issuance_plans) != len(self.operational_issuance_domain_plans)
            or set(issuance_plans)
            != {
                item.operational_issuance_domain_plan_digest
                for item in self.cases
            }
            or any(
                issuance_plans[
                    item.operational_issuance_domain_plan_digest
                ].case_id
                != item.case_id
                for item in self.cases
            )
        ):
            raise ValueError("operational issuance-domain plans are incomplete")
        reference_plans = {
            item.plan_digest: item for item in self.regime_reference_plans
        }
        if (
            len(reference_plans) != len(self.regime_reference_plans)
            or set(reference_plans)
            != {item.regime_reference_plan_digest for item in self.cases}
            or any(
                reference_plans[item.regime_reference_plan_digest].case_id
                != item.case_id
                for item in self.cases
            )
        ):
            raise ValueError("holdout regime-reference plans are incomplete")
        if any(
            _canonical_datetime(
                reference_plans[
                    item.regime_reference_plan_digest
                ].labeling_valid_time
            )
            <= _canonical_datetime(item.issue_time)
            for item in self.cases
        ):
            raise ValueError("regime reference must be produced after issue")
        _require_digest(
            "reference label contract", self.reference_label_contract_digest
        )
        _require_digest(
            "promotion decision rule", self.promotion_decision_rule_digest
        )
        for name in (
            "scoring_algorithm_digest",
            "scoring_runtime_digest",
            "metric_engine_digest",
            "verification_resolver_digest",
        ):
            _require_digest(name, getattr(self, name))
        if self.metric_engine_digest != scoring_metric_engine_identity_digest():
            raise ValueError(
                "holdout metric engine is not the installed implementation"
            )
        if set(self.physical_event_catalog_plan.holdout_case_ids) != set(case_ids):
            raise ValueError("physical event-catalog plan cases are incomplete")
        if any(
            item.labeler_id != self.physical_event_catalog_plan.adjudicator_id
            or item.labeler_public_key_hex
            != self.physical_event_catalog_plan.adjudicator_public_key_hex
            or item.adjudication_policy_digest
            != self.physical_event_catalog_plan.adjudication_policy_digest
            for item in self.regime_reference_plans
        ):
            raise ValueError("physical event-catalog plan authority is untrusted")
        if any(
            item.source_contract_digest != self.reference_label_contract_digest
            for item in self.regime_reference_plans
        ):
            raise ValueError("regime-reference source contract is not approved")
        if (
            not self.regime_classifier_manifests
            or len(
                {item.manifest_digest for item in self.regime_classifier_manifests}
            )
            != len(self.regime_classifier_manifests)
            or len(
                {item.classifier_digest for item in self.regime_classifier_manifests}
            )
            != len(self.regime_classifier_manifests)
            or any(
                item.reference_label_contract_digest
                != self.reference_label_contract_digest
                for item in self.regime_classifier_manifests
            )
        ):
            raise ValueError("holdout classifier family is invalid")
        holdout_case_ids = {item.case_id for item in self.cases}
        holdout_storm_ids = {item.storm_id for item in self.cases}
        holdout_days = {item.day for item in self.cases}
        holdout_issues = tuple(item.issue_time for item in self.cases)
        for classifier in self.regime_classifier_manifests:
            training_registry_receipt = _training_raw_registry_receipt_from_json(
                classifier.training_raw_registry_receipt_payload_json,
                expected_digest=classifier.training_raw_registry_receipt_digest,
            )
            reservation = self.promotion_experiment_family.global_sampling_reservation
            if (
                set(classifier.training_case_ids) & holdout_case_ids
                or set(classifier.training_storm_ids) & holdout_storm_ids
                or set(classifier.training_days) & holdout_days
                or any(
                    _canonical_datetime(start)
                    <= _canonical_datetime(issue)
                    <= _canonical_datetime(end)
                    for start, end in classifier.training_time_windows
                    for issue in holdout_issues
                )
                or training_registry_receipt.registry_id != reservation.registry_id
                or training_registry_receipt.authority_id != reservation.authority_id
                or training_registry_receipt.authority_public_key_hex
                != reservation.authority_public_key_hex
                or training_registry_receipt.registry_sequence_number + 1
                != reservation.registry_sequence_number
                or training_registry_receipt.committed_registry_root_digest
                != reservation.previous_registry_root_digest
                or _canonical_datetime(training_registry_receipt.committed_at)
                >= _canonical_datetime(reservation.reserved_at)
            ):
                raise ValueError("classifier training overlaps the holdout")
        matching_trials = tuple(
            item
            for item in self.promotion_experiment_family.trials
            if item.candidate_prior_digest == self.candidate_family_digests[0]
            and item.promotion_decision_rule_digest
            == self.promotion_decision_rule_digest
            and item.classifier_manifest_digests
            == tuple(
                manifest.manifest_digest
                for manifest in self.regime_classifier_manifests
            )
        )
        if (
            self.promotion_experiment_family.holdout_cohort_digest
            != _holdout_dataset_digest(self.cases)
            or self.promotion_experiment_family.parent_prior_digest
            != self.parent_prior_digest
            or len(matching_trials) != 1
        ):
            raise ValueError("holdout plan disagrees with its experiment family")
        registered = _canonical_time(self.registered_at)
        if _canonical_datetime(
            self.promotion_experiment_family.global_sampling_reservation.reserved_at
        ) > _canonical_datetime(registered):
            raise ValueError("global sampling reservation must precede plan registration")
        if self.mode == "prospective":
            if self.sealed_historical_dataset_digest is not None or (
                self.candidate_training_started_at is not None
            ):
                raise ValueError("prospective holdout cannot use a sealed dataset")
            if any(
                _canonical_datetime(registered)
                >= _canonical_datetime(slot.acquisition_valid_time)
                for slot in self.raw_observation_slot_plans
            ):
                raise ValueError(
                    "prospective raw observation slots must follow plan registration"
                )
            if any(
                _canonical_datetime(registered)
                >= _canonical_datetime(item.issue_time)
                for item in self.cases
            ):
                raise ValueError("holdout plan must precede every issue time")
            if any(
                item.regime != "pending" or item.storm_id != "pending"
                for item in self.cases
            ):
                raise ValueError(
                    "prospective holdout cannot preregister weather truth or storm identity"
                )
        elif self.mode == "sealed_historical":
            if self.sealed_historical_dataset_digest is None or (
                self.candidate_training_started_at is None
            ):
                raise ValueError("historical holdout requires a sealed dataset")
            _require_digest(
                "sealed_historical_dataset_digest",
                self.sealed_historical_dataset_digest,
            )
            started = _canonical_time(self.candidate_training_started_at)
            if _canonical_datetime(registered) >= _canonical_datetime(started):
                raise ValueError("historical holdout must be sealed before training")
            object.__setattr__(self, "candidate_training_started_at", started)
        else:
            raise ValueError("unsupported holdout plan mode")
        object.__setattr__(self, "registered_at", registered)
        object.__setattr__(self, "plan_digest", json_digest(_holdout_plan_payload(self)))

    def case(self, case_id: str) -> NeuralPriorHoldoutPlanCase:
        matches = tuple(item for item in self.cases if item.case_id == case_id)
        if len(matches) != 1:
            raise ValueError("case is not in the holdout plan")
        return matches[0]

    @property
    def holdout_dataset_digest(self) -> str:
        return _holdout_dataset_digest(self.cases)

    @property
    def scoring_execution_contract_digest(self) -> str:
        return json_digest(
            {
                "contract": "neural-prior-scoring-execution-contract-v1",
                "holdout_plan_digest": self.plan_digest,
                "parent_prior_digest": self.parent_prior_digest,
                "candidate_family_digests": sorted(
                    self.candidate_family_digests
                ),
                "metric_contract_digests": sorted(
                    {item.metric_contract_digest for item in self.cases}
                ),
                "verification_plan_digests": sorted(
                    {item.verification_plan_digest for item in self.cases}
                ),
                "scoring_algorithm_digest": self.scoring_algorithm_digest,
                "scoring_runtime_digest": self.scoring_runtime_digest,
                "metric_engine_digest": self.metric_engine_digest,
                "verification_resolver_digest": (
                    self.verification_resolver_digest
                ),
                "promotion_decision_rule_digest": (
                    self.promotion_decision_rule_digest
                ),
            }
        )


@dataclass(frozen=True)
class NeuralPriorHoldoutPlanPolicy:
    """Root-approved limits for pre-registering holdout plans."""

    approved_plan_digests: tuple[str, ...]
    approved_metric_contract_digests: tuple[str, ...]
    maximum_candidate_family_size: int
    sampling_registry_id: str
    sampling_registry_authority_id: str
    sampling_registry_authority_public_key_hex: str
    approved_sampling_registry_root_digests: tuple[str, ...]
    raw_ingestor_trust_store_digest: str
    training_target_source_trust_store_digest: str
    analysis_processor_id: str
    analysis_processor_public_key_hex: str
    training_target_source_authority_id: str
    training_target_source_authority_public_key_hex: str
    contract: str = "neural-prior-holdout-plan-policy-v7"

    def __post_init__(self) -> None:
        if self.contract != "neural-prior-holdout-plan-policy-v7":
            raise ValueError("unsupported holdout plan policy")
        if not self.approved_plan_digests or not self.approved_metric_contract_digests:
            raise ValueError("holdout policy approvals must be nonempty")
        for digest in self.approved_plan_digests + self.approved_metric_contract_digests:
            _require_digest("holdout policy digest", digest)
        if (
            type(self.maximum_candidate_family_size) is not int
            or self.maximum_candidate_family_size != 1
        ):
            raise ValueError("current scoring contract requires family size one")
        if (
            not self.sampling_registry_id
            or self.sampling_registry_id.strip() != self.sampling_registry_id
            or not self.approved_sampling_registry_root_digests
            or not self.analysis_processor_id
            or self.analysis_processor_id.strip() != self.analysis_processor_id
            or not self.training_target_source_authority_id
            or self.training_target_source_authority_id.strip()
            != self.training_target_source_authority_id
            or self.training_target_source_authority_id
            == self.analysis_processor_id
        ):
            raise ValueError("holdout provenance policy identity is invalid")
        for digest in self.approved_sampling_registry_root_digests:
            _require_digest("approved sampling registry root", digest)
        _require_digest(
            "raw ingestor trust store",
            self.raw_ingestor_trust_store_digest,
        )
        _require_digest(
            "training target-source trust store",
            self.training_target_source_trust_store_digest,
        )
        if (
            not self.sampling_registry_authority_id
            or self.sampling_registry_authority_id.strip()
            != self.sampling_registry_authority_id
        ):
            raise ValueError("sampling registry authority ID is invalid")
        try:
            Ed25519PublicKey.from_public_bytes(
                bytes.fromhex(self.sampling_registry_authority_public_key_hex)
            )
            Ed25519PublicKey.from_public_bytes(
                bytes.fromhex(self.analysis_processor_public_key_hex)
            )
            target_source_key = bytes.fromhex(
                self.training_target_source_authority_public_key_hex
            )
            Ed25519PublicKey.from_public_bytes(target_source_key)
            if target_source_key == bytes.fromhex(
                self.analysis_processor_public_key_hex
            ):
                raise ValueError
        except (ValueError, TypeError) as error:
            raise ValueError("sampling registry authority key is invalid") from error

    @property
    def digest(self) -> str:
        return json_digest(
            {
                "contract": self.contract,
                "approved_plan_digests": sorted(self.approved_plan_digests),
                "approved_metric_contract_digests": sorted(
                    self.approved_metric_contract_digests
                ),
                "maximum_candidate_family_size": (
                    self.maximum_candidate_family_size
                ),
                "sampling_registry_id": self.sampling_registry_id,
                "sampling_registry_authority_id": (
                    self.sampling_registry_authority_id
                ),
                "sampling_registry_authority_public_key_hex": (
                    self.sampling_registry_authority_public_key_hex
                ),
                "approved_sampling_registry_root_digests": sorted(
                    self.approved_sampling_registry_root_digests
                ),
                "raw_ingestor_trust_store_digest": (
                    self.raw_ingestor_trust_store_digest
                ),
                "training_target_source_trust_store_digest": (
                    self.training_target_source_trust_store_digest
                ),
                "analysis_processor_id": self.analysis_processor_id,
                "analysis_processor_public_key_hex": (
                    self.analysis_processor_public_key_hex
                ),
                "training_target_source_authority_id": (
                    self.training_target_source_authority_id
                ),
                "training_target_source_authority_public_key_hex": (
                    self.training_target_source_authority_public_key_hex
                ),
            }
        )


@dataclass(frozen=True)
class VerificationTargetIdentityArtifact:
    """Typed identity of the exact target tensors consumed by scoring.

    This is deliberately produced from the resolved target rather than from
    caller-supplied manifest strings.  Training/holdout independence and the
    metric engine therefore name the same physical source, instant and bytes.
    """

    source_identity_digest: str
    target_valid_time: str
    target_plan_digest: str
    target_tensor_digest: str
    target_valid_mask_digest: str
    target_quality_digest: str
    qc_pipeline_digest: str
    mask_policy_digest: str
    censor_policy_digest: str
    verification_bundle_digest: str
    observation_error_contract_digest: str
    contract: str = "verification-target-identity-artifact-v2"
    artifact_digest: str = field(init=False)

    def __post_init__(self) -> None:
        if self.contract != "verification-target-identity-artifact-v2":
            raise ValueError("unsupported verification target identity")
        for name in (
            "source_identity_digest",
            "target_plan_digest",
            "target_tensor_digest",
            "target_valid_mask_digest",
            "target_quality_digest",
            "qc_pipeline_digest",
            "mask_policy_digest",
            "censor_policy_digest",
            "verification_bundle_digest",
            "observation_error_contract_digest",
        ):
            _require_digest(name, getattr(self, name))
        object.__setattr__(
            self,
            "target_valid_time",
            _canonical_time(self.target_valid_time),
        )
        object.__setattr__(self, "artifact_digest", json_digest(self.payload))

    @classmethod
    def from_scoring_target(
        cls,
        *,
        plan: PriorUncertaintyTargetPlan,
        target: PriorUncertaintyTarget,
    ) -> VerificationTargetIdentityArtifact:
        if type(plan) is not PriorUncertaintyTargetPlan or (
            type(target) is not PriorUncertaintyTarget
        ):
            raise TypeError("current uncertainty target plan and target are required")
        if (
            target.target_plan_digest != plan.plan_digest
            or target.source_digest != target.source_verification_bundle_digest
            or target.support_event_digest != plan.support_event_digest
            or target.observation_error_plan_digest
            != plan.verification_observation_error_plan_digest
            or not target.observation_error_contract_digest
        ):
            raise ValueError("verification target disagrees with its plan")
        target_dbz = target._target_dbz.detach().clone()
        valid_mask = target._valid_mask.detach().clone()
        quality = target._quality_weight.detach().clone()
        if (
            valid_mask.dtype is not torch.bool
            or valid_mask.shape != target_dbz.shape
            or quality.shape != target_dbz.shape
            or not quality.is_floating_point()
            or not bool(torch.all(torch.isfinite(quality)))
            or not bool(torch.all((quality >= 0.0) & (quality <= 1.0)))
            or not bool(torch.all(quality.masked_select(~valid_mask) == 0.0))
            or float(quality.masked_select(valid_mask).sum()) <= 0.0
        ):
            raise ValueError("verification target mask/quality is invalid")
        return cls(
            source_identity_digest=plan.source_identity_digest,
            target_valid_time=plan.target_valid_time,
            target_plan_digest=plan.plan_digest,
            target_tensor_digest=tensor_digest(target_dbz),
            target_valid_mask_digest=tensor_digest(valid_mask),
            target_quality_digest=tensor_digest(quality),
            qc_pipeline_digest=plan.qc_pipeline_digest,
            mask_policy_digest=plan.mask_policy_digest,
            censor_policy_digest=plan.censor_policy_digest,
            verification_bundle_digest=target.source_verification_bundle_digest,
            observation_error_contract_digest=(
                target.observation_error_contract_digest
            ),
        )

    @property
    def payload(self) -> dict[str, object]:
        return {
            key: value
            for key, value in self.__dict__.items()
            if key != "artifact_digest"
        }

    @property
    def json(self) -> str:
        return json.dumps(
            self.payload | {"artifact_digest": self.artifact_digest},
            sort_keys=True,
            separators=(",", ":"),
        )


def _verification_target_identity_from_json(
    text: str,
    *,
    expected_digest: str,
) -> VerificationTargetIdentityArtifact:
    try:
        payload = json.loads(text)
    except json.JSONDecodeError as error:
        raise ValueError("verification target identity is invalid") from error
    if not isinstance(payload, dict):
        raise ValueError("verification target identity is invalid")
    values = dict(payload)
    stored_digest = values.pop("artifact_digest", None)
    try:
        artifact = VerificationTargetIdentityArtifact(**cast(Any, values))
    except (TypeError, ValueError) as error:
        raise ValueError("verification target identity is invalid") from error
    if (
        artifact.artifact_digest != expected_digest
        or stored_digest != artifact.artifact_digest
        or text != artifact.json
    ):
        raise ValueError("verification target identity digest mismatch")
    return artifact


@dataclass(frozen=True)
class NeuralPriorHoldoutCase:
    """One completed paired forecast committed by a holdout plan."""

    case_id: str
    planned_storm_id: str
    storm_id: str
    physical_event_digest: str
    meteorological_sampling_unit_digest: str
    day: str
    radar_id: str
    planned_regime: str
    regime: str
    range_regime: str
    reference_active_range_regimes: tuple[str, ...]
    dynamic_range_source_resolution: bool
    range_band_contract_digest: str
    regime_reference_plan_digest: str
    regime_reference_evidence_digest: str
    operational_issuance_domain_plan_digest: str
    operational_issuance_domain_artifact_digest: str
    input_plan_digest: str
    input_plan_resolution_digest: str
    input_bundle_digest: str
    full_analysis_input_digest: str
    analysis_input_derivation_artifact_digest: str
    resolved_raw_volume_identity_digests: tuple[str, ...]
    global_raw_resolution_receipt_digest: str
    fixed_input_context_digest: str
    observation_quality_weight_digest: str
    observation_std_dbz_digest: str
    verification_plan_digest: str
    verification_bundle_digest: str
    metric_contract_digest: str
    uncertainty_target_plan_digest: str
    uncertainty_target_digest: str
    verification_target_identity_artifact_json: str
    verification_target_identity_artifact_digest: str
    prior_probability_contract_digest: str
    state_calibration_target_plan_digest: str
    state_calibration_target_digest: str
    prior_state_contract_digest: str
    issue_time: str
    candidate_forecast_digest: str
    parent_forecast_digest: str
    candidate_prior_application_digest: str
    parent_prior_application_digest: str
    candidate_inference_evidence_digest: str
    parent_inference_evidence_digest: str

    def __post_init__(self) -> None:
        _validate_holdout_case_identity(self)
        for name in (
            "input_plan_digest",
            "input_plan_resolution_digest",
            "input_bundle_digest",
            "full_analysis_input_digest",
            "analysis_input_derivation_artifact_digest",
            "global_raw_resolution_receipt_digest",
            "fixed_input_context_digest",
            "observation_quality_weight_digest",
            "observation_std_dbz_digest",
            "verification_plan_digest",
            "verification_bundle_digest",
            "metric_contract_digest",
            "uncertainty_target_plan_digest",
            "uncertainty_target_digest",
            "verification_target_identity_artifact_digest",
            "prior_probability_contract_digest",
            "state_calibration_target_plan_digest",
            "state_calibration_target_digest",
            "prior_state_contract_digest",
            "range_band_contract_digest",
            "regime_reference_plan_digest",
            "regime_reference_evidence_digest",
            "operational_issuance_domain_plan_digest",
            "operational_issuance_domain_artifact_digest",
            "physical_event_digest",
            "meteorological_sampling_unit_digest",
            "candidate_forecast_digest",
            "parent_forecast_digest",
            "candidate_prior_application_digest",
            "parent_prior_application_digest",
            "candidate_inference_evidence_digest",
            "parent_inference_evidence_digest",
        ):
            _require_digest(name, getattr(self, name))
        if (
            not self.resolved_raw_volume_identity_digests
            or len(set(self.resolved_raw_volume_identity_digests))
            != len(self.resolved_raw_volume_identity_digests)
        ):
            raise ValueError("completed raw-volume identities are invalid")
        for digest in self.resolved_raw_volume_identity_digests:
            _require_digest("completed raw-volume identity", digest)
        identity = _verification_target_identity_from_json(
            self.verification_target_identity_artifact_json,
            expected_digest=self.verification_target_identity_artifact_digest,
        )
        if identity.target_plan_digest != self.uncertainty_target_plan_digest:
            raise ValueError("verification target identity disagrees with its plan")
        if (
            type(self.dynamic_range_source_resolution) is not bool
            or (
                not self.dynamic_range_source_resolution
                and not self.reference_active_range_regimes
            )
            or len(set(self.reference_active_range_regimes))
            != len(self.reference_active_range_regimes)
            or any(not value for value in self.reference_active_range_regimes)
        ):
            raise ValueError("completed reference range set is invalid")
        if (
            not self.planned_regime
            or self.planned_regime.strip() != self.planned_regime
            or not self.planned_storm_id
            or self.planned_storm_id.strip() != self.planned_storm_id
        ):
            raise ValueError("completed planned event identity is invalid")
        object.__setattr__(self, "issue_time", _canonical_time(self.issue_time))
        if self.candidate_forecast_digest == self.parent_forecast_digest:
            raise ValueError("candidate and parent holdout forecasts must differ")
        if self.candidate_prior_application_digest == (
            self.parent_prior_application_digest
        ):
            raise ValueError("candidate and parent prior applications must differ")

    def plan_case(self) -> NeuralPriorHoldoutPlanCase:
        return NeuralPriorHoldoutPlanCase(
            case_id=self.case_id,
            storm_id=self.planned_storm_id,
            day=self.day,
            radar_id=self.radar_id,
            regime=self.planned_regime,
            range_regime=self.range_regime,
            reference_active_range_regimes=(
                ()
                if self.dynamic_range_source_resolution
                else self.reference_active_range_regimes
            ),
            range_band_contract_digest=self.range_band_contract_digest,
            regime_reference_plan_digest=self.regime_reference_plan_digest,
            operational_issuance_domain_plan_digest=(
                self.operational_issuance_domain_plan_digest
            ),
            input_plan_digest=self.input_plan_digest,
            verification_plan_digest=self.verification_plan_digest,
            metric_contract_digest=self.metric_contract_digest,
            uncertainty_target_plan_digest=self.uncertainty_target_plan_digest,
            state_calibration_target_plan_digest=(
                self.state_calibration_target_plan_digest
            ),
            issue_time=self.issue_time,
            meteorological_sampling_unit_digest=(
                self.meteorological_sampling_unit_digest
            ),
        )

    @property
    def verification_target_identity(self) -> VerificationTargetIdentityArtifact:
        return _verification_target_identity_from_json(
            self.verification_target_identity_artifact_json,
            expected_digest=self.verification_target_identity_artifact_digest,
        )

    @property
    def completed_case_digest(self) -> str:
        """Digest every completed truth and lineage input used by scoring."""

        return json_digest(
            {
                "contract": "neural-prior-completed-holdout-case-v1",
                "case": asdict(self),
            }
        )


def _validate_classifier_holdout_independence(
    classifier: RegimeClassifierManifest,
    cases: tuple[NeuralPriorHoldoutCase, ...],
) -> None:
    """Reject renamed or re-manifested holdout inputs used in training."""

    holdout_bundle_digests = {item.input_bundle_digest for item in cases}
    holdout_full_digests = {item.full_analysis_input_digest for item in cases}
    if (
        set(classifier.training_input_bundle_digests) & holdout_bundle_digests
        or set(classifier.training_full_analysis_input_digests)
        & holdout_full_digests
    ):
        raise ValueError("classifier training inputs overlap the holdout")
    if set(classifier.training_physical_event_digests) & {
        item.physical_event_digest for item in cases
    }:
        raise ValueError("classifier training physical events overlap the holdout")
    classifier_derivation = _training_dataset_derivation_from_json(
        classifier.training_dataset_derivation_artifact_json,
        expected_digest=classifier.training_dataset_derivation_artifact_digest,
    )
    if {item.physical_event_digest for item in classifier_derivation.target_derivations} & {
        item.physical_event_digest for item in cases
    }:
        raise ValueError("classifier training targets overlap the holdout")
    holdout_targets = {
        (
            item.verification_target_identity.source_identity_digest,
            item.verification_target_identity.target_valid_time,
        )
        for item in cases
    }
    if {
        (
            item.target_source_identity_digest,
            _canonical_time(item.target_source_valid_time),
        )
        for item in classifier_derivation.target_derivations
    } & holdout_targets:
        raise ValueError("classifier training target source overlaps the holdout")
    holdout_raw_identities = {
        digest
        for item in cases
        for digest in item.resolved_raw_volume_identity_digests
    }
    if set(classifier.training_raw_volume_identity_digests) & holdout_raw_identities:
        raise ValueError("classifier training raw volumes overlap the holdout")
    if set(classifier.training_sampling_unit_digests) & {
        item.meteorological_sampling_unit_digest for item in cases
    }:
        raise ValueError("classifier training sampling units overlap the holdout")


@dataclass(frozen=True)
class LegacyNeuralPriorCandidateManifestAuditV2:
    """Digest-verified v2 manifest retained only for historical audit."""

    manifest_digest: str
    payload_json: str
    contract: str = "legacy-neural-prior-candidate-manifest-audit-v2"
    contains_full_input_identity: bool = field(init=False)
    audit_digest: str = field(init=False)

    def __post_init__(self) -> None:
        _require_digest("legacy candidate manifest digest", self.manifest_digest)
        try:
            payload = json.loads(self.payload_json)
        except json.JSONDecodeError as error:
            raise ValueError("invalid legacy candidate manifest payload") from error
        if (
            not isinstance(payload, dict)
            or payload.get("contract") != "neural-prior-candidate-manifest-v2"
            or payload.get("manifest_digest") != self.manifest_digest
        ):
            raise ValueError("invalid legacy candidate manifest")
        canonical = json.dumps(payload, sort_keys=True, separators=(",", ":"))
        if canonical != self.payload_json:
            raise ValueError("legacy candidate manifest is not canonical")
        original = dict(payload)
        original.pop("manifest_digest")
        if json_digest(original) != self.manifest_digest:
            raise ValueError("legacy candidate manifest digest mismatch")
        cases = payload.get("holdout_cases")
        if not isinstance(cases, list) or any(
            not isinstance(item, dict) for item in cases
        ):
            raise ValueError("legacy candidate manifest cases are invalid")
        required = {
            "full_analysis_input_digest",
            "fixed_input_context_digest",
            "observation_quality_weight_digest",
            "observation_std_dbz_digest",
        }
        object.__setattr__(
            self,
            "contains_full_input_identity",
            bool(cases) and all(required <= set(item) for item in cases),
        )
        object.__setattr__(
            self,
            "audit_digest",
            json_digest(
                {
                    "contract": self.contract,
                    "manifest_digest": self.manifest_digest,
                    "payload": payload,
                }
            ),
        )


