def _issue_operational_decision_activation_receipt(
    certificate: OperationalDeploymentDecisionCertificate,
    publication_receipt: OperationalDecisionPublicationReceipt,
    *,
    publication_payload_committed_at: str,
    activation_authorized_at: str,
    publication_guard_interval_seconds: float,
    committed_chain_root_digest: str,
    signer: DeploymentAuthoritySigner,
    authority_trust_store: _PromotionDeploymentAuthorityTrustStore,
) -> OperationalDecisionActivationReceipt:
    """Authorize the terminal transaction after its SQLite lock is held."""

    issued_at = _canonical_time(signer.signing_time())
    publication_commit = _canonical_time(publication_payload_committed_at)
    activation_authorized = _canonical_time(activation_authorized_at)
    if (
        not math.isfinite(publication_guard_interval_seconds)
        or publication_guard_interval_seconds < 0.05
    ):
        raise ValueError("operational publication guard is invalid")
    _require_digest("committed chain root", committed_chain_root_digest)
    _validate_signer(
        signer,
        trust_store=authority_trust_store,
        role="ledger_issuance",
        issued_at=issued_at,
    )
    if (
        certificate.ledger_instance_digest
        not in authority_trust_store.ledger_instance_digests.get(
            signer.authority_id,
            frozenset(),
        )
        or not _canonical_datetime(publication_commit)
        <= _canonical_datetime(activation_authorized)
        <= _canonical_datetime(issued_at)
        < _canonical_datetime(certificate.publication_time)
        or _canonical_datetime(publication_receipt.issued_at)
        > _canonical_datetime(issued_at)
        or _canonical_datetime(issued_at) > datetime.now(timezone.utc)
    ):
        raise ValueError("operational activation chronology is invalid")
    ledger_payload = json.loads(certificate.operational_ledger_receipt_payload_json)
    if not isinstance(ledger_payload, dict):
        raise ValueError("operational activation ledger lineage is invalid")
    ledger_receipt = _operational_decision_ledger_receipt_from_payload(
        ledger_payload
    )
    if (
        signer.authority_id != ledger_receipt.signer_id
        or signer.public_key_hex != ledger_receipt.signer_public_key_hex
        or committed_chain_root_digest
        != ledger_receipt.committed_chain_root_digest
    ):
        raise ValueError("operational activation requires the committing ledger")
    values: dict[str, object] = {
        "operational_decision_certificate_digest": certificate.certificate_digest,
        "publication_receipt_digest": publication_receipt.receipt_digest,
        "decision_payload_digest": certificate.decision_payload_digest,
        "ledger_instance_digest": certificate.ledger_instance_digest,
        "sequence_number": certificate.ledger_sequence_number,
        "committed_chain_root_digest": committed_chain_root_digest,
        "publication_payload_committed_at": publication_commit,
        "activation_authorized_at": activation_authorized,
        "publication_guard_interval_seconds": (
            publication_guard_interval_seconds
        ),
        "terminal_status": "published",
        "usable": True,
        "issued_at": issued_at,
        "signer_id": signer.authority_id,
        "signer_public_key_hex": signer.public_key_hex,
        "signer_trust_store_digest": authority_trust_store.content_digest,
        "contract": "operational-decision-activation-receipt-v3",
    }
    signature = signer.sign(
        json.dumps(values, sort_keys=True, separators=(",", ":")).encode()
    ).hex()
    result = object.__new__(OperationalDecisionActivationReceipt)
    for name, value in values.items():
        object.__setattr__(result, name, value)
    object.__setattr__(result, "signer_signature_hex", signature)
    object.__setattr__(result, "receipt_digest", json_digest(result.payload))
    return result


def _validate_operational_decision_activation_receipt(
    receipt: OperationalDecisionActivationReceipt,
    *,
    certificate: OperationalDeploymentDecisionCertificate,
    publication_receipt: OperationalDecisionPublicationReceipt,
    authority_trust_store: _PromotionDeploymentAuthorityTrustStore,
) -> None:
    for name in (
        "operational_decision_certificate_digest",
        "publication_receipt_digest",
        "decision_payload_digest",
        "ledger_instance_digest",
        "committed_chain_root_digest",
        "signer_trust_store_digest",
    ):
        _require_digest(name, getattr(receipt, name))
    ledger_payload = json.loads(certificate.operational_ledger_receipt_payload_json)
    if not isinstance(ledger_payload, dict):
        raise ValueError("operational activation ledger lineage is invalid")
    ledger_receipt = _operational_decision_ledger_receipt_from_payload(
        ledger_payload
    )
    if (
        type(receipt) is not OperationalDecisionActivationReceipt
        or receipt.contract != "operational-decision-activation-receipt-v3"
        or receipt.receipt_digest != json_digest(receipt.payload)
        or receipt.operational_decision_certificate_digest
        != certificate.certificate_digest
        or receipt.publication_receipt_digest != publication_receipt.receipt_digest
        or receipt.decision_payload_digest != certificate.decision_payload_digest
        or receipt.ledger_instance_digest != certificate.ledger_instance_digest
        or receipt.sequence_number != certificate.ledger_sequence_number
        or receipt.committed_chain_root_digest
        != ledger_receipt.committed_chain_root_digest
        or receipt.terminal_status != "published"
        or receipt.usable is not True
        or not math.isfinite(receipt.publication_guard_interval_seconds)
        or receipt.publication_guard_interval_seconds < 0.05
        or not _canonical_datetime(receipt.publication_payload_committed_at)
        <= _canonical_datetime(receipt.activation_authorized_at)
        <= _canonical_datetime(receipt.issued_at)
        < _canonical_datetime(certificate.publication_time)
        or _canonical_datetime(publication_receipt.issued_at)
        > _canonical_datetime(receipt.issued_at)
        or receipt.signer_id != ledger_receipt.signer_id
        or receipt.signer_public_key_hex != ledger_receipt.signer_public_key_hex
        or receipt.signer_trust_store_digest != authority_trust_store.content_digest
    ):
        raise ValueError("operational activation receipt is invalid")
    key = _trusted_authority_key(
        authority_trust_store,
        authority_id=receipt.signer_id,
        public_key_hex=receipt.signer_public_key_hex,
        role="ledger_issuance",
        issued_at=receipt.issued_at,
    )
    try:
        key.verify(
            bytes.fromhex(receipt.signer_signature_hex),
            json.dumps(
                receipt.unsigned_payload,
                sort_keys=True,
                separators=(",", ":"),
            ).encode(),
        )
    except (InvalidSignature, ValueError) as error:
        raise ValueError("operational activation signature is invalid") from error


@dataclass(frozen=True, init=False)
class OperationalDecisionCommitAuthorizationReceipt:
    """Ledger authorization made while the terminal SQLite writer lock is held.

    SQLite does not expose a cryptographically attestable physical fsync time.
    This receipt therefore proves a guarded terminal-commit authorization, not
    an after-COMMIT observation.
    """

    operational_decision_certificate_digest: str
    activation_receipt_digest: str
    ledger_instance_digest: str
    sequence_number: int
    activation_authorized_at: str
    terminal_commit_authorized_at: str
    publication_time: str
    signer_id: str
    signer_public_key_hex: str
    signer_trust_store_digest: str
    signer_signature_hex: str
    contract: str = "operational-decision-commit-authorization-receipt-v2"
    receipt_digest: str = field(init=False)

    def __init__(self) -> None:
        raise TypeError("operational commit authorizations are ledger-issued")

    @property
    def unsigned_payload(self) -> dict[str, object]:
        return {
            key: value
            for key, value in self.__dict__.items()
            if key not in {"signer_signature_hex", "receipt_digest"}
        }

    @property
    def payload(self) -> dict[str, object]:
        return {
            key: value
            for key, value in self.__dict__.items()
            if key != "receipt_digest"
        }


def _operational_decision_commit_authorization_receipt_from_payload(
    payload: dict[str, object],
) -> OperationalDecisionCommitAuthorizationReceipt:
    expected = {
        item.name
        for item in OperationalDecisionCommitAuthorizationReceipt.__dataclass_fields__.values()
        if item.name != "receipt_digest"
    }
    if set(payload) != expected:
        raise ValueError("operational commit authorization is incomplete")
    result = object.__new__(OperationalDecisionCommitAuthorizationReceipt)
    for name, value in payload.items():
        object.__setattr__(result, name, value)
    object.__setattr__(result, "receipt_digest", json_digest(result.payload))
    return result


def _issue_operational_decision_commit_authorization_receipt(
    certificate: OperationalDeploymentDecisionCertificate,
    activation_receipt: OperationalDecisionActivationReceipt,
    *,
    terminal_commit_authorized_at: str,
    signer: DeploymentAuthoritySigner,
    authority_trust_store: _PromotionDeploymentAuthorityTrustStore,
) -> OperationalDecisionCommitAuthorizationReceipt:
    authorized = _canonical_time(terminal_commit_authorized_at)
    _validate_signer(
        signer,
        trust_store=authority_trust_store,
        role="ledger_issuance",
        issued_at=authorized,
    )
    if (
        activation_receipt.operational_decision_certificate_digest
        != certificate.certificate_digest
        or not _canonical_datetime(activation_receipt.activation_authorized_at)
        <= _canonical_datetime(authorized)
        < _canonical_datetime(certificate.publication_time)
    ):
        raise ValueError("operational commit authorization chronology is invalid")
    values: dict[str, object] = {
        "operational_decision_certificate_digest": certificate.certificate_digest,
        "activation_receipt_digest": activation_receipt.receipt_digest,
        "ledger_instance_digest": certificate.ledger_instance_digest,
        "sequence_number": certificate.ledger_sequence_number,
        "activation_authorized_at": activation_receipt.activation_authorized_at,
        "terminal_commit_authorized_at": authorized,
        "publication_time": certificate.publication_time,
        "signer_id": signer.authority_id,
        "signer_public_key_hex": signer.public_key_hex,
        "signer_trust_store_digest": authority_trust_store.content_digest,
        "contract": "operational-decision-commit-authorization-receipt-v2",
    }
    result = object.__new__(OperationalDecisionCommitAuthorizationReceipt)
    for name, value in values.items():
        object.__setattr__(result, name, value)
    object.__setattr__(
        result,
        "signer_signature_hex",
        signer.sign(
            json.dumps(values, sort_keys=True, separators=(",", ":")).encode()
        ).hex(),
    )
    object.__setattr__(result, "receipt_digest", json_digest(result.payload))
    return result


def _validate_operational_decision_commit_authorization_receipt(
    receipt: OperationalDecisionCommitAuthorizationReceipt,
    *,
    certificate: OperationalDeploymentDecisionCertificate,
    activation_receipt: OperationalDecisionActivationReceipt,
    authority_trust_store: _PromotionDeploymentAuthorityTrustStore,
) -> None:
    for name in (
        "operational_decision_certificate_digest",
        "activation_receipt_digest",
        "ledger_instance_digest",
        "signer_trust_store_digest",
    ):
        _require_digest(name, getattr(receipt, name))
    if (
        type(receipt) is not OperationalDecisionCommitAuthorizationReceipt
        or receipt.contract
        != "operational-decision-commit-authorization-receipt-v2"
        or receipt.receipt_digest != json_digest(receipt.payload)
        or receipt.operational_decision_certificate_digest
        != certificate.certificate_digest
        or receipt.activation_receipt_digest != activation_receipt.receipt_digest
        or receipt.ledger_instance_digest != certificate.ledger_instance_digest
        or receipt.sequence_number != certificate.ledger_sequence_number
        or receipt.activation_authorized_at
        != activation_receipt.activation_authorized_at
        or receipt.publication_time != certificate.publication_time
        or not _canonical_datetime(receipt.activation_authorized_at)
        <= _canonical_datetime(receipt.terminal_commit_authorized_at)
        < _canonical_datetime(receipt.publication_time)
        or receipt.signer_id != activation_receipt.signer_id
        or receipt.signer_public_key_hex
        != activation_receipt.signer_public_key_hex
        or receipt.signer_trust_store_digest
        != authority_trust_store.content_digest
    ):
        raise ValueError("operational commit authorization is invalid")
    key = _trusted_authority_key(
        authority_trust_store,
        authority_id=receipt.signer_id,
        public_key_hex=receipt.signer_public_key_hex,
        role="ledger_issuance",
        issued_at=receipt.terminal_commit_authorized_at,
    )
    try:
        key.verify(
            bytes.fromhex(receipt.signer_signature_hex),
            json.dumps(
                receipt.unsigned_payload,
                sort_keys=True,
                separators=(",", ":"),
            ).encode(),
        )
    except (InvalidSignature, ValueError) as error:
        raise ValueError("operational commit authorization signature is invalid") from error


def _operational_decision_publication_receipt_from_payload(
    payload: dict[str, object],
) -> OperationalDecisionPublicationReceipt:
    expected = {
        item.name
        for item in OperationalDecisionPublicationReceipt.__dataclass_fields__.values()
        if item.name != "receipt_digest"
    }
    if set(payload) != expected:
        raise ValueError("operational publication receipt is incomplete")
    result = object.__new__(OperationalDecisionPublicationReceipt)
    for name, value in payload.items():
        object.__setattr__(result, name, value)
    object.__setattr__(result, "receipt_digest", json_digest(result.payload))
    return result


def _issue_operational_decision_publication_receipt(
    certificate: OperationalDeploymentDecisionCertificate,
    *,
    decision_row_committed_at: str,
    signer: DeploymentAuthoritySigner,
    authority_trust_store: _PromotionDeploymentAuthorityTrustStore,
) -> OperationalDecisionPublicationReceipt:
    issued_at = _canonical_time(signer.signing_time())
    _validate_signer(
        signer,
        trust_store=authority_trust_store,
        role="ledger_issuance",
        issued_at=issued_at,
    )
    committed = _canonical_time(decision_row_committed_at)
    if (
        certificate.ledger_instance_digest
        not in authority_trust_store.ledger_instance_digests.get(
            signer.authority_id,
            frozenset(),
        )
        or not _canonical_datetime(committed)
        <= _canonical_datetime(issued_at)
        <= _canonical_datetime(certificate.decision_deadline)
        or _canonical_datetime(issued_at) > datetime.now(timezone.utc)
    ):
        raise ValueError("operational decision publication missed its deadline")
    ledger_payload = json.loads(
        certificate.operational_ledger_receipt_payload_json
    )
    if not isinstance(ledger_payload, dict):
        raise ValueError("operational publication ledger lineage is invalid")
    ledger_receipt = _operational_decision_ledger_receipt_from_payload(
        ledger_payload
    )
    if (
        signer.authority_id != ledger_receipt.signer_id
        or signer.public_key_hex != ledger_receipt.signer_public_key_hex
    ):
        raise ValueError("operational publication requires the committing ledger")
    values: dict[str, object] = {
        "operational_decision_certificate_digest": certificate.certificate_digest,
        "ledger_instance_digest": certificate.ledger_instance_digest,
        "sequence_number": certificate.ledger_sequence_number,
        "decision_row_committed_at": committed,
        "issued_at": issued_at,
        "signer_id": signer.authority_id,
        "signer_public_key_hex": signer.public_key_hex,
        "signer_trust_store_digest": authority_trust_store.content_digest,
        "contract": "operational-decision-publication-receipt-v3",
    }
    signature = signer.sign(
        json.dumps(values, sort_keys=True, separators=(",", ":")).encode()
    ).hex()
    result = object.__new__(OperationalDecisionPublicationReceipt)
    for name, value in values.items():
        object.__setattr__(result, name, value)
    object.__setattr__(result, "signer_signature_hex", signature)
    object.__setattr__(result, "receipt_digest", json_digest(result.payload))
    return result


def _validate_operational_decision_publication_receipt(
    receipt: OperationalDecisionPublicationReceipt,
    *,
    certificate: OperationalDeploymentDecisionCertificate,
    authority_trust_store: _PromotionDeploymentAuthorityTrustStore,
) -> None:
    if (
        type(receipt) is not OperationalDecisionPublicationReceipt
        or receipt.contract != "operational-decision-publication-receipt-v3"
        or receipt.receipt_digest != json_digest(receipt.payload)
        or receipt.operational_decision_certificate_digest
        != certificate.certificate_digest
        or receipt.ledger_instance_digest != certificate.ledger_instance_digest
        or receipt.sequence_number != certificate.ledger_sequence_number
        or not _canonical_datetime(receipt.decision_row_committed_at)
        <= _canonical_datetime(receipt.issued_at)
        <= _canonical_datetime(certificate.decision_deadline)
    ):
        raise ValueError("operational publication receipt is invalid")
    ledger_payload = json.loads(
        certificate.operational_ledger_receipt_payload_json
    )
    if not isinstance(ledger_payload, dict):
        raise ValueError("operational publication ledger lineage is invalid")
    ledger_receipt = _operational_decision_ledger_receipt_from_payload(
        ledger_payload
    )
    if (
        receipt.signer_id != ledger_receipt.signer_id
        or receipt.signer_public_key_hex != ledger_receipt.signer_public_key_hex
        or receipt.signer_trust_store_digest != authority_trust_store.content_digest
    ):
        raise ValueError("operational publication ledger lineage disagrees")
    key = _trusted_authority_key(
        authority_trust_store,
        authority_id=receipt.signer_id,
        public_key_hex=receipt.signer_public_key_hex,
        role="ledger_issuance",
        issued_at=receipt.issued_at,
    )
    try:
        key.verify(
            bytes.fromhex(receipt.signer_signature_hex),
            json.dumps(
                receipt.unsigned_payload,
                sort_keys=True,
                separators=(",", ":"),
            ).encode(),
        )
    except (InvalidSignature, ValueError) as error:
        raise ValueError("operational publication signature is invalid") from error


def _operational_decision_commit_digests(
    decision_payload: dict[str, object],
    *,
    ledger_instance_digest: str,
    sequence_number: int,
    previous_operational_decision_digest: str,
    accepted_at: str,
) -> tuple[str, str]:
    """Derive the immutable entry and chain root committed by the ledger."""

    canonical_accepted_at = _canonical_time(accepted_at)
    entry = json_digest(
        {
            "contract": "operational-decision-commit-entry-v1",
            "ledger_instance_digest": ledger_instance_digest,
            "sequence_number": sequence_number,
            "previous_operational_decision_digest": (
                previous_operational_decision_digest
            ),
            "decision_payload_digest": json_digest(decision_payload),
            "promotion_deployment_certificate_digest": cast(
                dict[str, object],
                decision_payload["promotion_deployment_certificate"],
            )["certificate_digest"],
            "input_plan_digest": decision_payload.get("input_plan_digest"),
            "accepted_at": canonical_accepted_at,
        }
    )
    root = json_digest(
        {
            "contract": "operational-decision-committed-chain-root-v1",
            "ledger_instance_digest": ledger_instance_digest,
            "sequence_number": sequence_number,
            "previous_operational_decision_digest": (
                previous_operational_decision_digest
            ),
            "commit_entry_digest": entry,
        }
    )
    return entry, root


def _issue_operational_decision_ledger_receipt(
    decision_payload: dict[str, object],
    *,
    ledger_instance_digest: str,
    sequence_number: int,
    previous_operational_decision_digest: str,
    accepted_at: str,
    committed_at: str,
    commit_entry_digest: str,
    committed_chain_root_digest: str,
    signer: DeploymentAuthoritySigner,
    authority_trust_store: _PromotionDeploymentAuthorityTrustStore,
) -> OperationalDecisionLedgerReceipt:
    canonical_accepted_at = _canonical_time(accepted_at)
    canonical_committed_at = _canonical_time(committed_at)
    proof_issued_at = _canonical_time(signer.signing_time())
    _validate_signer(
        signer,
        trust_store=authority_trust_store,
        role="ledger_issuance",
        issued_at=proof_issued_at,
    )
    if ledger_instance_digest not in authority_trust_store.ledger_instance_digests.get(
        signer.authority_id, frozenset()
    ):
        raise ValueError("operational decision belongs to an unapproved ledger")
    deadline = _canonical_datetime(cast(str, decision_payload.get("decision_deadline")))
    publication = _canonical_datetime(cast(str, decision_payload.get("publication_time")))
    accepted = _canonical_datetime(canonical_accepted_at)
    committed = _canonical_datetime(canonical_committed_at)
    proof_time = _canonical_datetime(proof_issued_at)
    if (
        not accepted <= committed <= proof_time <= deadline < publication
        or proof_time > datetime.now(timezone.utc)
    ):
        raise ValueError("operational decision was not committed before its deadline")
    _require_digest("operational commit entry", commit_entry_digest)
    _require_digest("operational committed chain root", committed_chain_root_digest)
    values: dict[str, object] = {
        "ledger_instance_digest": ledger_instance_digest,
        "sequence_number": sequence_number,
        "previous_operational_decision_digest": previous_operational_decision_digest,
        "decision_payload_digest": json_digest(decision_payload),
        "promotion_deployment_certificate_digest": cast(
            dict[str, object], decision_payload["promotion_deployment_certificate"]
        )["certificate_digest"],
        "input_plan_digest": decision_payload.get("input_plan_digest"),
        "decision_deadline": decision_payload.get("decision_deadline"),
        "publication_time": decision_payload.get("publication_time"),
        "accepted_at": canonical_accepted_at,
        "committed_at": canonical_committed_at,
        "proof_issued_at": proof_issued_at,
        "commit_entry_digest": commit_entry_digest,
        "committed_chain_root_digest": committed_chain_root_digest,
        "signer_id": signer.authority_id,
        "signer_public_key_hex": signer.public_key_hex,
        "signer_trust_store_digest": authority_trust_store.content_digest,
        "contract": "operational-decision-ledger-receipt-v2",
    }
    signature = signer.sign(
        json.dumps(values, sort_keys=True, separators=(",", ":")).encode()
    ).hex()
    result = object.__new__(OperationalDecisionLedgerReceipt)
    for name, value in values.items():
        object.__setattr__(result, name, value)
    object.__setattr__(result, "signer_signature_hex", signature)
    object.__setattr__(result, "receipt_digest", json_digest(result.payload))
    _validate_operational_decision_ledger_receipt(
        result,
        decision_payload=decision_payload,
        authority_trust_store=authority_trust_store,
    )
    return result


def _operational_decision_ledger_receipt_from_payload(
    payload: dict[str, object],
) -> OperationalDecisionLedgerReceipt:
    expected = {
        item.name
        for item in OperationalDecisionLedgerReceipt.__dataclass_fields__.values()
        if item.name != "receipt_digest"
    }
    if set(payload) != expected:
        raise ValueError("operational decision ledger receipt is incomplete")
    result = object.__new__(OperationalDecisionLedgerReceipt)
    for name, value in payload.items():
        object.__setattr__(result, name, value)
    object.__setattr__(result, "receipt_digest", json_digest(result.payload))
    return result


def _validate_operational_decision_ledger_receipt(
    receipt: OperationalDecisionLedgerReceipt,
    *,
    decision_payload: dict[str, object],
    authority_trust_store: _PromotionDeploymentAuthorityTrustStore,
) -> None:
    for name in (
        "ledger_instance_digest",
        "previous_operational_decision_digest",
        "decision_payload_digest",
        "promotion_deployment_certificate_digest",
        "input_plan_digest",
        "signer_trust_store_digest",
        "commit_entry_digest",
        "committed_chain_root_digest",
    ):
        _require_digest(name, getattr(receipt, name))
    if (
        type(receipt) is not OperationalDecisionLedgerReceipt
        or receipt.contract != "operational-decision-ledger-receipt-v2"
        or receipt.receipt_digest != json_digest(receipt.payload)
        or type(receipt.sequence_number) is not int
        or receipt.sequence_number <= 0
        or receipt.accepted_at != _canonical_time(receipt.accepted_at)
        or receipt.committed_at != _canonical_time(receipt.committed_at)
        or receipt.proof_issued_at != _canonical_time(receipt.proof_issued_at)
        or receipt.decision_payload_digest != json_digest(decision_payload)
        or receipt.promotion_deployment_certificate_digest
        != cast(
            dict[str, object], decision_payload["promotion_deployment_certificate"]
        ).get("certificate_digest")
        or receipt.input_plan_digest != decision_payload.get("input_plan_digest")
        or receipt.decision_deadline != decision_payload.get("decision_deadline")
        or receipt.publication_time != decision_payload.get("publication_time")
        or (
            receipt.sequence_number == 1
            and receipt.previous_operational_decision_digest
            != OPERATIONAL_DECISION_LEDGER_GENESIS_DIGEST
        )
        or (receipt.commit_entry_digest, receipt.committed_chain_root_digest)
        != _operational_decision_commit_digests(
            decision_payload,
            ledger_instance_digest=receipt.ledger_instance_digest,
            sequence_number=receipt.sequence_number,
            previous_operational_decision_digest=(
                receipt.previous_operational_decision_digest
            ),
            accepted_at=receipt.accepted_at,
        )
        or not _canonical_datetime(receipt.accepted_at)
        <= _canonical_datetime(receipt.committed_at)
        <= _canonical_datetime(receipt.proof_issued_at)
        <= _canonical_datetime(receipt.decision_deadline)
        < _canonical_datetime(receipt.publication_time)
        or _canonical_datetime(receipt.proof_issued_at) > datetime.now(timezone.utc)
    ):
        raise ValueError("operational decision ledger receipt is invalid")
    key = _trusted_authority_key(
        authority_trust_store,
        authority_id=receipt.signer_id,
        public_key_hex=receipt.signer_public_key_hex,
        role="ledger_issuance",
        issued_at=receipt.proof_issued_at,
    )
    if receipt.ledger_instance_digest not in authority_trust_store.ledger_instance_digests.get(
        receipt.signer_id, frozenset()
    ):
        raise ValueError("operational decision ledger is not root-approved")
    try:
        key.verify(
            bytes.fromhex(receipt.signer_signature_hex),
            json.dumps(
                receipt.unsigned_payload,
                sort_keys=True,
                separators=(",", ":"),
            ).encode(),
        )
    except (InvalidSignature, ValueError) as error:
        raise ValueError("operational decision ledger signature is invalid") from error


class CommittedOperationalDecisionClient(Protocol):
    """Bound ledger service that owns all signing capabilities internally."""

    def current_raw_ingestor_trust_store_digest(self) -> str: ...

    def current_training_target_source_trust_store_digest(self) -> str: ...

    def issue_operational_deployment_decision(
        self,
        decision_payload: dict[str, object],
        *,
        deployment_bundle_release_approval: DeploymentBundleReleaseApproval,
        deployment_runtime_activation_receipt: (
            DeploymentRuntimeActivationReceipt
        ),
        promotion_deployment_certificate: LedgeredPromotionDeploymentCertificate,
        promotion_evidence: NeuralPriorPromotionEvidence,
        policy: DeployedNeuralPriorPolicy,
        policy_trust_store_digest: str,
        regime_evidence: RegimeClassificationEvidence,
        range_partition_evidence: RangePartitionEvidence,
        range_geometry_contract: RangeGeometryContract | MosaicRangeGeometryContract,
        regime_classifier: NeuralPriorRegimeClassifier,
        input_run: ForecastRunContract,
        range_grid_x_m: Tensor,
        range_grid_y_m: Tensor,
    ) -> OperationalDeploymentDecisionCertificate: ...


@dataclass(frozen=True, init=False, slots=True)
class _EpisodeLedgerOperationalDecisionClient:
    """Sealed capability issued only by an EpisodeLedger instance."""

    _issuer: Callable[..., OperationalDeploymentDecisionCertificate]
    _ledger: object
    _authority_trust_store_path: str | Path
    _raw_ingestor_trust_store_path: str | Path
    _training_target_source_trust_store_path: str | Path

    def __init__(self) -> None:
        raise TypeError(
            "operational decision clients are created by EpisodeLedger"
        )

    def issue_operational_deployment_decision(
        self,
        decision_payload: dict[str, object],
        *,
        deployment_bundle_release_approval: DeploymentBundleReleaseApproval,
        deployment_runtime_activation_receipt: (
            DeploymentRuntimeActivationReceipt
        ),
        promotion_deployment_certificate: LedgeredPromotionDeploymentCertificate,
        promotion_evidence: NeuralPriorPromotionEvidence,
        policy: DeployedNeuralPriorPolicy,
        policy_trust_store_digest: str,
        regime_evidence: RegimeClassificationEvidence,
        range_partition_evidence: RangePartitionEvidence,
        range_geometry_contract: RangeGeometryContract | MosaicRangeGeometryContract,
        regime_classifier: NeuralPriorRegimeClassifier,
        input_run: ForecastRunContract,
        range_grid_x_m: Tensor,
        range_grid_y_m: Tensor,
    ) -> OperationalDeploymentDecisionCertificate:
        return self._issuer(
            decision_payload,
            deployment_bundle_release_approval=(
                deployment_bundle_release_approval
            ),
            deployment_runtime_activation_receipt=(
                deployment_runtime_activation_receipt
            ),
            promotion_deployment_certificate=promotion_deployment_certificate,
            promotion_evidence=promotion_evidence,
            policy=policy,
            policy_trust_store_digest=policy_trust_store_digest,
            regime_evidence=regime_evidence,
            range_partition_evidence=range_partition_evidence,
            range_geometry_contract=range_geometry_contract,
            regime_classifier=regime_classifier,
            input_run=input_run,
            range_grid_x_m=range_grid_x_m,
            range_grid_y_m=range_grid_y_m,
        )

    def current_raw_ingestor_trust_store_digest(self) -> str:
        """Return the root-owned revocation snapshot bound to this client."""

        ledger_module = importlib.import_module(f"{__package__}.ledger")
        store = ledger_module._load_raw_ingestor_trust_store(
            self._raw_ingestor_trust_store_path
        )
        return cast(str, store.content_digest)

    def current_training_target_source_trust_store_digest(self) -> str:
        """Return the root-owned current training-target revocation snapshot."""

        ledger_module = importlib.import_module(f"{__package__}.ledger")
        store = ledger_module._load_training_target_source_trust_store(
            self._training_target_source_trust_store_path
        )
        return cast(str, store.content_digest)

    def _validate_committed_decision(
        self,
        certificate: OperationalDeploymentDecisionCertificate,
        decision_payload: dict[str, object],
    ) -> tuple[
        OperationalDecisionPublicationReceipt,
        OperationalDecisionActivationReceipt,
        OperationalDecisionCommitAuthorizationReceipt,
    ]:
        """Invoke only the exact bound EpisodeLedger's DB-backed verifier."""

        ledger_type = getattr(
            importlib.import_module(f"{__package__}.ledger"),
            "EpisodeLedger",
        )
        if type(self._ledger) is not ledger_type:
            raise TypeError(
                "automatic deployment client is not bound to an EpisodeLedger"
            )
        ledger_type._require_initialized(self._ledger)
        raw_trust_before = self.current_raw_ingestor_trust_store_digest()
        target_trust_before = (
            self.current_training_target_source_trust_store_digest()
        )
        if (
            raw_trust_before != certificate.raw_ingestor_trust_store_digest
            or raw_trust_before
            != decision_payload.get("raw_ingestor_trust_store_digest")
        ):
            raise ValueError(
                "operational decision raw-ingestor trust is no longer current"
            )
        if (
            target_trust_before
            != decision_payload.get(
                "training_target_source_trust_store_digest"
            )
        ):
            raise ValueError(
                "operational decision target-source trust is no longer current"
            )
        authority_trust_store = (
            _load_promotion_deployment_authority_trust_store(
                self._authority_trust_store_path
            )
        )
        expected_index_path = authority_trust_store.ledger_instance_index_paths.get(
            certificate.ledger_instance_digest
        )
        if type(expected_index_path) is not type(Path()):
            raise ValueError(
                "automatic deployment ledger instance has no root-approved index"
            )
        publication, activation, authorization = (
            ledger_type._validate_committed_operational_decision(
            self._ledger,
            certificate,
            decision_payload,
            expected_index_path=expected_index_path,
            authority_trust_store_path=self._authority_trust_store_path,
            )
        )
        _validate_operational_decision_publication_receipt(
            publication,
            certificate=certificate,
            authority_trust_store=authority_trust_store,
        )
        _validate_operational_decision_activation_receipt(
            activation,
            certificate=certificate,
            publication_receipt=publication,
            authority_trust_store=authority_trust_store,
        )
        _validate_operational_decision_commit_authorization_receipt(
            authorization,
            certificate=certificate,
            activation_receipt=activation,
            authority_trust_store=authority_trust_store,
        )
        if self.current_raw_ingestor_trust_store_digest() != raw_trust_before:
            raise ValueError(
                "operational decision raw-ingestor trust changed during validation"
            )
        if (
            self.current_training_target_source_trust_store_digest()
            != target_trust_before
        ):
            raise ValueError(
                "operational decision target-source trust changed during validation"
            )
        return publication, activation, authorization


def _replay_operational_deployment_selection(
    decision_payload: dict[str, object],
    *,
    promotion_deployment_certificate: LedgeredPromotionDeploymentCertificate,
    promotion_evidence: NeuralPriorPromotionEvidence,
    policy: DeployedNeuralPriorPolicy,
    policy_trust_store_digest: str,
    regime_evidence: RegimeClassificationEvidence | None = None,
    range_partition_evidence: RangePartitionEvidence | None = None,
    range_geometry_contract: (
        RangeGeometryContract | MosaicRangeGeometryContract | None
    ) = None,
    allow_committed_routing_evidence: bool = False,
) -> tuple[str, Literal["candidate", "parent"], str, float]:
    """Recompute every decision-critical selection field before signing."""

    regime = decision_payload.get("regime_classification_evidence")
    range_partition = decision_payload.get("range_partition_evidence")
    selection = decision_payload.get("selection")
    retained_policy = decision_payload.get("deployment_policy")
    retained_certificate = decision_payload.get(
        "promotion_deployment_certificate"
    )
    trust = decision_payload.get("policy_trust_store")
    routing_verified = decision_payload.get(
        "routing_semantic_replay_verified"
    )
    if not all(
        isinstance(value, dict)
        for value in (
            regime,
            range_partition,
            selection,
            retained_policy,
            retained_certificate,
            trust,
        )
    ):
        raise ValueError("operational deployment decision is incomplete")
    assert isinstance(regime, dict)
    assert isinstance(range_partition, dict)
    assert isinstance(selection, dict)
    assert isinstance(retained_policy, dict)
    assert isinstance(retained_certificate, dict)
    assert isinstance(trust, dict)
    regime_payload = dict(regime)
    regime_digest = regime_payload.pop("evidence_digest", None)
    range_payload = dict(range_partition)
    range_digest = range_payload.pop("evidence_digest", None)
    expected_policy = policy.payload | {"policy_digest": policy.policy_digest}
    expected_certificate = promotion_deployment_certificate.payload | {
        "certificate_digest": (
            promotion_deployment_certificate.certificate_digest
        )
    }
    if (
        type(promotion_evidence) is not NeuralPriorPromotionEvidence
        or type(policy) is not DeployedNeuralPriorPolicy
        or retained_policy != expected_policy
        or retained_certificate != expected_certificate
        or trust.get("content_digest") != policy_trust_store_digest
        or regime_digest != json_digest(regime_payload)
        or range_digest != json_digest(range_payload)
        or policy.promotion_evidence_digest
        != promotion_evidence.promotion_evidence_digest
        or policy.promotion_deployment_certificate_digest
        != promotion_deployment_certificate.certificate_digest
        or policy.candidate_prior_digest
        != promotion_evidence.candidate_prior_digest
        or policy.parent_prior_digest != promotion_evidence.parent_prior_digest
        or policy.regime_classifier_digest != regime.get("classifier_digest")
        or policy.regime_classifier_digest
        != promotion_evidence.deployment_regime_classifier_digest
        or policy.regime_classifier_manifest_digest
        != promotion_evidence.deployment_regime_classifier_manifest_digest
        or policy.range_geometry_contract_digest
        != range_partition.get("range_geometry_contract_digest")
        or policy.semantic_replay_generation_digest
        != promotion_evidence.semantic_replay_generation_digest
    ):
        raise ValueError("operational deployment decision lineage disagrees")
    if routing_verified is True:
        if not allow_committed_routing_evidence:
            if (
                type(regime_evidence) is not RegimeClassificationEvidence
                or type(range_partition_evidence) is not RangePartitionEvidence
                or type(range_geometry_contract)
                not in (RangeGeometryContract, MosaicRangeGeometryContract)
            ):
                raise ValueError(
                    "candidate routing requires exact semantic replay products"
                )
            RegimeClassificationEvidence.validate_integrity(regime_evidence)
            RangePartitionEvidence.validate_integrity(range_partition_evidence)
            assert range_geometry_contract is not None
            if type(range_geometry_contract) is RangeGeometryContract:
                RangeGeometryContract.validate_integrity(range_geometry_contract)
            else:
                MosaicRangeGeometryContract.validate_integrity(
                    cast(MosaicRangeGeometryContract, range_geometry_contract)
                )
            expected_geometry = range_geometry_contract.payload | {
                "contract_digest": range_geometry_contract.contract_digest
            }
            if (
                regime
                != regime_evidence.payload
                | {"evidence_digest": regime_evidence.evidence_digest}
                or range_partition
                != range_partition_evidence.payload
                | {"evidence_digest": range_partition_evidence.evidence_digest}
                or decision_payload.get("range_geometry_contract")
                != expected_geometry
            ):
                raise ValueError(
                    "operational routing products disagree with the decision"
                )
    elif routing_verified is False:
        if any(
            value is not None
            for value in (
                regime_evidence,
                range_partition_evidence,
                range_geometry_contract,
            )
        ):
            raise ValueError("unverified routing cannot retain semantic products")
        reason = "unverified_routing_evidence"
        role: Literal["candidate", "parent"] = "parent"
        selected_prior = policy.parent_prior_digest
        deployment_margin = 0.0
        if (
            selection.get("fallback_reason") != reason
            or selection.get("selected_role") != role
            or selection.get("selected_prior_digest") != selected_prior
            or float(
                selection.get("deployment_confidence_margin", math.nan)
            )
            != deployment_margin
        ):
            raise ValueError("operational deployment selection replay failed")
        return reason, role, selected_prior, deployment_margin
    else:
        raise ValueError("operational routing replay status is invalid")
    certified = set(
        promotion_evidence.certified_applicability_regime_groups
    )
    active_range_regimes = range_partition.get("active_range_regimes")
    if not isinstance(active_range_regimes, list) or any(
        type(value) is not str for value in active_range_regimes
    ):
        raise ValueError("operational range partition is invalid")
    active_groups = tuple(
        (regime.get("regime"), range_regime)
        for range_regime in active_range_regimes
    )
    confidence = float(regime.get("regime_confidence", -math.inf))
    deployment_margin = confidence - policy.minimum_regime_confidence
    branch_stable = (
        float(regime.get("weather_top1_top2_gap", -math.inf))
        >= policy.minimum_weather_top1_top2_gap
        and deployment_margin >= policy.minimum_deployment_confidence_margin
    )
    if not promotion_evidence.deployment_eligible:
        reason = "promotion_ineligible"
    elif not certified:
        reason = "no_certified_regime"
    elif regime.get("is_ood"):
        reason = "ood_or_abstained"
    elif not branch_stable:
        reason = "ambiguous_classifier_branch"
    elif confidence < policy.minimum_regime_confidence:
        reason = "low_regime_confidence"
    elif policy.range_geometry_contract_digest not in set(
        promotion_evidence.certified_range_geometry_contract_digests
    ):
        reason = "uncertified_range_geometry"
    elif not any(group[0] == regime.get("regime") for group in certified):
        reason = "uncertified_regime"
    elif not active_groups or any(
        group not in certified for group in active_groups
    ):
        reason = "uncertified_range_band"
    else:
        reason = "certified_candidate"
    role: Literal["candidate", "parent"] = (
        "candidate" if reason == "certified_candidate" else "parent"
    )
    selected_prior = (
        policy.candidate_prior_digest
        if role == "candidate"
        else policy.parent_prior_digest
    )
    if (
        selection.get("fallback_reason") != reason
        or selection.get("selected_role") != role
        or selection.get("selected_prior_digest") != selected_prior
        or not math.isclose(
            float(selection.get("deployment_confidence_margin", math.nan)),
            deployment_margin,
            abs_tol=1e-12,
        )
    ):
        raise ValueError("operational deployment selection replay failed")
    return reason, role, selected_prior, deployment_margin


def _issue_operational_deployment_decision_certificate(
    decision_payload: dict[str, object],
    *,
    deployment_bundle_release_approval: DeploymentBundleReleaseApproval,
    deployment_runtime_activation_receipt: DeploymentRuntimeActivationReceipt,
    promotion_deployment_certificate: LedgeredPromotionDeploymentCertificate,
    promotion_evidence: NeuralPriorPromotionEvidence,
    policy: DeployedNeuralPriorPolicy,
    policy_trust_store_digest: str,
    regime_evidence: RegimeClassificationEvidence | None,
    range_partition_evidence: RangePartitionEvidence | None,
    range_geometry_contract: (
        RangeGeometryContract | MosaicRangeGeometryContract | None
    ),
    ledger_receipt: OperationalDecisionLedgerReceipt,
    signer: DeploymentAuthoritySigner,
    authority_trust_store: _PromotionDeploymentAuthorityTrustStore,
) -> OperationalDeploymentDecisionCertificate:
    _validate_deployment_bundle_release_approval(
        deployment_bundle_release_approval,
        authority_trust_store=authority_trust_store,
        required_valid_through=cast(str, decision_payload.get("publication_time")),
        require_deployable=True,
    )
    _validate_deployment_runtime_activation_receipt(
        deployment_runtime_activation_receipt,
        release_approval=deployment_bundle_release_approval,
        authority_trust_store=authority_trust_store,
        required_valid_through=cast(str, decision_payload.get("publication_time")),
    )
    expected_runtime_activation = (
        deployment_runtime_activation_receipt.payload
        | {
            "receipt_digest": (
                deployment_runtime_activation_receipt.receipt_digest
            )
        }
    )
    if (
        decision_payload.get("deployment_bundle_release_approval")
        != deployment_bundle_release_approval.payload
        | {"approval_digest": deployment_bundle_release_approval.approval_digest}
    ):
        raise ValueError("operational decision release approval lineage disagrees")
    if (
        decision_payload.get("deployment_runtime_activation_receipt")
        != expected_runtime_activation
    ):
        raise ValueError(
            "operational decision runtime activation lineage disagrees"
        )
    _validate_ledgered_promotion_deployment_certificate(
        promotion_deployment_certificate,
        authority_trust_store=authority_trust_store,
        promotion_evidence=promotion_evidence,
    )
    policy.validate_integrity()
    issued_at = _canonical_time(signer.signing_time())
    _validate_operational_decision_ledger_receipt(
        ledger_receipt,
        decision_payload=decision_payload,
        authority_trust_store=authority_trust_store,
    )
    _validate_signer(
        signer,
        trust_store=authority_trust_store,
        role="operational_decision",
        issued_at=issued_at,
    )
    if (
        signer.authority_id == promotion_deployment_certificate.authority_id
        or signer.public_key_hex
        == promotion_deployment_certificate.authority_public_key_hex
    ):
        raise ValueError(
            "promotion certification and operational signing require separate authorities"
        )
    if (
        signer.authority_id == deployment_bundle_release_approval.authority_id
        or signer.public_key_hex
        == deployment_bundle_release_approval.authority_public_key_hex
        or signer.authority_id
        == deployment_runtime_activation_receipt.authority_id
        or signer.public_key_hex
        == deployment_runtime_activation_receipt.authority_public_key_hex
    ):
        raise ValueError(
            "release, runtime activation, and operational signing require separate authorities"
        )
    try:
        receipt_payload = json.loads(
            promotion_deployment_certificate.ledger_issuance_receipt_payload_json
        )
        if not isinstance(receipt_payload, dict):
            raise ValueError
        promotion_ledger_receipt = _ledger_issuance_receipt_from_payload(
            receipt_payload
        )
    except (TypeError, ValueError, json.JSONDecodeError) as error:
        raise ValueError("promotion ledger issuance receipt is invalid") from error
    if (
        signer.authority_id == promotion_ledger_receipt.signer_id
        or signer.public_key_hex == promotion_ledger_receipt.signer_public_key_hex
    ):
        raise ValueError(
            "ledger issuance and operational signing require separate authorities"
        )
    observation = _canonical_datetime(
        cast(str, decision_payload.get("observation_valid_time"))
    )
    available = _canonical_datetime(
        cast(str, decision_payload.get("input_available_time"))
    )
    deadline = _canonical_datetime(
        cast(str, decision_payload.get("decision_deadline"))
    )
    publication = _canonical_datetime(
        cast(str, decision_payload.get("publication_time"))
    )
    issued = _canonical_datetime(issued_at)
    if (
        not observation
        <= available
        <= _canonical_datetime(ledger_receipt.accepted_at)
        <= _canonical_datetime(ledger_receipt.committed_at)
        <= _canonical_datetime(ledger_receipt.proof_issued_at)
        <= issued
        <= deadline
        < publication
        or issued
        < _canonical_datetime(promotion_deployment_certificate.issued_at)
        or issued > datetime.now(timezone.utc)
    ):
        raise ValueError("operational decision is outside its prepublication window")
    _replay_operational_deployment_selection(
        decision_payload,
        promotion_deployment_certificate=promotion_deployment_certificate,
        promotion_evidence=promotion_evidence,
        policy=policy,
        policy_trust_store_digest=policy_trust_store_digest,
        regime_evidence=regime_evidence,
        range_partition_evidence=range_partition_evidence,
        range_geometry_contract=range_geometry_contract,
    )
    selection = cast(dict[str, object], decision_payload["selection"])
    values: dict[str, object] = {
        "decision_payload_digest": json_digest(decision_payload),
        "promotion_deployment_certificate_digest": (
            promotion_deployment_certificate.certificate_digest
        ),
        "promotion_evidence_digest": promotion_evidence.promotion_evidence_digest,
        "deployment_policy_digest": policy.policy_digest,
        "deployment_policy_trust_store_digest": policy_trust_store_digest,
        "full_analysis_input_digest": decision_payload.get(
            "full_analysis_input_digest"
        ),
        "analysis_input_derivation_artifact_digest": decision_payload.get(
            "analysis_input_derivation_artifact_digest"
        ),
        "global_raw_resolution_receipt_digest": decision_payload.get(
            "global_raw_resolution_receipt_digest"
        ),
        "resolved_raw_volume_identity_set_digest": decision_payload.get(
            "resolved_raw_volume_identity_set_digest"
        ),
        "analysis_processor_trust_store_digest": decision_payload.get(
            "analysis_processor_trust_store_digest"
        ),
        "raw_ingestor_trust_store_digest": decision_payload.get(
            "raw_ingestor_trust_store_digest"
        ),
        "analysis_input_provenance_commitment_digest": decision_payload.get(
            "analysis_input_provenance_commitment_digest"
        ),
        "deployment_bundle_release_approval_digest": (
            deployment_bundle_release_approval.approval_digest
        ),
        "deployment_runtime_activation_receipt_digest": (
            deployment_runtime_activation_receipt.receipt_digest
        ),
        "deployment_bundle_digest": (
            deployment_runtime_activation_receipt.deployment_bundle_digest
        ),
        "runtime_tree_digest": (
            deployment_runtime_activation_receipt.runtime_tree_digest
        ),
        "interpreter_closure_digest": (
            deployment_runtime_activation_receipt.interpreter_closure_digest
        ),
        "deployment_instance_digest": (
            deployment_runtime_activation_receipt.deployment_instance_digest
        ),
        "host_identity_digest": (
            deployment_runtime_activation_receipt.host_identity_digest
        ),
        "input_plan_digest": decision_payload.get("input_plan_digest"),
        "observation_valid_time": decision_payload.get(
            "observation_valid_time"
        ),
        "input_available_time": decision_payload.get("input_available_time"),
        "decision_deadline": decision_payload.get("decision_deadline"),
        "publication_time": decision_payload.get("publication_time"),
        "operational_cycle_id": decision_payload.get("operational_cycle_id"),
        "selected_prior_digest": selection.get("selected_prior_digest"),
        "selected_role": selection.get("selected_role"),
        "fallback_reason": selection.get("fallback_reason"),
        "operational_ledger_receipt_payload_json": json.dumps(
            ledger_receipt.payload,
            sort_keys=True,
            separators=(",", ":"),
        ),
        "operational_ledger_receipt_digest": ledger_receipt.receipt_digest,
        "ledger_instance_digest": ledger_receipt.ledger_instance_digest,
        "ledger_sequence_number": ledger_receipt.sequence_number,
        "previous_operational_decision_digest": (
            ledger_receipt.previous_operational_decision_digest
        ),
        "issued_at": issued_at,
        "authority_id": signer.authority_id,
        "authority_public_key_hex": signer.public_key_hex,
        "authority_trust_store_digest": authority_trust_store.content_digest,
        "contract": "operational-deployment-decision-certificate-v8",
    }
    signature = signer.sign(
        json.dumps(values, sort_keys=True, separators=(",", ":")).encode()
    ).hex()
    result = object.__new__(OperationalDeploymentDecisionCertificate)
    for name, value in values.items():
        object.__setattr__(result, name, value)
    object.__setattr__(result, "authority_signature_hex", signature)
    object.__setattr__(result, "certificate_digest", json_digest(result.payload))
    return result


def _operational_deployment_decision_certificate_from_payload(
    payload: dict[str, object],
) -> OperationalDeploymentDecisionCertificate:
    expected = {
        field_.name
        for field_ in OperationalDeploymentDecisionCertificate.__dataclass_fields__.values()
        if field_.name != "certificate_digest"
    }
    if set(payload) != expected:
        raise ValueError("operational decision certificate payload is incomplete")
    result = object.__new__(OperationalDeploymentDecisionCertificate)
    for name, value in payload.items():
        object.__setattr__(result, name, value)
    object.__setattr__(result, "certificate_digest", json_digest(result.payload))
    return result


def _validate_operational_deployment_decision_certificate(
    certificate: OperationalDeploymentDecisionCertificate,
    *,
    decision_payload: dict[str, object],
    authority_trust_store: _PromotionDeploymentAuthorityTrustStore,
) -> None:
    selection = decision_payload.get("selection")
    if not isinstance(selection, dict):
        raise ValueError("operational deployment selection is incomplete")
    for name in (
        "decision_payload_digest",
        "promotion_deployment_certificate_digest",
        "promotion_evidence_digest",
        "deployment_policy_digest",
        "deployment_policy_trust_store_digest",
        "full_analysis_input_digest",
        "analysis_input_derivation_artifact_digest",
        "global_raw_resolution_receipt_digest",
        "resolved_raw_volume_identity_set_digest",
        "analysis_processor_trust_store_digest",
        "raw_ingestor_trust_store_digest",
        "analysis_input_provenance_commitment_digest",
        "deployment_bundle_release_approval_digest",
        "deployment_runtime_activation_receipt_digest",
        "deployment_bundle_digest",
        "runtime_tree_digest",
        "interpreter_closure_digest",
        "deployment_instance_digest",
        "host_identity_digest",
        "input_plan_digest",
        "operational_cycle_id",
        "selected_prior_digest",
        "operational_ledger_receipt_digest",
        "ledger_instance_digest",
        "previous_operational_decision_digest",
        "authority_trust_store_digest",
    ):
        _require_digest(name, getattr(certificate, name))
    release_payload = decision_payload.get("deployment_bundle_release_approval")
    runtime_payload = decision_payload.get(
        "deployment_runtime_activation_receipt"
    )
    if not isinstance(release_payload, dict) or not isinstance(runtime_payload, dict):
        raise ValueError("operational runtime activation receipt is missing")
    retained_release_payload = dict(release_payload)
    release_approval_digest = retained_release_payload.pop(
        "approval_digest", None
    )
    release_approval = _deployment_bundle_release_approval_from_payload(
        retained_release_payload
    )
    _validate_deployment_bundle_release_approval(
        release_approval,
        authority_trust_store=authority_trust_store,
        required_valid_through=certificate.publication_time,
        require_deployable=True,
    )
    retained_runtime_payload = dict(runtime_payload)
    runtime_receipt_digest = retained_runtime_payload.pop(
        "receipt_digest", None
    )
    runtime_receipt = _deployment_runtime_activation_receipt_from_payload(
        retained_runtime_payload
    )
    _validate_deployment_runtime_activation_receipt(
        runtime_receipt,
        release_approval=release_approval,
        authority_trust_store=authority_trust_store,
        required_valid_through=certificate.publication_time,
    )
    if (
        type(certificate) is not OperationalDeploymentDecisionCertificate
        or certificate.contract
        != "operational-deployment-decision-certificate-v8"
        or certificate.certificate_digest != json_digest(certificate.payload)
        or certificate.decision_payload_digest != json_digest(decision_payload)
        or certificate.promotion_deployment_certificate_digest
        != cast(dict[str, object], decision_payload["promotion_deployment_certificate"]).get(
            "certificate_digest"
        )
        or certificate.promotion_evidence_digest
        != cast(dict[str, object], decision_payload["deployment_policy"]).get(
            "promotion_evidence_digest"
        )
        or certificate.deployment_policy_digest
        != cast(dict[str, object], decision_payload["deployment_policy"]).get(
            "policy_digest"
        )
        or certificate.deployment_policy_trust_store_digest
        != cast(dict[str, object], decision_payload["policy_trust_store"]).get(
            "content_digest"
        )
        or certificate.full_analysis_input_digest
        != decision_payload.get("full_analysis_input_digest")
        or certificate.analysis_input_derivation_artifact_digest
        != decision_payload.get("analysis_input_derivation_artifact_digest")
        or certificate.global_raw_resolution_receipt_digest
        != decision_payload.get("global_raw_resolution_receipt_digest")
        or certificate.resolved_raw_volume_identity_set_digest
        != decision_payload.get("resolved_raw_volume_identity_set_digest")
        or certificate.analysis_processor_trust_store_digest
        != decision_payload.get("analysis_processor_trust_store_digest")
        or certificate.raw_ingestor_trust_store_digest
        != decision_payload.get("raw_ingestor_trust_store_digest")
        or certificate.analysis_input_provenance_commitment_digest
        != decision_payload.get("analysis_input_provenance_commitment_digest")
        or release_approval_digest != release_approval.approval_digest
        or certificate.deployment_bundle_release_approval_digest
        != release_approval.approval_digest
        or runtime_receipt_digest != runtime_receipt.receipt_digest
        or certificate.deployment_runtime_activation_receipt_digest
        != runtime_receipt.receipt_digest
        or certificate.deployment_bundle_digest
        != runtime_receipt.deployment_bundle_digest
        or certificate.runtime_tree_digest
        != runtime_receipt.runtime_tree_digest
        or certificate.interpreter_closure_digest
        != runtime_receipt.interpreter_closure_digest
        or certificate.deployment_instance_digest
        != runtime_receipt.deployment_instance_digest
        or certificate.host_identity_digest
        != runtime_receipt.host_identity_digest
        or certificate.input_plan_digest != decision_payload.get("input_plan_digest")
        or certificate.observation_valid_time
        != decision_payload.get("observation_valid_time")
        or certificate.input_available_time
        != decision_payload.get("input_available_time")
        or certificate.decision_deadline
        != decision_payload.get("decision_deadline")
        or certificate.publication_time != decision_payload.get("publication_time")
        or certificate.operational_cycle_id
        != decision_payload.get("operational_cycle_id")
        or certificate.selected_prior_digest
        != selection.get("selected_prior_digest")
        or certificate.selected_role != selection.get("selected_role")
        or certificate.fallback_reason != selection.get("fallback_reason")
        or certificate.issued_at != _canonical_time(certificate.issued_at)
    ):
        raise ValueError("operational decision certificate integrity is invalid")
    try:
        operational_receipt_payload = json.loads(
            certificate.operational_ledger_receipt_payload_json
        )
        if not isinstance(operational_receipt_payload, dict):
            raise ValueError
        operational_receipt = _operational_decision_ledger_receipt_from_payload(
            operational_receipt_payload
        )
    except (TypeError, ValueError, json.JSONDecodeError) as error:
        raise ValueError("operational decision ledger receipt is invalid") from error
    _validate_operational_decision_ledger_receipt(
        operational_receipt,
        decision_payload=decision_payload,
        authority_trust_store=authority_trust_store,
    )
    if (
        certificate.operational_ledger_receipt_payload_json
        != json.dumps(
            operational_receipt.payload,
            sort_keys=True,
            separators=(",", ":"),
        )
        or certificate.operational_ledger_receipt_digest
        != operational_receipt.receipt_digest
        or certificate.ledger_instance_digest
        != operational_receipt.ledger_instance_digest
        or certificate.ledger_sequence_number
        != operational_receipt.sequence_number
        or certificate.previous_operational_decision_digest
        != operational_receipt.previous_operational_decision_digest
        or _canonical_datetime(certificate.issued_at)
        < _canonical_datetime(operational_receipt.proof_issued_at)
    ):
        raise ValueError("operational decision ledger lineage disagrees")
    observation = _canonical_datetime(certificate.observation_valid_time)
    available = _canonical_datetime(certificate.input_available_time)
    decision = _canonical_datetime(certificate.issued_at)
    deadline = _canonical_datetime(certificate.decision_deadline)
    publication = _canonical_datetime(certificate.publication_time)
    if (
        not observation
        <= available
        <= _canonical_datetime(operational_receipt.accepted_at)
        <= _canonical_datetime(operational_receipt.committed_at)
        <= _canonical_datetime(operational_receipt.proof_issued_at)
        <= decision
        <= deadline
        < publication
        or decision
        < _canonical_datetime(
            cast(
                str,
                cast(
                    dict[str, object],
                    decision_payload["promotion_deployment_certificate"],
                )["issued_at"],
            )
        )
        or decision > datetime.now(timezone.utc)
    ):
        raise ValueError("operational decision chronology is invalid")
    promotion_payload = cast(
        dict[str, object], decision_payload["promotion_deployment_certificate"]
    )
    try:
        ledger_receipt_payload = json.loads(
            cast(str, promotion_payload["ledger_issuance_receipt_payload_json"])
        )
        if not isinstance(ledger_receipt_payload, dict):
            raise ValueError
        ledger_receipt = _ledger_issuance_receipt_from_payload(
            ledger_receipt_payload
        )
    except (KeyError, TypeError, ValueError, json.JSONDecodeError) as error:
        raise ValueError("operational decision ledger receipt is invalid") from error
    if (
        certificate.authority_id == promotion_payload.get("authority_id")
        or certificate.authority_public_key_hex
        == promotion_payload.get("authority_public_key_hex")
        or certificate.authority_id == ledger_receipt.signer_id
        or certificate.authority_public_key_hex
        == ledger_receipt.signer_public_key_hex
        or certificate.authority_id == operational_receipt.signer_id
        or certificate.authority_public_key_hex
        == operational_receipt.signer_public_key_hex
        or certificate.authority_id == release_approval.authority_id
        or certificate.authority_public_key_hex
        == release_approval.authority_public_key_hex
        or certificate.authority_id == runtime_receipt.authority_id
        or certificate.authority_public_key_hex
        == runtime_receipt.authority_public_key_hex
    ):
        raise ValueError("operational decision authority is not role-separated")
    key = _trusted_authority_key(
        authority_trust_store,
        authority_id=certificate.authority_id,
        public_key_hex=certificate.authority_public_key_hex,
        role="operational_decision",
        issued_at=certificate.issued_at,
    )
    try:
        key.verify(
            bytes.fromhex(certificate.authority_signature_hex),
            json.dumps(
                certificate.unsigned_payload,
                sort_keys=True,
                separators=(",", ":"),
            ).encode(),
        )
    except (InvalidSignature, ValueError) as error:
        raise ValueError(
            "operational decision certificate signature is invalid"
        ) from error


def _select_deployed_prior(
    candidate_runner: NeuralPriorInferenceRunner,
    parent_runner: NeuralPriorInferenceRunner,
    promotion_evidence: NeuralPriorPromotionEvidence,
    promotion_deployment_certificate: LedgeredPromotionDeploymentCertificate,
    regime_evidence: RegimeClassificationEvidence,
    range_partition_evidence: RangePartitionEvidence,
    policy: DeployedNeuralPriorPolicy,
    *,
    regime_classifier: NeuralPriorRegimeClassifier,
    input_run: ForecastRunContract,
    range_grid_x_m: Tensor,
    range_grid_y_m: Tensor,
    range_geometry_contract: RangeGeometryContract | MosaicRangeGeometryContract,
    operational_grid_contract_digest: str,
    operational_frame_shape: tuple[int, int],
    operational_radar_source_kind: str | None = None,
    operational_radar_site_digest: str | None = None,
    operational_radar_site_location_digest: str | None = None,
    operational_input_plan: NeuralPriorInputPlan,
    analysis_input_derivation_artifact_digest: str,
    global_raw_resolution_receipt_digest: str,
    resolved_raw_volume_identity_set_digest: str,
    analysis_processor_trust_store_digest: str,
    policy_trust_store_path: str | Path,
    deployment_certificate_trust_store_path: str | Path,
    deployment_bundle_release_approval: DeploymentBundleReleaseApproval,
    deployment_runtime_activation_receipt: DeploymentRuntimeActivationReceipt,
    operational_decision_client: CommittedOperationalDecisionClient,
) -> tuple[NeuralPriorInferenceRunner, NeuralPriorDeploymentSelection]:
    """Select the candidate only for classifier-attested certified regimes."""

    regime_evidence.validate_integrity()
    range_partition_evidence.validate_integrity()
    range_geometry_contract.validate_integrity()
    if (
        range_partition_evidence.grid_contract_digest
        != operational_grid_contract_digest
        or not range_partition_evidence.masks
        or range_partition_evidence.masks[0].shape
        != operational_frame_shape
        or range_geometry_contract.grid_contract_digest
        != operational_grid_contract_digest
        or range_geometry_contract.contract_digest
        != range_partition_evidence.range_geometry_contract_digest
        or range_geometry_contract.range_regime_labels
        != range_partition_evidence.range_regime_labels
    ):
        raise ValueError("range partition disagrees with operational grid")
    if (
        type(promotion_evidence) is not NeuralPriorPromotionEvidence
        or promotion_evidence.contract
        != "neural-prior-promotion-evidence-v31"
        or type(policy) is not DeployedNeuralPriorPolicy
        or policy.contract != "deployed-neural-prior-policy-v17"
    ):
        raise TypeError("current replay-generation deployment evidence is required")
    policy.validate_integrity()
    trust = _load_learning_policy_trust_store(policy_trust_store_path)
    if policy.policy_digest not in trust.approved_policy_digests:
        raise ValueError("unapproved neural-prior deployment policy")
    if promotion_evidence.promotion_evidence_digest != json_digest(
        promotion_evidence._payload()
    ):
        raise ValueError("neural-prior promotion evidence digest mismatch")
    deployment_authority_trust = (
        _load_promotion_deployment_authority_trust_store(
            deployment_certificate_trust_store_path
        )
    )
    _validate_deployment_runtime_activation_receipt(
        deployment_runtime_activation_receipt,
        release_approval=deployment_bundle_release_approval,
        authority_trust_store=deployment_authority_trust,
        required_valid_through=operational_input_plan.publication_time,
        require_current_runtime=True,
    )
    _validate_ledgered_promotion_deployment_certificate(
        promotion_deployment_certificate,
        authority_trust_store=deployment_authority_trust,
        promotion_evidence=promotion_evidence,
    )
    if type(operational_decision_client) is not _EpisodeLedgerOperationalDecisionClient:
        raise TypeError(
            "automatic deployment requires an EpisodeLedger-bound client"
        )
    raw_ingestor_trust_store_digest = (
        operational_decision_client.current_raw_ingestor_trust_store_digest()
    )
    training_target_source_trust_store_digest = (
        operational_decision_client
        .current_training_target_source_trust_store_digest()
    )
    analysis_input_provenance_commitment_digest = json_digest(
        {
            "contract": "operational-analysis-input-provenance-commitment-v2",
            "analysis_input_derivation_artifact_digest": (
                analysis_input_derivation_artifact_digest
            ),
            "global_raw_resolution_receipt_digest": (
                global_raw_resolution_receipt_digest
            ),
            "resolved_raw_volume_identity_set_digest": (
                resolved_raw_volume_identity_set_digest
            ),
            "analysis_processor_trust_store_digest": (
                analysis_processor_trust_store_digest
            ),
            "raw_ingestor_trust_store_digest": (
                raw_ingestor_trust_store_digest
            ),
        }
    )
    if (
        policy.candidate_prior_digest != candidate_runner.neural_prior_digest
        or policy.parent_prior_digest != parent_runner.neural_prior_digest
        or policy.promotion_evidence_digest
        != promotion_evidence.promotion_evidence_digest
        or policy.promotion_deployment_certificate_digest
        != promotion_deployment_certificate.certificate_digest
        or policy.promotion_deployment_authority_trust_store_digest
        != promotion_deployment_certificate.authority_trust_store_digest
        or policy.regime_classifier_digest != regime_evidence.classifier_digest
        or policy.regime_classifier_digest
        != promotion_evidence.deployment_regime_classifier_digest
        or policy.regime_classifier_manifest_digest
        != promotion_evidence.deployment_regime_classifier_manifest_digest
        or promotion_evidence.candidate_prior_digest
        != candidate_runner.neural_prior_digest
        or promotion_evidence.parent_prior_digest
        != parent_runner.neural_prior_digest
        or policy.range_geometry_contract_digest
        != range_partition_evidence.range_geometry_contract_digest
        or policy.semantic_replay_generation_digest
        != promotion_evidence.semantic_replay_generation_digest
        or promotion_evidence.semantic_replay_generation_digest
        != SEMANTIC_SCORING_REPLAY_GENERATION_DIGEST
        or promotion_deployment_certificate.raw_ingestor_trust_store_digest
        != raw_ingestor_trust_store_digest
        or promotion_deployment_certificate
        .training_target_source_trust_store_digest
        != training_target_source_trust_store_digest
        or promotion_evidence.training_target_source_trust_store_digest
        != training_target_source_trust_store_digest
    ):
        raise ValueError("deployment policy lineage disagrees")
    confidence_ok = regime_evidence.regime_confidence >= policy.minimum_regime_confidence
    deployment_confidence_margin = (
        regime_evidence.regime_confidence - policy.minimum_regime_confidence
    )
    branch_stable = (
        regime_evidence.weather_top1_top2_gap
        >= policy.minimum_weather_top1_top2_gap
        and deployment_confidence_margin
        >= policy.minimum_deployment_confidence_margin
    )
    active_groups = tuple(
        (regime_evidence.regime, range_regime)
        for range_regime in range_partition_evidence.active_range_regimes
    )
    certified = set(promotion_evidence.certified_applicability_regime_groups)
    if not promotion_evidence.deployment_eligible:
        selected = parent_runner
        role: Literal["candidate", "parent"] = "parent"
        reason = "promotion_ineligible"
    elif not promotion_evidence.certified_applicability_regime_groups:
        selected = parent_runner
        role = "parent"
        reason = "no_certified_regime"
    elif regime_evidence.is_ood:
        selected = parent_runner
        role = "parent"
        reason = "ood_or_abstained"
    elif not branch_stable:
        selected = parent_runner
        role = "parent"
        reason = "ambiguous_classifier_branch"
    elif not confidence_ok:
        selected = parent_runner
        role = "parent"
        reason = "low_regime_confidence"
    elif policy.range_geometry_contract_digest not in set(
        promotion_evidence.certified_range_geometry_contract_digests
    ):
        selected = parent_runner
        role = "parent"
        reason = "uncertified_range_geometry"
    elif not any(group[0] == regime_evidence.regime for group in certified):
        selected = parent_runner
        role = "parent"
        reason = "uncertified_regime"
    elif not active_groups or any(group not in certified for group in active_groups):
        selected = parent_runner
        role = "parent"
        reason = "uncertified_range_band"
    else:
        selected = candidate_runner
        role = "candidate"
        reason = "certified_candidate"
    deployment_decision_core: dict[str, object] = {
        "contract": "neural-prior-deployment-decision-artifact-v19",
        "routing_semantic_replay_verified": True,
        "full_analysis_input_digest": regime_evidence.full_analysis_input_digest,
        "analysis_input_derivation_artifact_digest": (
            analysis_input_derivation_artifact_digest
        ),
        "global_raw_resolution_receipt_digest": (
            global_raw_resolution_receipt_digest
        ),
        "resolved_raw_volume_identity_set_digest": (
            resolved_raw_volume_identity_set_digest
        ),
        "analysis_processor_trust_store_digest": (
            analysis_processor_trust_store_digest
        ),
        "raw_ingestor_trust_store_digest": raw_ingestor_trust_store_digest,
        "training_target_source_trust_store_digest": (
            training_target_source_trust_store_digest
        ),
        "analysis_input_provenance_commitment_digest": (
            analysis_input_provenance_commitment_digest
        ),
        "deployment_bundle_release_approval": (
            deployment_bundle_release_approval.payload
            | {
                "approval_digest": (
                    deployment_bundle_release_approval.approval_digest
                )
            }
        ),
        "deployment_runtime_activation_receipt": (
            deployment_runtime_activation_receipt.payload
            | {
                "receipt_digest": (
                    deployment_runtime_activation_receipt.receipt_digest
                )
            }
        ),
        "input_plan_digest": operational_input_plan.plan_digest,
        "observation_valid_time": operational_input_plan.observation_valid_time,
        "input_available_time": operational_input_plan.input_available_time,
        "decision_deadline": operational_input_plan.decision_deadline,
        "publication_time": operational_input_plan.publication_time,
        "operational_cycle_id": json_digest(
            {
                "contract": "advar-operational-cycle-v2",
                "input_plan_digest": operational_input_plan.plan_digest,
                "full_analysis_input_digest": (
                    regime_evidence.full_analysis_input_digest
                ),
                "analysis_input_derivation_artifact_digest": (
                    analysis_input_derivation_artifact_digest
                ),
                "global_raw_resolution_receipt_digest": (
                    global_raw_resolution_receipt_digest
                ),
                "resolved_raw_volume_identity_set_digest": (
                    resolved_raw_volume_identity_set_digest
                ),
            }
        ),
        "operational_grid_contract_digest": operational_grid_contract_digest,
        "operational_frame_shape": list(operational_frame_shape),
        "operational_radar_source_kind": operational_radar_source_kind,
        "operational_radar_site_digest": operational_radar_site_digest,
        "operational_radar_site_location_digest": (
            operational_radar_site_location_digest
        ),
        "regime_classification_evidence": (
            regime_evidence.payload
            | {"evidence_digest": regime_evidence.evidence_digest}
        ),
        "deployment_policy": policy.payload | {"policy_digest": policy.policy_digest},
        "range_partition_evidence": (
            range_partition_evidence.payload
            | {"evidence_digest": range_partition_evidence.evidence_digest}
        ),
        "range_geometry_contract": (
            range_geometry_contract.payload
            | {"contract_digest": range_geometry_contract.contract_digest}
        ),
        "promotion_deployment_certificate": (
            promotion_deployment_certificate.payload
            | {
                "certificate_digest": (
                    promotion_deployment_certificate.certificate_digest
                )
            }
        ),
        "policy_trust_store": {
            "contract": "advar-learning-policy-trust-store-v1",
            "approved_policy_digests": sorted(trust.approved_policy_digests),
            "content_digest": trust.content_digest,
        },
        "selection": {
            "selected_prior_digest": selected.neural_prior_digest,
            "selected_role": role,
            "fallback_reason": reason,
            "deployment_confidence_margin": deployment_confidence_margin,
        },
    }
    operational_decision_certificate = (
        operational_decision_client.issue_operational_deployment_decision(
            deployment_decision_core,
            deployment_bundle_release_approval=(
                deployment_bundle_release_approval
            ),
            deployment_runtime_activation_receipt=(
                deployment_runtime_activation_receipt
            ),
            promotion_deployment_certificate=promotion_deployment_certificate,
            promotion_evidence=promotion_evidence,
            policy=policy,
            policy_trust_store_digest=trust.content_digest,
            regime_evidence=regime_evidence,
            range_partition_evidence=range_partition_evidence,
            range_geometry_contract=range_geometry_contract,
            regime_classifier=regime_classifier,
            input_run=input_run,
            range_grid_x_m=range_grid_x_m,
            range_grid_y_m=range_grid_y_m,
        )
    )
    (
        operational_publication_receipt,
        operational_activation_receipt,
        operational_commit_authorization_receipt,
    ) = operational_decision_client._validate_committed_decision(
        operational_decision_certificate,
        deployment_decision_core,
    )
    deployment_decision_payload = deployment_decision_core | {
        "operational_decision_certificate": (
            operational_decision_certificate.payload
            | {
                "certificate_digest": (
                    operational_decision_certificate.certificate_digest
                )
            }
        ),
        "operational_decision_publication_receipt": (
            operational_publication_receipt.payload
            | {"receipt_digest": operational_publication_receipt.receipt_digest}
        ),
        "operational_decision_activation_receipt": (
            operational_activation_receipt.payload
            | {"receipt_digest": operational_activation_receipt.receipt_digest}
        ),
        "operational_decision_commit_authorization_receipt": (
            operational_commit_authorization_receipt.payload
            | {
                "receipt_digest": (
                    operational_commit_authorization_receipt.receipt_digest
                )
            }
        ),
    }
    deployment_decision_json = json.dumps(
        deployment_decision_payload,
        sort_keys=True,
        separators=(",", ":"),
    )
    selection = _new_neural_prior_deployment_selection(
        selected_prior_digest=selected.neural_prior_digest,
        selected_role=role,
        full_analysis_input_digest=regime_evidence.full_analysis_input_digest,
        promotion_evidence_digest=promotion_evidence.promotion_evidence_digest,
        promotion_deployment_certificate_digest=(
            promotion_deployment_certificate.certificate_digest
        ),
        regime_classification_evidence_digest=regime_evidence.evidence_digest,
        deployment_policy_digest=policy.policy_digest,
        deployment_policy_trust_store_digest=trust.content_digest,
        range_geometry_contract_digest=policy.range_geometry_contract_digest,
        range_partition_evidence_digest=range_partition_evidence.evidence_digest,
        classifier_numerical_runtime_digest=(
            regime_evidence.numerical_runtime_digest
        ),
        classifier_input_dtype=regime_evidence.input_dtype,
        classifier_input_device=regime_evidence.input_device,
        weather_top1_top2_gap=regime_evidence.weather_top1_top2_gap,
        minimum_range_presence_margin=(
            regime_evidence.minimum_range_presence_margin
        ),
        deployment_confidence_margin=deployment_confidence_margin,
        deployment_decision_artifact_json=deployment_decision_json,
        deployment_decision_artifact_digest=json_digest(
            deployment_decision_payload
        ),
        fallback_reason=reason,
    )
    if (
        validate_neural_prior_deployment_decision_artifact(
            selection.deployment_decision_artifact_json,
            deployment_certificate_trust_store_path=(
                deployment_certificate_trust_store_path
            ),
            deployment_policy_trust_store_path=policy_trust_store_path,
            raw_ingestor_trust_store_path=(
                operational_decision_client._raw_ingestor_trust_store_path
            ),
            training_target_source_trust_store_path=(
                operational_decision_client
                ._training_target_source_trust_store_path
            ),
        )
        != selection.deployment_decision_artifact_digest
    ):
        raise ValueError("neural-prior deployment artifact digest mismatch")
    return selected, selection


def validate_neural_prior_deployment_decision_artifact(
    artifact_json: str,
    *,
    expected_operational_grid_contract_digest: str | None = None,
    expected_operational_frame_shape: tuple[int, int] | None = None,
    expected_operational_radar_source_kind: str | None = None,
    expected_operational_radar_site_digest: str | None = None,
    expected_operational_radar_site_location_digest: str | None = None,
    expected_input_plan_digest: str | None = None,
    expected_full_analysis_input_digest: str | None = None,
    expected_analysis_input_derivation_artifact_digest: str | None = None,
    expected_promotion_evidence_digest: str | None = None,
    expected_regime_classification_evidence_digest: str | None = None,
    expected_deployment_policy_digest: str | None = None,
    expected_deployment_selection_digest: str | None = None,
    expected_selected_prior_digest: str | None = None,
    deployment_certificate_trust_store_path: str | Path,
    deployment_policy_trust_store_path: str | Path,
    raw_ingestor_trust_store_path: str | Path,
    training_target_source_trust_store_path: str | Path,
    require_current_runtime: bool = False,
) -> str:
    """Replay a durable classifier/policy/certification deployment choice."""

    ledger_module = importlib.import_module(f"{__package__}.ledger")
    raw_trust_before = ledger_module._load_raw_ingestor_trust_store(
        raw_ingestor_trust_store_path
    ).content_digest
    target_trust_before = (
        ledger_module._load_training_target_source_trust_store(
            training_target_source_trust_store_path
        ).content_digest
    )
    try:
        payload = json.loads(artifact_json)
    except json.JSONDecodeError as error:
        raise ValueError("invalid neural-prior deployment artifact") from error
    if (
        not isinstance(payload, dict)
        or payload.get("contract")
        != "neural-prior-deployment-decision-artifact-v19"
        or json.dumps(payload, sort_keys=True, separators=(",", ":"))
        != artifact_json
    ):
        raise ValueError("neural-prior deployment artifact is not canonical")
    regime = payload.get("regime_classification_evidence")
    policy = payload.get("deployment_policy")
    certificate_payload = payload.get("promotion_deployment_certificate")
    operational_certificate_payload = payload.get(
        "operational_decision_certificate"
    )
    operational_publication_payload = payload.get(
        "operational_decision_publication_receipt"
    )
    operational_activation_payload = payload.get(
        "operational_decision_activation_receipt"
    )
    operational_commit_authorization_payload = payload.get(
        "operational_decision_commit_authorization_receipt"
    )
    runtime_activation_payload = payload.get(
        "deployment_runtime_activation_receipt"
    )
    release_approval_payload = payload.get(
        "deployment_bundle_release_approval"
    )
    range_partition = payload.get("range_partition_evidence")
    range_geometry = payload.get("range_geometry_contract")
    trust = payload.get("policy_trust_store")
    selection = payload.get("selection")
    if not all(
        isinstance(value, dict)
        for value in (
            regime,
            policy,
            certificate_payload,
            operational_certificate_payload,
            operational_publication_payload,
            operational_activation_payload,
            operational_commit_authorization_payload,
            release_approval_payload,
            runtime_activation_payload,
            range_partition,
            range_geometry,
            trust,
            selection,
        )
    ):
        raise ValueError("neural-prior deployment artifact is incomplete")
    assert isinstance(regime, dict)
    assert isinstance(policy, dict)
    assert isinstance(certificate_payload, dict)
    assert isinstance(operational_certificate_payload, dict)
    assert isinstance(operational_publication_payload, dict)
    assert isinstance(operational_activation_payload, dict)
    assert isinstance(operational_commit_authorization_payload, dict)
    assert isinstance(release_approval_payload, dict)
    assert isinstance(runtime_activation_payload, dict)
    assert isinstance(range_partition, dict)
    assert isinstance(range_geometry, dict)
    assert isinstance(trust, dict)
    assert isinstance(selection, dict)
    for provenance_name in (
        "analysis_input_derivation_artifact_digest",
        "global_raw_resolution_receipt_digest",
        "resolved_raw_volume_identity_set_digest",
        "analysis_processor_trust_store_digest",
        "raw_ingestor_trust_store_digest",
        "training_target_source_trust_store_digest",
        "analysis_input_provenance_commitment_digest",
    ):
        provenance_value = payload.get(provenance_name)
        if (
            not isinstance(provenance_value, str)
            or re.fullmatch(r"[0-9a-f]{64}", provenance_value) is None
        ):
            raise ValueError("neural-prior deployment provenance is incomplete")
    certificate_values = dict(certificate_payload)
    certificate_digest = certificate_values.pop("certificate_digest", None)
    try:
        certificate = _ledgered_promotion_deployment_certificate_from_payload(
            certificate_values
        )
    except (TypeError, ValueError) as error:
        raise ValueError(
            "neural-prior deployment certificate is invalid"
        ) from error
    if certificate_digest != certificate.certificate_digest:
        raise ValueError("neural-prior deployment certificate digest mismatch")
    authority_trust_store = _load_promotion_deployment_authority_trust_store(
        deployment_certificate_trust_store_path
    )
    release_approval_values = dict(release_approval_payload)
    release_approval_digest = release_approval_values.pop(
        "approval_digest", None
    )
    try:
        release_approval = _deployment_bundle_release_approval_from_payload(
            release_approval_values
        )
    except (TypeError, ValueError) as error:
        raise ValueError("deployment bundle release approval is invalid") from error
    if release_approval_digest != release_approval.approval_digest:
        raise ValueError("deployment bundle release approval digest mismatch")
    _validate_deployment_bundle_release_approval(
        release_approval,
        authority_trust_store=authority_trust_store,
        required_valid_through=datetime.now(timezone.utc)
        .isoformat()
        .replace("+00:00", "Z"),
        require_deployable=require_current_runtime,
    )
    runtime_activation_values = dict(runtime_activation_payload)
    runtime_activation_digest = runtime_activation_values.pop(
        "receipt_digest", None
    )
    try:
        runtime_activation_receipt = (
            _deployment_runtime_activation_receipt_from_payload(
                runtime_activation_values
            )
        )
    except (TypeError, ValueError) as error:
        raise ValueError(
            "deployment runtime activation receipt is invalid"
        ) from error
    if runtime_activation_digest != runtime_activation_receipt.receipt_digest:
        raise ValueError("deployment runtime activation digest mismatch")
    _validate_deployment_runtime_activation_receipt(
        runtime_activation_receipt,
        release_approval=release_approval,
        authority_trust_store=authority_trust_store,
        required_valid_through=datetime.now(timezone.utc)
        .isoformat()
        .replace("+00:00", "Z"),
        require_current_runtime=require_current_runtime,
    )
    _validate_ledgered_promotion_deployment_certificate(
        certificate,
        authority_trust_store=authority_trust_store,
    )
    operational_certificate_values = dict(operational_certificate_payload)
    operational_certificate_digest = operational_certificate_values.pop(
        "certificate_digest", None
    )
    try:
        operational_certificate = (
            _operational_deployment_decision_certificate_from_payload(
                operational_certificate_values
            )
        )
    except (TypeError, ValueError) as error:
        raise ValueError(
            "operational deployment decision certificate is invalid"
        ) from error
    decision_core = dict(payload)
    decision_core.pop("operational_decision_certificate")
    decision_core.pop("operational_decision_publication_receipt")
    decision_core.pop("operational_decision_activation_receipt")
    decision_core.pop("operational_decision_commit_authorization_receipt")
    if operational_certificate_digest != operational_certificate.certificate_digest:
        raise ValueError("operational decision certificate digest mismatch")
    _validate_operational_deployment_decision_certificate(
        operational_certificate,
        decision_payload=decision_core,
        authority_trust_store=authority_trust_store,
    )
    if (
        payload.get("raw_ingestor_trust_store_digest") != raw_trust_before
        or certificate.raw_ingestor_trust_store_digest != raw_trust_before
        or operational_certificate.raw_ingestor_trust_store_digest
        != raw_trust_before
    ):
        raise ValueError(
            "neural-prior deployment raw-ingestor trust is no longer current"
        )
    if (
        payload.get("training_target_source_trust_store_digest")
        != target_trust_before
        or certificate.training_target_source_trust_store_digest
        != target_trust_before
    ):
        raise ValueError(
            "neural-prior deployment target-source trust is no longer current"
        )
    operational_publication_values = dict(operational_publication_payload)
    operational_publication_digest = operational_publication_values.pop(
        "receipt_digest",
        None,
    )
    try:
        operational_publication = (
            _operational_decision_publication_receipt_from_payload(
                operational_publication_values
            )
        )
    except (TypeError, ValueError) as error:
        raise ValueError(
            "operational decision publication receipt is invalid"
        ) from error
    if operational_publication_digest != operational_publication.receipt_digest:
        raise ValueError("operational publication receipt digest mismatch")
    _validate_operational_decision_publication_receipt(
        operational_publication,
        certificate=operational_certificate,
        authority_trust_store=authority_trust_store,
    )
    operational_activation_values = dict(operational_activation_payload)
    operational_activation_digest = operational_activation_values.pop(
        "receipt_digest",
        None,
    )
    try:
        operational_activation = (
            _operational_decision_activation_receipt_from_payload(
                operational_activation_values
            )
        )
    except (TypeError, ValueError) as error:
        raise ValueError(
            "operational decision activation receipt is invalid"
        ) from error
    if operational_activation_digest != operational_activation.receipt_digest:
        raise ValueError("operational activation receipt digest mismatch")
    _validate_operational_decision_activation_receipt(
        operational_activation,
        certificate=operational_certificate,
        publication_receipt=operational_publication,
        authority_trust_store=authority_trust_store,
    )
    operational_authorization_values = dict(
        operational_commit_authorization_payload
    )
    operational_authorization_digest = operational_authorization_values.pop(
        "receipt_digest",
        None,
    )
    try:
        operational_authorization = (
            _operational_decision_commit_authorization_receipt_from_payload(
                operational_authorization_values
            )
        )
    except (TypeError, ValueError) as error:
        raise ValueError(
            "operational commit authorization receipt is invalid"
        ) from error
    if (
        operational_authorization_digest
        != operational_authorization.receipt_digest
    ):
        raise ValueError("operational commit authorization digest mismatch")
    _validate_operational_decision_commit_authorization_receipt(
        operational_authorization,
        certificate=operational_certificate,
        activation_receipt=operational_activation,
        authority_trust_store=authority_trust_store,
    )
    if require_current_runtime:
        expected_index_path = (
            authority_trust_store.ledger_instance_index_paths.get(
                operational_certificate.ledger_instance_digest
            )
        )
        ledger_type = getattr(ledger_module, "EpisodeLedger")
        if type(expected_index_path) is not type(Path()):
            raise ValueError(
                "automatic deployment ledger instance has no root-approved index"
            )
        committed_ledger = ledger_type._open_existing_index(
            expected_index_path
        )
        (
            committed_publication,
            committed_activation,
            committed_authorization,
        ) = committed_ledger._validate_committed_operational_decision(
            operational_certificate,
            decision_core,
            expected_index_path=expected_index_path,
            authority_trust_store_path=deployment_certificate_trust_store_path,
        )
        if (
            committed_publication.receipt_digest
            != operational_publication.receipt_digest
            or committed_activation.receipt_digest
            != operational_activation.receipt_digest
            or committed_authorization.receipt_digest
            != operational_authorization.receipt_digest
        ):
            raise ValueError(
                "current deployment artifact disagrees with committed ledger"
            )
    promotion_evidence = _decode_current_neural_prior_promotion_evidence(
        certificate.promotion_evidence_payload_json
    )
    if (
        promotion_evidence.training_target_source_trust_store_digest
        != target_trust_before
    ):
        raise ValueError(
            "neural-prior deployment target-source trust is no longer current"
        )
    scoring_certification = (
        promotion_evidence.scoring_backend_certification_policy_digest,
        promotion_evidence.scoring_backend_certification_evidence_digest,
    )
    if (scoring_certification[0] is None) != (
        scoring_certification[1] is None
    ) or any(
        value is not None
        and (not isinstance(value, str) or len(value) != 64)
        for value in scoring_certification
    ):
        raise ValueError("neural-prior scoring certification is incomplete")
    regime_payload = dict(regime)
    regime_digest = regime_payload.pop("evidence_digest", None)
    policy_payload = dict(policy)
    policy_digest = policy_payload.pop("policy_digest", None)
    approved = trust.get("approved_policy_digests")
    external_policy_trust = _load_learning_policy_trust_store(
        deployment_policy_trust_store_path
    )
    try:
        reconstructed_policy = DeployedNeuralPriorPolicy(
            **cast(Any, policy_payload)
        )
    except (TypeError, ValueError) as error:
        raise ValueError(
            "neural-prior deployment artifact policy is invalid"
        ) from error
    range_partition_payload = dict(range_partition)
    range_partition_digest = range_partition_payload.pop("evidence_digest", None)
    range_geometry_payload = dict(range_geometry)
    range_geometry_digest = range_geometry_payload.pop("contract_digest", None)
    geometry_values = dict(range_geometry_payload)
    for name in ("range_regime_labels", "radial_distance_edges_m"):
        value = geometry_values.get(name)
        if not isinstance(value, list):
            raise ValueError("neural-prior deployment artifact is incomplete")
        geometry_values[name] = tuple(value)
    for name in ("radar_site_digests", "radar_site_location_digests"):
        value = geometry_values.get(name)
        if value is not None:
            if not isinstance(value, list):
                raise ValueError("neural-prior deployment artifact is incomplete")
            geometry_values[name] = tuple(value)
    if "radar_projected_xy_m" in geometry_values:
        geometry_values["radar_projected_xy_m"] = tuple(
            tuple(point) for point in geometry_values["radar_projected_xy_m"]
        )
    try:
        reconstructed_geometry = (
            MosaicRangeGeometryContract(**cast(Any, geometry_values))
            if geometry_values.get("contract")
            == "mosaic-horizontal-range-geometry-contract-v3"
            else RangeGeometryContract(**cast(Any, geometry_values))
        )
    except (TypeError, ValueError) as error:
        raise ValueError(
            "neural-prior deployment artifact range geometry is invalid"
        ) from error
    if (
        not isinstance(regime_digest, str)
        or json_digest(regime_payload) != regime_digest
        or not isinstance(policy_digest, str)
        or reconstructed_policy.policy_digest != policy_digest
        or not isinstance(approved, list)
        or policy_digest not in external_policy_trust.approved_policy_digests
        or json_digest(
            {
                "contract": trust.get("contract"),
                "approved_policy_digests": sorted(approved),
            }
        )
        != trust.get("content_digest")
        or policy.get("promotion_deployment_certificate_digest")
        != certificate.certificate_digest
        or policy.get("promotion_deployment_authority_trust_store_digest")
        != certificate.authority_trust_store_digest
        or policy.get("promotion_evidence_digest")
        != promotion_evidence.promotion_evidence_digest
        or policy.get("candidate_prior_digest")
        != promotion_evidence.candidate_prior_digest
        or policy.get("parent_prior_digest")
        != promotion_evidence.parent_prior_digest
        or policy.get("contract") != "deployed-neural-prior-policy-v17"
        or policy.get("semantic_replay_generation_digest")
        != promotion_evidence.semantic_replay_generation_digest
        or promotion_evidence.scoring_replay_contract
        != SEMANTIC_SCORING_REPLAY_CONTRACT
        or promotion_evidence.scoring_replay_method
        != SEMANTIC_SCORING_REPLAY_METHOD
        or promotion_evidence.semantic_replay_generation_digest
        != SEMANTIC_SCORING_REPLAY_GENERATION_DIGEST
        or policy.get("regime_classifier_digest")
        != regime.get("classifier_digest")
        or promotion_evidence.deployment_regime_classifier_digest
        != regime.get("classifier_digest")
        or policy.get("regime_classifier_manifest_digest")
        != promotion_evidence.deployment_regime_classifier_manifest_digest
        or not isinstance(range_partition_digest, str)
        or json_digest(range_partition_payload) != range_partition_digest
        or not isinstance(range_geometry_digest, str)
        or json_digest(range_geometry_payload) != range_geometry_digest
        or reconstructed_geometry.contract_digest != range_geometry_digest
        or policy.get("range_geometry_contract_digest")
        != range_partition.get("range_geometry_contract_digest")
        or range_geometry_digest
        != range_partition.get("range_geometry_contract_digest")
        or range_geometry.get("grid_contract_digest")
        != range_partition.get("grid_contract_digest")
        or range_geometry.get("range_regime_labels")
        != range_partition.get("range_regime_labels")
        or payload.get("full_analysis_input_digest")
        != regime.get("full_analysis_input_digest")
        or payload.get("analysis_input_provenance_commitment_digest")
        != json_digest(
            {
                "contract": (
                    "operational-analysis-input-provenance-commitment-v2"
                ),
                "analysis_input_derivation_artifact_digest": payload.get(
                    "analysis_input_derivation_artifact_digest"
                ),
                "global_raw_resolution_receipt_digest": payload.get(
                    "global_raw_resolution_receipt_digest"
                ),
                "resolved_raw_volume_identity_set_digest": payload.get(
                    "resolved_raw_volume_identity_set_digest"
                ),
                "analysis_processor_trust_store_digest": payload.get(
                    "analysis_processor_trust_store_digest"
                ),
                "raw_ingestor_trust_store_digest": payload.get(
                    "raw_ingestor_trust_store_digest"
                ),
            }
        )
        or payload.get("operational_cycle_id")
        != json_digest(
            {
                "contract": "advar-operational-cycle-v2",
                "input_plan_digest": payload.get("input_plan_digest"),
                "full_analysis_input_digest": payload.get(
                    "full_analysis_input_digest"
                ),
                "analysis_input_derivation_artifact_digest": payload.get(
                    "analysis_input_derivation_artifact_digest"
                ),
                "global_raw_resolution_receipt_digest": payload.get(
                    "global_raw_resolution_receipt_digest"
                ),
                "resolved_raw_volume_identity_set_digest": payload.get(
                    "resolved_raw_volume_identity_set_digest"
                ),
            }
        )
    ):
        raise ValueError("neural-prior deployment artifact lineage disagrees")
    if (
        "operational_radar_source_kind" not in payload
        or "operational_radar_site_digest" not in payload
        or "operational_radar_site_location_digest" not in payload
        or
        payload.get("operational_grid_contract_digest")
        != range_partition.get("grid_contract_digest")
        or payload.get("operational_frame_shape")
        != range_partition.get("grid_shape")
    ):
        raise ValueError(
            "neural-prior deployment artifact disagrees with operational grid"
        )
    if (
        expected_operational_grid_contract_digest is not None
        and payload.get("operational_grid_contract_digest")
        != expected_operational_grid_contract_digest
    ) or (
        expected_operational_frame_shape is not None
        and payload.get("operational_frame_shape")
        != list(expected_operational_frame_shape)
    ) or (
        expected_operational_radar_source_kind is not None
        and payload.get("operational_radar_source_kind")
        != expected_operational_radar_source_kind
    ) or (
        expected_operational_radar_site_digest is not None
        and payload.get("operational_radar_site_digest")
        != expected_operational_radar_site_digest
    ) or (
        expected_input_plan_digest is not None
        and payload.get("input_plan_digest") != expected_input_plan_digest
    ) or (
        expected_operational_radar_site_location_digest is not None
        and payload.get("operational_radar_site_location_digest")
        != expected_operational_radar_site_location_digest
    ) or (
        expected_full_analysis_input_digest is not None
        and payload.get("full_analysis_input_digest")
        != expected_full_analysis_input_digest
    ) or (
        expected_analysis_input_derivation_artifact_digest is not None
        and payload.get("analysis_input_derivation_artifact_digest")
        != expected_analysis_input_derivation_artifact_digest
    ) or (
        expected_promotion_evidence_digest is not None
        and promotion_evidence.promotion_evidence_digest
        != expected_promotion_evidence_digest
    ) or (
        expected_regime_classification_evidence_digest is not None
        and regime_digest != expected_regime_classification_evidence_digest
    ) or (
        expected_deployment_policy_digest is not None
        and policy_digest != expected_deployment_policy_digest
    ) or (
        expected_selected_prior_digest is not None
        and selection.get("selected_prior_digest")
        != expected_selected_prior_digest
    ):
        raise ValueError(
            "neural-prior deployment artifact disagrees with current forecast run"
        )
    _replay_operational_deployment_selection(
        decision_core,
        promotion_deployment_certificate=certificate,
        promotion_evidence=promotion_evidence,
        policy=reconstructed_policy,
        policy_trust_store_digest=external_policy_trust.content_digest,
        allow_committed_routing_evidence=True,
    )
    reconstructed_selection = _new_neural_prior_deployment_selection(
        selected_prior_digest=selection["selected_prior_digest"],
        selected_role=selection["selected_role"],
        full_analysis_input_digest=payload["full_analysis_input_digest"],
        promotion_evidence_digest=promotion_evidence.promotion_evidence_digest,
        promotion_deployment_certificate_digest=certificate.certificate_digest,
        regime_classification_evidence_digest=regime_digest,
        deployment_policy_digest=policy_digest,
        deployment_policy_trust_store_digest=external_policy_trust.content_digest,
        range_geometry_contract_digest=range_geometry_digest,
        range_partition_evidence_digest=range_partition_digest,
        classifier_numerical_runtime_digest=regime["numerical_runtime_digest"],
        classifier_input_dtype=regime["input_dtype"],
        classifier_input_device=regime["input_device"],
        weather_top1_top2_gap=regime["weather_top1_top2_gap"],
        minimum_range_presence_margin=regime["minimum_range_presence_margin"],
        deployment_confidence_margin=selection["deployment_confidence_margin"],
        deployment_decision_artifact_json=artifact_json,
        deployment_decision_artifact_digest=json_digest(payload),
        fallback_reason=selection["fallback_reason"],
    )
    if (
        expected_deployment_selection_digest is not None
        and reconstructed_selection.selection_digest
        != expected_deployment_selection_digest
    ):
        raise ValueError(
            "neural-prior deployment artifact selection disagrees with forecast run"
        )
    if (
        ledger_module._load_raw_ingestor_trust_store(
            raw_ingestor_trust_store_path
        ).content_digest
        != raw_trust_before
    ):
        raise ValueError(
            "raw-ingestor trust store changed during deployment replay"
        )
    if (
        ledger_module._load_training_target_source_trust_store(
            training_target_source_trust_store_path
        ).content_digest
        != target_trust_before
    ):
        raise ValueError(
            "target-source trust store changed during deployment replay"
        )
    return json_digest(payload)


def _validate_operational_range_geometry_source(
    source_identity: OperationalDataIdentity,
    range_geometry_contract: RangeGeometryContract | MosaicRangeGeometryContract,
) -> None:
    """Bind static radar-source identity to its physical range geometry."""

    if type(range_geometry_contract) is RangeGeometryContract:
        if source_identity.radar_source_kind != "single_site":
            raise ValueError(
                "single-radar range geometry cannot be used with a mosaic source"
            )
        if (
            source_identity.radar_site_digest
            != range_geometry_contract.radar_site_digest
            or source_identity.radar_site_location_digest
            != range_geometry_contract.radar_site_location_digest
        ):
            raise ValueError("range geometry disagrees with operational radar site")
    elif type(range_geometry_contract) is MosaicRangeGeometryContract:
        if (
            source_identity.radar_source_kind != "mosaic"
            or source_identity.radar_source_contract_digest
            != range_geometry_contract.source_radar_registry_digest
            or source_identity.source_selection_policy_digest
            != range_geometry_contract.source_selection_policy_digest
        ):
            raise ValueError("mosaic range geometry disagrees with source identity")
    else:
        raise TypeError("unsupported operational range geometry")


def infer_deployed_neural_prior(
    frames_dbz: Tensor,
    *,
    qc_valid_mask: Tensor,
    quality_weight: Tensor,
    observation_std_dbz: Tensor,
    input_run: ForecastRunContract,
    candidate_runner: NeuralPriorInferenceRunner,
    parent_runner: NeuralPriorInferenceRunner,
    promotion_evidence: NeuralPriorPromotionEvidence,
    promotion_deployment_certificate: LedgeredPromotionDeploymentCertificate,
    regime_classifier: NeuralPriorRegimeClassifier,
    range_geometry_contract: RangeGeometryContract | MosaicRangeGeometryContract,
    grid_x_m: Tensor,
    grid_y_m: Tensor,
    source_radar_index_map: Tensor | None = None,
    input_history_source_radar_index_map: Tensor | None = None,
    outage_mask: Tensor | None = None,
    dynamic_qc_valid_mask: Tensor | None = None,
    policy: DeployedNeuralPriorPolicy,
    policy_trust_store_path: str | Path,
    deployment_certificate_trust_store_path: str | Path,
    deployment_bundle_release_approval: DeploymentBundleReleaseApproval,
    deployment_runtime_activation_receipt: DeploymentRuntimeActivationReceipt,
    operational_decision_client: CommittedOperationalDecisionClient,
    mps_backend_certification: MPSBackendCertificationEvidence | None = None,
    mps_backend_certification_policy: (
        MPSBackendCertificationPolicy | None
    ) = None,
) -> NeuralPriorApplication:
    """Classify, select, and infer without accepting caller-provided labels."""

    input_run.validate_integrity()
    if frames_dbz.device.type == "mps":
        raise ValueError(
            "operational MPS deployment requires a model-scoring certificate"
        )
    if (
        input_run.grid_time_contract_digest is None
        or range_geometry_contract.grid_contract_digest
        != input_run.grid_time_contract_digest
    ):
        raise ValueError("range geometry disagrees with operational grid")
    if (
        grid_x_m.shape != frames_dbz.shape[-2:]
        or grid_y_m.shape != frames_dbz.shape[-2:]
    ):
        raise ValueError("range coordinates disagree with radar frames")
    if input_run.operational_data_identity_json is None:
        raise ValueError("operational neural prior requires radar source identity")
    source_identity = OperationalDataIdentity.from_json(
        input_run.operational_data_identity_json
    )
    _validate_operational_range_geometry_source(
        source_identity,
        range_geometry_contract,
    )
    if source_identity.radar_source_kind == "single_site":
        if input_history_source_radar_index_map is not None:
            raise ValueError("single-site inference cannot accept mosaic history")
        source_available_mask = torch.ones_like(
            qc_valid_mask, dtype=torch.bool
        )
    else:
        if (
            input_history_source_radar_index_map is None
            or input_history_source_radar_index_map.dtype != torch.int64
            or input_history_source_radar_index_map.shape != frames_dbz.shape
            or input_history_source_radar_index_map.device != frames_dbz.device
        ):
            raise ValueError(
                "mosaic learned inference requires time-resolved source history"
            )
        source_available_mask = input_history_source_radar_index_map >= 0
    if (
        input_run.source_available_mask_digest is None
        or tensor_digest(source_available_mask)
        != input_run.source_available_mask_digest
    ):
        raise ValueError("learned source availability disagrees with the input run")
    if input_run.input_plan_json is None or input_run.input_plan_digest is None:
        raise ValueError("operational neural prior requires a bound input plan")
    if (
        input_run.analysis_input_derivation_artifact_json is None
        or input_run.analysis_input_derivation_artifact_digest is None
    ):
        raise ValueError(
            "operational neural prior requires committed analysis provenance"
        )
    try:
        derivation_payload = json.loads(
            input_run.analysis_input_derivation_artifact_json
        )
        if not isinstance(derivation_payload, dict):
            raise TypeError
        processor_id = cast(str, derivation_payload["processor_id"])
        processor_public_key_hex = cast(
            str,
            derivation_payload["processor_public_key_hex"],
        )
        processor_signature_hex = cast(
            str,
            derivation_payload["processor_signature_hex"],
        )
        processed_at = cast(str, derivation_payload["processed_at"])
        global_raw_resolution_receipt_digest = cast(
            str,
            derivation_payload["global_raw_resolution_receipt_digest"],
        )
        raw_identities = cast(
            list[str],
            derivation_payload["canonical_raw_volume_identity_digests"],
        )
        if (
            derivation_payload["contract"]
            != "analysis-input-derivation-artifact-v5"
            or derivation_payload["source_available_mask_digest"]
            != input_run.source_available_mask_digest
            or derivation_payload["learned_model_input_features_digest"]
            != input_run.learned_model_input_features_digest
        ):
            raise ValueError
    except (KeyError, TypeError, ValueError, json.JSONDecodeError) as error:
        raise ValueError("operational analysis provenance is invalid") from error
    authority_trust = _load_promotion_deployment_authority_trust_store(
        deployment_certificate_trust_store_path
    )
    processor_key = _trusted_authority_key(
        authority_trust,
        authority_id=processor_id,
        public_key_hex=processor_public_key_hex,
        role="analysis_processor",
        issued_at=processed_at,
    )
    derivation_unsigned = dict(derivation_payload)
    derivation_unsigned.pop("processor_signature_hex", None)
    try:
        processor_key.verify(
            bytes.fromhex(processor_signature_hex),
            json_digest(derivation_unsigned).encode("ascii"),
        )
    except (InvalidSignature, ValueError) as error:
        raise ValueError(
            "operational analysis processor signature is invalid"
        ) from error
    resolved_raw_volume_identity_set_digest = json_digest(
        {
            "contract": "resolved-raw-volume-identity-set-v1",
            "identity_digests": sorted(raw_identities),
        }
    )
    try:
        input_plan_values = json.loads(input_run.input_plan_json)
        if not isinstance(input_plan_values, dict):
            raise TypeError
        input_plan_values = dict(input_plan_values)
        valid_times = input_plan_values.get("valid_times")
        if not isinstance(valid_times, list):
            raise TypeError
        input_plan_values["valid_times"] = tuple(valid_times)
        operational_input_plan = NeuralPriorInputPlan(**cast(Any, input_plan_values))
    except (TypeError, ValueError, json.JSONDecodeError) as error:
        raise ValueError("operational input plan cannot be reconstructed") from error
    if operational_input_plan.plan_digest != input_run.input_plan_digest:
        raise ValueError("operational input-plan digest disagrees")
    if (
        regime_classifier.learned_input_feature_contract
        != LEARNED_RADAR_INPUT_FEATURE_CONTRACT
    ):
        raise ValueError(
            "automatic deployment requires the current classifier input contract"
        )
    regime_evidence = regime_classifier.classify(
        frames_dbz,
        input_run=input_run,
        qc_valid_mask=qc_valid_mask,
        quality_weight=quality_weight,
        observation_std_dbz=observation_std_dbz,
        source_available_mask=source_available_mask,
    )
    if type(range_geometry_contract) is RangeGeometryContract:
        range_partition_evidence = resolve_range_geometry(
            range_geometry_contract,
            grid_x_m=grid_x_m,
            grid_y_m=grid_y_m,
        )
    elif type(range_geometry_contract) is MosaicRangeGeometryContract:
        if (
            source_radar_index_map is None
            or source_identity.source_radar_index_map_digest
            != tensor_digest(source_radar_index_map)
            or outage_mask is None
            or dynamic_qc_valid_mask is None
            or outage_mask.dtype is not torch.bool
            or dynamic_qc_valid_mask.dtype is not torch.bool
            or outage_mask.shape != source_radar_index_map.shape
            or dynamic_qc_valid_mask.shape != source_radar_index_map.shape
            or outage_mask.device != source_radar_index_map.device
            or dynamic_qc_valid_mask.device != source_radar_index_map.device
            or source_identity.outage_mask_digest != tensor_digest(outage_mask)
            or source_identity.dynamic_qc_valid_mask_digest
            != tensor_digest(dynamic_qc_valid_mask)
        ):
            raise ValueError("mosaic range geometry disagrees with source identity")
        range_partition_evidence, effective_horizontal_range_m = (
            resolve_mosaic_range_geometry(
            range_geometry_contract,
            grid_x_m=grid_x_m,
            grid_y_m=grid_y_m,
            source_radar_index_map=source_radar_index_map,
            )
        )
        if (
            source_identity.effective_horizontal_range_map_digest
            != tensor_digest(effective_horizontal_range_m)
        ):
            raise ValueError("mosaic effective range disagrees with source identity")
        range_partition_evidence = restrict_range_partition_domain(
            range_partition_evidence,
            valid_range_domain_mask=(
                (source_radar_index_map >= 0)
                & ~outage_mask
                & dynamic_qc_valid_mask
            ),
        )
    else:
        raise TypeError("unsupported operational range geometry")
    runner, selection = _select_deployed_prior(
        candidate_runner,
        parent_runner,
        promotion_evidence,
        promotion_deployment_certificate,
        regime_evidence,
        range_partition_evidence,
        policy,
        regime_classifier=regime_classifier,
        input_run=input_run,
        range_grid_x_m=grid_x_m,
        range_grid_y_m=grid_y_m,
        range_geometry_contract=range_geometry_contract,
        operational_grid_contract_digest=input_run.grid_time_contract_digest,
        operational_frame_shape=(
            int(frames_dbz.shape[-2]),
            int(frames_dbz.shape[-1]),
        ),
        operational_radar_source_kind=source_identity.radar_source_kind,
        operational_radar_site_digest=source_identity.radar_site_digest,
        operational_radar_site_location_digest=(
            source_identity.radar_site_location_digest
        ),
        operational_input_plan=operational_input_plan,
        analysis_input_derivation_artifact_digest=(
            input_run.analysis_input_derivation_artifact_digest
        ),
        global_raw_resolution_receipt_digest=(
            global_raw_resolution_receipt_digest
        ),
        resolved_raw_volume_identity_set_digest=(
            resolved_raw_volume_identity_set_digest
        ),
        analysis_processor_trust_store_digest=authority_trust.content_digest,
        policy_trust_store_path=policy_trust_store_path,
        deployment_certificate_trust_store_path=(
            deployment_certificate_trust_store_path
        ),
        deployment_bundle_release_approval=(
            deployment_bundle_release_approval
        ),
        deployment_runtime_activation_receipt=(
            deployment_runtime_activation_receipt
        ),
        operational_decision_client=operational_decision_client,
    )
    return runner._infer_deployed(
        frames_dbz,
        input_run=input_run,
        deployment_selection=selection,
        qc_valid_mask=qc_valid_mask,
        quality_weight=quality_weight,
        observation_std_dbz=observation_std_dbz,
        source_available_mask=source_available_mask,
    )
